	//
	//     ★当たり判定は**1次元**のまま（★主役の足元の高さだけを見る）。
	//     ★★見るのは「**いま描いているコマの、絵のてっぺんの高さ**」——
	//       ★★★`enemyFrame()` を通すので、**描いている絵と必ず同じコマ**です
	//       （★2026-08-22 と 08-31 に2度踏んだ「数字だけ動いて絵が動かない」を構造で塞ぐ）。
	//
