	//     3. ★★★**地面にいるコマの決まりを変えないこと**（★跳べば素通り ＝ 全障害物の土台）
	//     4. ★★**`AOSURA_AIR_MARGIN` を勝手に 0 にしないこと**（★避けようがない位相が出ます）
	//     5. ★`AOSURA_AIR_ON = 0` で、2026-09-05 までの見え方（★素通り）に戻る
	var AOSURA_AIR_ON  = 1;     // ★1 = 飛び上がりに当たる / 0 = 昔どおり（跳べば素通り）
