	//     name   … 呼び名（★画面には出ません）
	//     weight … ★出やすさ（★大きいほどよく出る。★0 にするとその並びは出ない）
	//     rows   … 何段か。★1段なら1つ、2段なら2つ書く
	//       n    … 何枚並べるか
	//       step … となりまでの距離（ドット）
	//       lift … ★★高さ。**「跳んで届くいちばん上」を 1.00 とした割合**
	//              （★直書きしない ＝ 島さんが跳躍の絵を変えたら、高さも追従する）
	//
	//   ★★★**どの段も、必ず水平にそろいます**（★同じ地面を基準に置くため）。
	//
	//   ■ ★高さの目安（★いま「跳んで届くいちばん上」は 25ドット）
	//       0.55 … ★一段ジャンプの**途中**で通る高さ（★走っていては届かない）
	//       1.00 … ★一段ジャンプの**てっぺん**
	//       1.60 … ★★**二段ジャンプでしか届かない**（★一段のてっぺんより 15 上）
	// ★★★★2026-08-23、島さんが `tools/preview-picks.html` で**見ながら決めた形**
	//
	//   ★実測（★置き方を1ドットずつ・二回目を1コマずつ全部試した結果）:
	//
	//     並び    出やすさ  枚数   幅   一段で  二段で   高さ
	//     ふつう      81%     5枚    53      4      5     25
	//     短い        8%     3枚    25    ★3      3     25
	//     2段         4%    10枚    45      5   ★10     25,35
	//     3段         4%    24枚    75      5     18     25,35,45
	//     ★６段       4%    60枚    95      5     22     25,35,45,55,65,75
	//
	//   ★★★**６段の上2段（65 と 75）は、二段ジャンプでも届きません**
	//     （★二段でいちばん高い足元は **50**。★拾える余裕は ±8）。
	//     ★★これは**見えているのに取れない**形 ＝ ★★★`TODO.md` の**D案（マグネット）**の場所。
	//     ★島さんが**そのつもりで置いたのか**は確かめていません（→ 引き継ぎ）。
	//
	//   ★★決めるページ: **`tools/preview-picks.html`**（★見ながら直せます）
	var PICK_PATTERNS = [
		// Same formations at every magnet level: growing changes what you can reach.
		// Full rows / full columns only. No diagonals, junctions or symbol shapes.
		{ name: "短い水平", phase: 0, weight: 1, rows: [{ n: 3, step: 12, lift: 0.72 }] },
		{ name: "短い垂直", phase: 0, weight: 1, rows: [{ n: 1, step: 12, lift: 0.56 }, { n: 1, step: 12, lift: 1.12 }, { n: 1, step: 12, lift: 1.68 }] },
		{ name: "離れた水平二列", phase: 1, weight: 1, rows: [{ n: 4, step: 12, lift: 0.8 }, { n: 4, step: 12, lift: 1.92 }] },
		{ name: "垂直二列", phase: 1, weight: 1, rows: [{ n: 2, step: 24, lift: 0.56 }, { n: 2, step: 24, lift: 1.16 }, { n: 2, step: 24, lift: 1.76 }, { n: 2, step: 24, lift: 2.36 }] },
		{ name: "水平四列", phase: 2, weight: 1, rows: [{ n: 5, step: 12, lift: 0.56 }, { n: 5, step: 12, lift: 1.36 }, { n: 5, step: 12, lift: 2.16 }, { n: 5, step: 12, lift: 2.96 }] },
		{ name: "垂直四列", phase: 2, weight: 1, rows: [{ n: 4, step: 12, lift: 0.56 }, { n: 4, step: 12, lift: 1.16 }, { n: 4, step: 12, lift: 1.76 }, { n: 4, step: 12, lift: 2.36 }, { n: 4, step: 12, lift: 2.96 }] },
		{ name: "余白", phase: 3, weight: 0, rest: true, rows: [] }
	];

	// ============================================================
	// ■■■ ★★★★ゴールの扉 —— ★★5000m のエンディング（2026-08-22 島さんの指定）■■■
	// ============================================================
	//
	//   > 島さん「距離10000ｍで一旦エンディングにしたい。いい感じの。」
	//   > 島さん「**B案で扉を使いましょう。その後は②へ。
	//   >   エンディング(ショートカット可)を見たあと「CONTINUE」で先へ。**」
	//
	//   ★★★★2026-08-23、島さんの指定で **10000m → 5000m** へ動きました:
	//   > 島さん「エンディングは5000ｍにします。関係する扉周りの設定も。コイン出現なども。」
	//
	//     ★★変えたのは**距離だけ**です（★仕組み・演出・クレジットは1ドットも変えていない）。
	//     ★あわせて動かしたもの: ★`PICK_FROM_M`（拾えるコイン）と
	//       ★`js/shell.js` のテストモード（★TEST 4950m）
	//
	//   ★★★**これは下の「扉と鍵」（`GATE_ON`。★いまも保留中）とは別物です。**
	//
	//     | | 扉と鍵（`GATE_ON = 0`・保留中） | ★★ゴールの扉（これ） |
	//     |---|---|---|
	//     | 役目 | ★**通せんぼ**（鍵が無いと行き止まり） | ★★**到達点**（着いたら必ず開く） |
	//     | 場所 | 140m | ★★**5000m** |
	//     | 鍵 | ★要る | ★★**要らない** |
	//
	//   ★★★**AIへ: `GATE_ON` を 1 に戻さないこと。** ★あちらは保留のままです。
	//     ★借りているのは**絵だけ**（`js/gate-art.js`。★これも仮の絵）。
	//
	// ■ ★★もとの 10000m は「実測してから」決めた距離でした（★当てずっぽうではない）
	//
	//     かかる時間     … ★★**約13分**（育てながら走った場合。★何も買わないと24分）
	//     くぐる障害物   … 約380〜400個
	//     そのときの育ち … SPEED Lv18 / STAMINA Lv18 / COIN Lv35 あたり
	//     届くか         … ★ミス5%までのプレイなら **8回中7回**届く。
	//                      ★ミス10%だと 4000〜6500m で力尽きる
	//
	//   ★★★**そのうえで島さんが 5000m に決めました**（2026-08-23）。
	//     ★上の実測でいちばん引っかかっていたのが**「13分は長い」**でした
	//       （★★ミス10%のプレイは 4000〜6500m で力尽きる ＝ **届かない人がいた**）。
	//     ★★5000m は**その手前**なので、★★★**同じ腕前でも届くようになる**。
	//     ★かかる時間の目安 … ★★**約6分半**（★育てながら走った場合）
	//
	//   → ★★★**「上手い人だけが見られる」ではなく「ちゃんと育てた人が見られる」**位置。
	//   ★おまけ: 封印してある技（KICKFLIP / POP ＝ 220,000）は
	//     **3000m の手前でお金が届く** ＝ ★道中で技が戻ってくる
	//
	// ■ ★エンディングの段取り（★★どこでもタップで**ショートカット**できる）
	//
	//     ① 扉が開く（`GOAL_OPEN_MS`）
	//     ② ★★**白い光が広がる**（`GOAL_LIGHT_MS`）
	//     ③ まん中に3行 … CONGRATULATIONS / 5000M / CONTINUE（★点滅）
	//        （★数字は `GOAL_M` から作るので、★★**距離を変えても自動で追従**します）
	//     ④ ★もう一度タップ ＝ **CONTINUE**。★育てたものはそのままで、**その先へ**
	//
	//   ★★★**暗転（GAMEOVER）は黒、こちらは白。★対にしてあります。**
	//     ★どちらも「横の行を `FADE_ORDER` の順に塗る」やり方。★半透明は使いません
	//     （→ `OVER_FADE_MS` の説明。★重ねると 33色の外の色が出るため）
	//
	//   ★★★**CONTINUE で育てたものを消さないこと**（島さんの指定「その後は②へ」）。
	//     ★6分半かけて組んだビルドが、**達成した直後に消える**のがいちばん痛い。
	//     ★消えるのは、これまでどおり **GAMEOVER のときだけ**
	// ============================================================
	var GOAL_ON       = 1;       // ★0 にすると仕組みごと止まる（★扉も出ない）
	// ★★★★ここを変えたら、いっしょに動かすものが3つあります（★ばらけると意味が壊れる）:
	//     ① `PICK_FROM_M`（2026-09-10: 序盤から出す指定で0に変更。GOAL_Mとは独立）
	//     ② `js/shell.js` の `startM`（★テストモード。★ゴールの50m手前）
	//     ③ ★画面の文字は `{M}` で自動（★手で書き換えない）
	var GOAL_M        = 5000;    // ★★ここに扉が立っている（メートル）★2026-08-23 島さんの指定
	var GOAL_OPEN_MS  = 600;     // ★①扉が開いたのを見せる時間
	var GOAL_LIGHT_MS = 900;     // ★②白い光が広がりきるまで
	var C_GOAL_LIGHT  = 29;      // ★★白（★GAMEOVER の黒と対）
	var C_GOAL_TITLE  = 17;      // ★1行目。17=赤（★GAMEOVER の文字と同じ色 ＝ 対の関係）
	var C_GOAL_TEXT   = 9;       // ★2行目以降。9=まっ黒（★白地なので黒が読みやすい）
	var GOAL_BLINK_MS = 450;     // ★CONTINUE が点いたり消えたりする間隔
	// ============================================================
	// ★★★★ページは4秒で切り替わる（2026-08-23 島さんの指定）
	// ============================================================
	//
	//   > 島さん「エンディングでページが切り替わるのは4秒間に設定してください。
	//   >   画面タップでの省略は可能だがタップ音は必要ないです。
	//   >   切り替わる効果としてフェードインとフェードアウトを入れてください。」
	//
	//   ★★★**フェードに半透明は使いません**（★この世界の色が濁るため）。
	//     ★暗転・白い光とまったく同じ「**横の行を塗る**」やり方（`FADE_ORDER`）で、
	//     ★★**白く覆っていく／覆いを外していく**ことで、出入りを作っています。
	//
	//   ★★★**最後のページは自動で進みません**（★`CONTINUE` を待つ ＝ 島さんが決めた形）
	var GOAL_PAGE_MS  = 4000;    // ★★1ページを見せる長さ（島さんの指定「4秒間」）
	var GOAL_FADE_MS  = 350;     // ★出るとき・消えるときの片道
	// ★★★★扉の前後、これだけ**何も置かない**（メートル）。2026-08-23 島さんの指定
	//   > 島さん「扉前後20ｍは障害物などおかないようにしてください。」
	//   ★★「など」＝ ★コーン・★丘の敵・★拾えるコイン **全部**。
	//   ★★★13分走った先の**到達の瞬間**を、★障害物で邪魔しないため
	var GOAL_CLEAR_M  = 20;

	// ============================================================
	// ■■■ ★★★★二段ジャンプを授かる（2026-08-22 島さんの指定）■■■
	// ============================================================
	//
	//   > 島さん「エンディングでコンテニュー後画面タップで暗転し
	//   >   一秒後画面に JUNP の文字表示お願いします。
