	//   ★★★**出す数字は、必ず「実際に変わった量」から作ること**（島さんの指定）。
	//     表示だけ別に直書きすると、あとで倍率を変えたときに
	//     **「実際は +1.0 なのに画面は +0.5」**という同期バグが必ず起きる
	var POP_ON       = 1;     // 0 にするとポップアップが出なくなる
	var POP_MS       = 800;   // ★1つが出ている長さ（ミリ秒）
	var POP_RISE     = 16;    // ★その間に上へ何ドット上がるか
