	//   ★★★★★2026-09-12、島さんが**「ぼかし・拡大を使わない」制限を外しました**。
	//     ★だから ②⑥ は**本物のぼかし**（`ctx.filter`）を使います。
	//     ★★使ったあとは**必ず `none` と `1` に戻すこと**
