	//   ★2026-08-16、ここは倍率だった。★★倍率が消えたので**コインそのもの**を出す
	var GAIN_FLASH_MS = 260;  // 跳ねている長さ
	var C_COIN      = 16;     // ふだんの色。16=生成り
	var C_COIN_UP   = 19;     // ★増えた瞬間。19=黄色
	// ★★扉に止められたときに扉が光る色（2026-08-16）。16=生成り（いちばん明るい）
	var C_GATE_FLASH = 16;

