	var HIT_FLASH_ON     = 1;
	var HIT_FLASH_FRAMES = 1;    // ★★何コマ光らせるか（★島さんの指定は1）
	// ★★★★光る色（2026-08-27、島さんが**赤（純）**を選んだ）
	//   > 桜井資料「フラッシングは手応えと**状態変化の表現**（無敵=白、掴まれ無敵=黄 など
	//   >   **意味を持たせる**）」（出典: フラッシング / `03-graphics.md`）
	//
	//   ★★★**この作品では、白はもう別の意味に使われています**:
	//     ・MAXdrink の全回復 … ★**白い点滅**（★良いこと）
	//     ・ゴールの光        … ★**白**（★良いこと）
	//   ★★だからダメージも白にすると、**良いことと悪いことが同じ見え方**になります。
	//
	//   ★実測（★ふだんの画面の明るさ 0.378）:
	//     赤（純）#e00000 … 明るさ 0.158 / ★変化 0.220 / ★★**消えるドット 0.0%**
	//     白      #fcf5fd … 明るさ 0.931 / 変化 0.552 / ★★消えるドット **9.1%**（鳥・コーンの白）
	//   ★★桃は却下（★背景と明るさがほぼ同じで、光ったと分からない）
	var C_HIT_FLASH      = 25;   // ★25=赤（純）#e00000

	// ============================================================
	// ★★★★★昼と夜 —— 時間の概念（2026-09-02 島さんの指定）
	// ============================================================
	//
	//   > 島さん「ゲーム内に時間の概念を取り入れたい。昼から夜にかけて #00007a の色を
	//   >   Multiply で Opacity10％から画面全体に一番手前のレイヤーとして徐々にかけていく。
	//   >   Opacity70％を完全な夜とする。一旦、昼一分間プレイ後に夜をスタートしようか。
	//   >   色の制限は外す。」
	//
	//   ★★**画像編集ソフトの「乗算レイヤー」とまったく同じもの**を、
	//     ★液晶ぜんぶに1枚かぶせます（★`globalCompositeOperation = "multiply"`）。
	//
	//   ■ ★★★乗算だと何が起きるか（★#00007a は 赤0 / 緑0 / 青122）
	//
	//     赤 … ×0（★消える）  緑 … ×0（★消える）  青 … ×0.478（★半分ほど残る）
	//     → ★★**「暗くなって、青だけが残る」** ＝ そのまま夜の見え方になります。
	//     ★★★**新しい色を一つも選んでいません**（★島さんが決めた1色だけ）。
	//
	//   ■ ★濃さ（Opacity）ごとに、画面の色がどうなるか
	//
	//        濃さ    赤と緑     青
	//        10%     ×0.90    ×0.95     ← ★夜のはじまり
	//        40%     ×0.60    ×0.79
	//        70%     ×0.30    ×0.64     ← ★★完全な夜
	//
	//   ■ ★★★★「色の制限は外す」は島さんの指定です（2026-09-02）
	//
	//     ★この作品は 42色（`js/palette.js`）だけで作ってきましたが、
	//     ★★乗算は**42色の外の色を作ります**（★画面ぜんぶが対象）。
	//     ★★★これは島さんが**承知のうえで外した**もの。★**AIが勝手に戻さないこと。**
	//     ★★きらめきの半透明（`SPARK_DIM_ALPHA`）に続く、2つ目の例外です。
	//
	//   ■ ★★時計は「プレイしている時間」（★距離ではない）
	//
	//     ★島さんの指定が「昼**一分間プレイ**後」なので、**時間**で数えます。
	//     ★★一時停止・お店・READY・エンディングのあいだは**進みません**
	//       （★`st.animMs` とまったく同じ場所で進めるので、2か所に持たない）。
	//     ★★★死んだら昼に戻ります（★コイン・レベル・技と同じ「そのランのあいだだけ」）
	var NIGHT_ON       = 1;          // ★0 で仕組みごと止まる（★ずっと昼になる）
	var NIGHT_COLOR    = "#00007a";  // ★★島さんが決めた色（★パレットの外）
	var NIGHT_START_MS = 60000;      // ★★昼のあいだ（★島さんの指定「昼一分間」）
	// ★★★暮れていく長さ（★★島さんの持ち場。★AIが仮に 1分 を置いた）
	//   ★短くすると急に暗くなり、長くすると気づかないうちに暮れます
	var NIGHT_FADE_MS  = 60000;
	// ★★★★2026-09-03、島さんの指定で **0 から**始めるようにした
	//   > 島さん「夜の始まりの段差は段差がわからないくらい徐々に。」
	//   ★★前は 60秒ちょうどで **0% → 10%** に跳んでいました（★明るさ 0.379 → 0.304）。
	//   ★★★**0 にすると、段差そのものが無くなります**（★1コマの変化 0.019%）。
	//     ★0.10 に戻すと、また跳びます（★島さんの最初の指定はこちらでした）
	var NIGHT_A0       = 0;          // ★★夜のはじまり（★島さんの指定「段差がわからないくらい」）
	var NIGHT_A1       = 0.70;       // ★★★完全な夜（★島さんの指定「Opacity70％」）
	// ============================================================
	// ★★★★★朝に戻る（2026-09-03 島さんの指定）
	// ============================================================
	//   > 島さん「朝にもどす。←夜を一分間プレイ後。」
	//
	//   ★★これで**時間が一周まわります**（★前は夜のまま一方通行でした）:
	//
	//        昼 60秒 → 暮れる 60秒 → ★夜 60秒 → 明ける 60秒 → 昼 …（くり返し）
	//        ────────────────── 一周 4分 ──────────────────
	//
	//   ★**明ける長さは、暮れる長さと同じ**（`NIGHT_FADE_MS` を両方で使う）。
	//     ★★数字を2つに分けないこと（★片方だけ直して、行きと帰りが食い違う事故を防ぐ）
	//   ★★★`NIGHT_LOOP = 0` にすると、**夜のまま止まります**（2026-09-02 までの形）
	var NIGHT_HOLD_MS  = 60000;      // ★★完全な夜のまま続く長さ（★島さんの指定「一分間」）
	var NIGHT_LOOP     = 1;          // ★★★朝に戻ってくり返すか
	// ============================================================
	// ★★★★★情報と光るものには、夜をかけない（2026-09-03 島さんの指定）
	// ============================================================
	//
	//   > 島さん「距離、コイン所持枚数、コイン取得時表示、HP、ショップメニュー、
	//   >   グラインドエフェクトの火花。これらを夜の影響をどの程度入れるか入れないかを
