	//
	//   ★★前は島さんの指定どおり**画面全体**にかけていましたが、
	//     ★実測したら、この作品自身の決まり（**明るさの比 1.5倍以上**）を下回っていました:
	//
	//        距離の文字 2.23倍 → ★1.31倍    コインの数字 2.23倍 → ★1.31倍
	//        お店（いちばん強い差）9.57倍 → ★1.98倍    火花 2.13倍 → ★1.30倍
	//
	//   ★★★**外すと、昼より見やすくなります**（★後ろの世界だけが暗くなるため）:
	//        距離の文字 2.23倍 → ★★9.37倍　　火花 2.13倍 → ★★10.08倍
	//
	//   ★★★★火花を外すのには、この作品に**前例**があります:
	//     ★`js/parts.js` の「**光もの**」の層は、**フィルターを通さない**
	//     （★★「夜の窓あかり・星のために残してある」と島さんが書いています）。
	//     ★★★火花は**自分で光っているもの**なので、夜に負けるほうが不自然です
	//
	//   ★★外したもの（＝夜の**上**に出る）:
	//     ★距離 / コインの枚数 / 頭上の +18 / HP バー / お店 /
	//     ★GAMEOVER / エンディング / ダメージのフラッシュ / ★★トラックの火花
	//   ★夜がかかるもの（＝世界）:
	//     ★空・山・地面・背景の部品・障害物・レール・主役・
	//     ★跳ぶけむり・着地のけむり・きらめき・拾えるコイン
	//
	//   ★★★★**AIへ: この2つを勝手に 1 に戻さないこと**（★決めたのは島さんです）。
	//     ★戻すときは、`test/screen.test.js`【4.5】の表もいっしょに直すこと
	var NIGHT_OVER_UI    = 0;   // ★情報（文字・HP・お店）に夜をかけるか
	var NIGHT_OVER_TRACK = 0;   // ★★トラックの火花に夜をかけるか

	// ============================================================
	// ★★★★★空気遠近法（かすみ）—— ★★まだ止めてあります（2026-09-11）
	// ============================================================
	//
	//   > **島さん「地面より奥のレイヤーとして screen で fcf5fd を 0〜50%（要調整）を
	//   >   いれるのはどうだろう。ただし今の夜や雨に影響しないよう。」**
	//   > **島さん「空気遠近法は各レイヤーごとに割合を変えた方がよいかな？」**
	//
	//   ★★**まだ島さんが見比べている途中です。`HAZE_ON = 0` で完全に止めてあります**
	//     （★0 のあいだ、画面は1ドットも変わりません）。
	//     ★決めるページ: **`tools/preview-haze.html`**
	//
	//   ■ ★★★なぜ「各レイヤーごと」が正しいのか
	//
	//     ★空気遠近法は「**遠いものほど霞む**」。★★1枚かぶせるだけでは、
	//     ★★★空も手前の森も**同じだけ**霞んでしまい、遠近が出ません。
	//
	//   ■ ★★★★だから「順に少しずつ重ねる」形にしてあります
	//
	//     ```
	//     空を描く      → かすみ①      ← ★空は ①+②+③+④ ぶん霞む（いちばん奥）
	//     遠山を描く    → かすみ②      ← ★遠山は ②+③+④
	//     丘の帯を描く  → かすみ③      ← ★丘は ③+④
	//     背景の部品    → かすみ④      ← ★部品は ④ だけ
	//     ─────────────── ★ここから手前は霞ませない ───────────────
	//     地面 → コーン → 主役
	//     ```
	//     ★★1つ1つは小さな数でよく、★★★**奥ほど自動的に濃くなります**。
	//
	//   ■ ★★★★★夜と雨には影響させない（島さんの指定）
	//
	//     ★かすみは**夜（乗算）より手前で描く**ので、放っておくと夜にも残ります。
	//     → ★**夜が濃くなるほど、かすみを消す**（`HAZE_NIGHT_OFF`）。
	//     ★★雨のときも消す（`HAZE_RAIN_OFF`）。
	//
	//     ★★★★**`nightAlpha()` は「読むだけ」**。★★ここに何かを足さないこと
	//       （★星・青スライム・キャンプボタンが同じものを見ています。
	//        ★★足すと昼に星が出ます ＝ 2026-09-06 に実際に確かめた事故）。
	//
	//   ■ ★★★夜空の星は崩れません（★島さん「今の夜空の星は素晴らしいので崩したくない」）
	//
	//     ★星は**夜（乗算）の手前**に screen で描きます（2026-09-05(13)）。
	//     ★★かすみは**ずっと奥**（地面より前）なので、描く場所がそもそも違います。
	//     ★★★そのうえ**完全な夜では かすみ = 0**（上の決まり）なので、
	//       ★**星が出ている時間帯には、かすみは1ドットも描かれません**。
	//
	//   ■ ★★42色の外の色ができます（★星・夜・きらめきに続く例外）
	//     ★★★入れるかどうかは**島さんが決めること**です。
	var HAZE_ON     = 1;          // ★★1 にすると効きます（★いまは止めてある）
	var HAZE_COLOR  = "#fcf5fd";  // ★島さんの指定（★29 = 白）
	// ★かぶせる量（★奥から順に。★★小さくてよい ＝ 重なって濃くなる）
	var HAZE_SKY    = 0.25;   // ① 空のうしろ
	var HAZE_FAR    = 0.25;   // ② 遠山・ランドマークのうしろ
	var HAZE_MID    = 0.25;   // ③ 丘の帯のうしろ
	var HAZE_NEAR   = 0.25;   // ④ 背景の部品のうしろ
	var HAZE_NIGHT_OFF = 1;   // ★1 = 夜になるほど消える（★島さんの指定）
	var HAZE_RAIN_OFF  = 1;   // ★1 = 雨のときも消える（★島さんの指定）

	// ============================================================
	// ★★★★★2026-09-04、**キャンプモード**（★島さんの指定）
	// ============================================================
	//
	//   > 島さん「夜になったらキャンプボタン出現。キャンプモードを選択できる。
	//   >   これまで越えたモンスターの種類と数が表示され、素材としてアイテムボックスに入る。」
	//
	//   ★★島さんが決めた2つ（2026-09-04）:
	//     ① ★**入口は「液晶の外のボタン」**（★原案どおり。★世界の中の焚き火ではない）
	//     ② ★★★**数は死んだら消える／種類は永久に残る**
	//
	//   ■ ★★★★なぜ「種類だけ」残してよいのか（★ここがこの機能の芯）
	//
	//     ★2026-08-16、島さんは「**残るのは BEST だけ**」と決めました。
	//     ★★では BEST はなぜ残ってよいのか ——
	//       ★★★**あれは「強さ」ではなく「どこまで行けたか」という足跡**だからです。
	//
	//     ★同じ理屈で「**どのモンスターに会ったか**」も足跡であって、強さではありません。
	//     ★★だから残せます。★★★**力になるものは1つも残らない**（★数は消える）。
	//
	//     → ★「残るのは BEST だけ」を壊すのではなく、
	//       ★★**「残るのは"記録"だけ」へ広げる**だけで済みます。
	//
	//   ■ ★★AIへ: この6つを守ること
	//
	//     1. ★★★★**数（`st.met`）を永久に残さないこと**（★コイン・レベルと同じで死ねば消える）。
	//        ★★★**種類（`metKinds`）を「強さ」に変えないこと**（★変えた瞬間に上の理屈が崩れる）
	//     2. ★★★**旧キャンプ（`CAMP_ON`、817行）を 1 に戻さないこと。**
	//        ★あちらは「そこで旅を終えて店へ戻る＝清算」で、★★**清算という概念は
	//        いまのゲームにもう存在しません**。★★★名前が同じだけの別ものです。
	//        ★骨組み（世界を止める・選ぶ）は借りる。★★仕様は借りない
	//     3. ★★**数える処理を、払う処理と離さないこと**（★同じ1か所の中で数える）。
	//        ★★★離すと「片方だけ直す」事故が起きます
	//        （★2026-09-02、レールで**当たり判定は外したのに払い出しを外し忘れた**のと同じ罠）
	//     4. ★★**世界の止め方は「お店とまったく同じ」**（★`update()` の early return に相乗り）。
	//        ★★★これで **`st.dayMs`（夜の時計）も自動的に止まります**
	//        ＝ ★「キャンプに長く居るほど夜が長くなる」は**構造として起きません**
	//     5. ★★**テストモードでは覚えないこと**（★`saveCoins` などと同じ `if (testMode) return;`）
	//     6. ★★`CAMPMODE_ON = 0` で仕組みごと止まる（★ボタンも出ない）
	//
	//   ■ ★★★いつボタンが出るか
	//
	//     ★島さんの言葉は「**夜になったら**」。★★この作品で「夜のはじまり」とは
	//     ★★★**暮れはじめ**（＝ `nightAlpha() > 0` になる瞬間 ＝ 走り出しから60秒）です
	//     （★`NIGHT_A0` のコメントに「夜のはじまり」と書いてあるのが、その定義）。
	//     ★実測: ふつうの人のランは平均409秒なので、★★**夜には必ず届きます**
	var CAMPMODE_ON = 1;      // ★0 で仕組みごと止まる（★ボタンも出ない）
	var CAMP_KEY    = "dotollie-met";   // ★★会った種類を覚えておく場所（★BEST と同じ扱い）

