	//
	//   ★★**形が小さくなり始めてから**（＝2段目以降）、消えるまでのあいだ、
	//     ★★★**細かく点いたり消えたり**します。
	//
	//   ■ ★★★粒ごとに「位相」をずらしてある（★ここが要）
