	                       //     （★実測: 星46 ＋ 火花39 ＋ けむり5 ＝ 90。★倍の余裕を取った）
	                       //   ★★★2026-08-31、24 → 40 → **64**（★トラックの火花が出続けるため）
	                       //   ★★狭いと、★★★**火花が跳ぶけむり・着地のけむりを押し出します**
	                       //     （★実測: 40 のとき火花だけで39粒 ＝ ほぼ満杯だった）
	// ★★★★粒の色（★島さんの指定「1ドットの緑二〜三種」）★島さんの持ち場
