	//     （★★★単色では、どこかで必ず背景に溶けます → きらめきと同じ）。
	//
	//   ■ ★★★実測（★粒が実際に通った 16,290ドットの背景を数えて選びました）
	//     ★粒のまわりに多い背景は **丘かげ #1e9674（明るさ0.48）が 36.9%** ／
