	var DUST_COLS  = [39, 33, 12];
	var C_DUST_LATE = 12;  // ★消える直前の色。12=暗い緑（★すっと沈むように消える）
	// ★★★半透明の粒を混ぜる（★島さんの指定「半透明も(可)」）
	//   ★★きらめきと**同じ例外**です（★ほかの場所へ広げないこと）
	//
	//   ★★★**消えていく粒は、必ず薄くなります**（★これが「フワッと」の正体）。
	//     ★そのうえで、はじめから薄い粒を `DUST_DIM_RATE` の割合で混ぜます。
	//   ★★実測で 0.5（半々）から下げました:
