	var LAND_EDGE  = 11;   // ★★ボードの幅は19ドット（★これで必ず外へ出る）    // ★ボードの端まで何ドットか（★ここから外向きに散る）
	var LAND_SPREAD = 2;   // ★出る場所のよこのばらつき（★±このドット）
