	//
	//     ★★★これは、この作品の芯（★**地形を配列に貯めない**）とまったく同じ形です。
	//       ★天気を覚えておく変数は**1つもありません**。
	var RAIN_ON      = 1;      // ★★0 にすると仕組みごと止まる（★降水量も 0 になる）
	// ★★降水量のうねり1つぶんの長さ（ドット）。★大きいほど、天気がゆっくり変わる
	var RAIN_PERIOD  = 3600;
