	// ★★★★★2026-09-12、**軌道が不自然だったのを直しました**（島さんの指摘）
	//
	//   > **島さん「雨粒で軌道と速度が不自然なものが含まれたので直して」**
	//
	//   ★前は**落ちる速さだけ**を遅くしていました。★★ところが横への流れ（★走る速さ）は
	//     そのままだったので、★★★**遅い粒だけが極端に寝て**見えていました。
	//
	//   ★実測（★画面の上で、実際に粒を追いかけて測った傾き。★垂直が 0度）:
	//
	//   ```
	//   ふつうの粒   … 中央 **19.5度**（9.8〜28.4）
	//   ★ゆっくりの粒 … 中央 **32.4度**（19.5〜★★**40.6**）  ← ★★★ここ
	//   ```
	//
	//   ★★★★**一つの雨の中で、傾きが 2 種類に割れていた**のです。
	//     ★実物の雨は、同じ風の中では**ほぼ同じ角度**で降ります。
	//     ★★別々の角度で降ると「雨」ではなく「**別の何かが飛んでいる**」に見えます。
	//
	//   ★★★★★**直し方: ゆっくりの粒は「遅い粒」ではなく「★遠くを降っている粒」にした**
	//
	//     ★遠くのものは、**落ちるのも・横に流れるのも、同じだけ遅く見えます**。
	//     ★★だから `vx` も `vy` も `par`（★流れる速さ）も、**同じ割合で遅く**します。
	//     ★★★すると**傾きはそのまま**で、★**速さだけが遅い** ＝ 遠くの雨になります。
	//
	//     ★すじの長さも同じ割合で短くします。
	//       ★★すじは「★★★**速さのぶんだけ伸びた残像**」なので、
	//       ★遅く見える粒が同じ長さのすじを引くのは★★**棒が飛んでいる**ように見えます。
	//
	//   ★★実測（★直したあと）はこのすぐ下の `addRain()` にあります。
	//
	//   ★★★★**速さは「1本ごと」に決めます**（★1つぶごとではない）。
	//     ★すじの中の粒は**必ず同じ速さ**（★★★ここを 1 つぶごとにするとすじがほどけます）。
	//
	//   ★★AI へ: ★★★**`par` を 1 に戻さないこと**（★戻すと、また遅い粒だけが寝ます）。
	var RAIN_SLOW_RATE  = 0;     // ★★遠くを降っているすじの割合（★0 = 混ぜない ＝ 昔どおり）
	var RAIN_SLOW_SCALE = 0.55;  // ★★★その見かけの速さ（★近くの何割か。★1 に近いほど差が小さい）

	var RAIN_SPAWN_Y = -2;     // ★どこから降ってくるか（★画面の上のすぐ外）
	// ★★右のほうが空かないように、画面の外からも降らせる
	//   （★粒は落ちながら後ろへ流れるので、右端が空きます）
	var RAIN_SPAWN_X = 70;
	// ★★雨粒の色 ★★★島さんの持ち場（★どれも 42色の中）
	//   ★★★**実測で選びました**（★「水色だから」で選ばない ＝ つぶまきの決まり）:
	//
	//       29 白 #fcf5fd … ★★溶けるのは **10.3%**   ← ★採用
	//       16 生成り     … ★★**10.3%**              ← ★採用
	//       15 明るい灰   … ★★★**62.8% 溶ける**      ← ★外した
	//        8 空色       … ★★★**63.9% 溶ける**      ← ★外した（★空とまったく同じ色）
	//       21 水色       … ★★★**64.3% 溶ける**      ← ★外した（★空とほぼ同じ明るさ）
	//
	//   ★★この画面は**空が半分**（★#3ebde0 と #29adff で 51.2%）を占めます。
	//     ★★★だから「水色っぽい雨」は、**空に溶けて消えます**。
	var RAIN_COLS    = [29, 16];
	var RAIN_DIM_RATE = 0.45;  // ★★薄い粒の割合（★これが「近くの雨・遠くの雨」を作る）
	var RAIN_DIM_ALPHA = 0.45; // ★★★雨だけの薄さ（★けむり・星とは分けてある）

	// ============================================================
	// ★★★★★降水量で、乗算レイヤーが濃くなる（★島さんの指定）
	// ============================================================
	//
	//   > **島さん「乗算レイヤーは降水量により薄くなったり濃くなったり。自然に。」**
	//
	//   ★★**夜とまったく同じ1枚**（★#00007a）を、**降水量のぶんだけ濃くします**。
	//     ★★★重ねる枚数は**いまも1枚のまま**です
	//       （★2枚にすると、★★濃さを数える場所が2つになります ＝ この作品の禁じ手）。
	//
	//   ■ ★★★★★ここでいちばん大事なこと ── **`nightAlpha()` に足してはいけません**
	//
	//     ★`nightAlpha()` は「**いま何時か**」を表しています。★★これを見ているのは:
	//
	//         ★夜空の星が出るか      （`updateStars`）
	//         ★★青スライムが出るか  （`isFullNight`）
	//         ★★★キャンプボタンが出るか（`isNightNow`）
	//
	//     → ★★★★雨を足すと、★**昼にどしゃ降りが来ただけで
	//       「夜が来た」ことになり**、★★**昼間に星が出て、青スライムが出ます**。
	//
	//     ★だから、**画面を暗くする濃さ**（`skyDarkAlpha`）と
	//       **いま何時か**（`nightAlpha`）を、★★**別々にしてあります**。
	var RAIN_DARK    = 0.30;   // ★★いちばん強い雨のときに、どれだけ濃くするか
	// ★★★濃さの上限（★夜（0.70）＋雨 でも、ここまで）
	//   ★1.0 まで許すと**まっ暗**になって、夜の雨で何も見えなくなります
	var RAIN_DARK_MAX = 0.80;
	// ============================================================
	// ★★★★★雨の夜は、星が減る（2026-09-06 島さんの指定）
	// ============================================================
	//
	//   > **島さん「夜で雨の時は星の数を減らした方が自然」**
	//
	//   ★★そのとおりです。★雨が降っている ＝ **空が雲に覆われている**ので、
	//     ★★★星は見えないのが本当のところです。
	//
	//   ■ ★★どうやって減らすか ── **新しく生まれる数を減らすだけ**
	//     ★すでに出ている星は**消しません**（★パッと消えると不自然）。
	//     ★★寿命（3〜9秒）が来た順に、★★★**自然にまばらになっていきます**。
	//     ★雨がやめば、また少しずつ増えます（★同じ道を逆にたどる）。
	//
	//   ■ ★1 = どしゃ降りで**星が1つも生まれない** ／ ★★0 = 減らさない（★昨日までの形）
	var RAIN_STAR_CUT = 1;
	// ★★★★★「TEST RAIN」で、強い雨の**どれだけ手前**に置くか（ドット）。
	//   ★★ここが 0 だと**いちばん強いところ**から始まり、あとは弱くなる一方です。
	//   ★少し手前に置くと、★★**強くなって、やがて止む**まで見られます
	var RAIN_TEST_BEFORE = 700;
	// ★★★★★ゴールから、これだけ手前までで探す（メートル）。
	//   ★★ゴールより先から走り出すと、★★★**数秒でエンディングが始まります**
	var RAIN_TEST_MARGIN_M = 1000;
	// ★★★「もう降っている」とみなす強さ（★これより弱いところまでは戻さない）
	var RAIN_TEST_MIN = 0.35;
	// ============================================================
	// ★★★★★雨粒が地面で跳ねる —— **小さな水しぶき**（2026-09-06 島さんの指定）
	// ============================================================
	//
	//   > **島さん「雨粒が地面にぶつかったとき小さな水しぶきが起きる
	//   >   パターンも混ぜて。つぶまきで」**
	//
	//   ★★**「も混ぜて」** ＝ ★★★**ぜんぶの雨粒が跳ねるのではありません**。
	//     ★跳ねる粒と、そのまま消える粒が混ざります（★`RAIN_SPLASH_RATE`）。
	//     ★★これは「跳ぶけむり」が**０粒のときもある**のと同じ考え方です。
	//
	//   ■ ★★★新しい仕組みは1つも作っていません
	//     ★雨粒の**寿命が来たところ**（＝地面に届いたところ）で、
	//       ★★つぶまきの粒を1〜3つぶ撒くだけです。
	//     ★★★撒く場所も、消えるところも、★**いままでと同じ1か所**を通ります。
	//
	//   ■ ★★寿命は「上がって戻るまで」（★着地のけむりで作った形とまったく同じ）
	//     ★★★だから**地面に張り付きません**（★跳ねて、落ちて、消える）。
	//
	//   ■ ★★★★色は**実測で**選びました（★雨粒とは条件がまったくちがいます）
	//     ★雨粒は**空の前**を落ちますが、★★しぶきは**地面のすぐ上**に出ます。
	//     ★★★しかも**雨のときは乗算がかかっている**ので、そこまで含めて測りました。
	//
	//     ★実測（★地面のすぐ上 1〜6ドット・★★乗算をかけたあとの色で）:
	//
	//         |      | ★昼の雨 | ★★夜の雨 |
	//         |---   |---:|---:|
	//         | ★27 青（純） #0000e0 | ★★**10.5%** | ★★★**99.9%**（★消える） |
	//         | ★29 白 #fcf5fd       | ★23.3%       | ★★**56.6%**（★いちばんまし） |
	//         | ★ 8 空色             | ★★43.2%     | ★96.9% |
	//         | ★21 水色             | ★★★62.4%   | ★96.1% |
	//
	//     ★★★**どちらか片方では、昼か夜のどちらかで消えます。**
	//       → ★**2色を混ぜました**: ★★**昼は青が、夜は白が**受け持ちます。
	//     ★★どちらも「水」の色なので、混ざっていても不自然ではありません。
	//     ★★★空色・水色は**外しました**（★雨粒に使った色ですが、
	//       ★地面ぎわでは草のあかりに溶けます ＝ **場所がちがえば答えもちがう**）。
	var RAIN_SPLASH_ON   = 1;    // ★★0 にすると、しぶきだけ止まる（★雨はそのまま降る）
	var RAIN_SPLASH_RATE = 0.4; // ★★★**跳ねる雨粒の割合**（★島さんの「も混ぜて」）
	var RAIN_SPLASH_MIN  = 3;    // ★1回のしぶきのつぶ数（★ここから）
	var RAIN_SPLASH_NUM  = 5;    //   ★ここまで
	var RAIN_SPLASH_RISE = 60;   // ★★上へ跳ねる速さ（★およそ 3ドット上がる）
	var RAIN_SPLASH_SIDE = 20;   // ★横へ散る速さ
	var RAIN_SPLASH_GRAV = 380;  // ★★落ち方（★大きいほど、すぐ戻ってくる）
	var RAIN_SPLASH_COLS = [29, 27];  // ★★白 と 青（純） ★島さんの持ち場（★上の実測で選んだ）
	// ★★★★薄い粒は混ぜません（★実測で決めた）。
	//   ★しぶきは**1ドット**なので、★★半透明にすると**草に溶けて見えなくなります**
	//   （★雨すじは4つぶ続くので、薄くても形が分かります ＝ そちらは混ぜたまま）
	var RAIN_SPLASH_DIM  = 0;

	// ★★距離の節目（★進むほど間隔が広がる。★距離は報酬の主役ではない）
	//
