	//   ★1 に戻せばまた出る（★仕組みも表もそのまま残してある）
	var MILESTONE_POP_ON = 0;    // ★0 = 出さない / 1 = 節目に「+100m」を出す
	var MILESTONES = [20, 50, 100, 200, 300, 500, 750, 1000, 1500, 2000, 3000];
	var MILESTONE_STEP = 2000;   // ★表を使い切ったあとは、この間隔で

