	//       `node tools/bar2art.js` を走らせれば、**置き場所も自動でそろいます**
	//   ★`BAR_H_FALLBACK` は、絵が読めなかったときだけ使う予備の高さ
	var BAR_H_FALLBACK = 3;
	// ============================================================
	// ★★★MAXdrink（回復アイテム）—— 2026-08-22 島さんの指定
	// ============================================================
	//   > 島さん「回復のタイミングは残り体力が0になった時です。
