	var REVIVE_BLINK = 90;    // ★バーが白く光る間隔（ミリ秒）

	// ============================================================
	// ■■■ ★★★★BET（賭け）—— 体力を払ってコインを増やす ■■■
	// ============================================================
	//
	//   > 島さん「BETにして。試験的にプレイしてみたいです。」（2026-08-23）
	//
	//   ★★★★**エンディング後の遊びです**（2026-08-23 島さんの指定）:
	//   > 島さん「BETはエンディング後の遊びにしたいです。」
	//     ★★ゴール（5000m）を見て二段ジャンプを授かるまで、**一覧に出ません**。
	//     ★★★二段ジャンプと**まったく同じ扱い**（★そのランだけ・死ねば消える）。
