	//
	//   ★★**数字は `js/upgrades.js` の `BET`**（★島さんの持ち場）。ここは見せ方だけ。
	//   ★`BET_ON = 0` にすると仕組みごと止まります（★ショップからも消える）。
	//
	//   ■ ★★★伝え方 —— **説明文は1文字も出さない**（★扉と鍵と同じ考え方）
	//
	//     押した瞬間に、★**払ったもの**と★★**得たもの**が同時に見える:
	//       (1) 体力バーが**赤く点滅して1つぶん減る**   … ★払った
	//       (2) 左上のコインの横に **×1.5** が出っぱなし … ★★得た
