	//     2. ★★**そのランのあいだだけ**（★死ねば ×1 に戻る。コイン・レベル・技と同じ）
	//     3. ★★★**廃止した `MULT` を戻したのではない。**
	//        ★あちらは「買って育てる倍率」／★★こちらは「**体力を払って買う倍率**」
	// ★★★★2026-08-23、島さんの指定で**保留**にしました:
	//   > 島さん「BETは一旦消して保留でお願いします。」
	//   ★★**消していません。1 に戻せばそのまま復活します**（★テストも一緒に戻る）。
	//   ★★★**AIへ: 勝手に 1 に戻さないこと。** ★戻すのは島さんが決めます
	//   （★`GATE_ON` / `CAMP_ON` とまったく同じ扱い）
	var BET_ON       = 0;
	var BET_FLASH_MS = 500;   // ★払った瞬間、バーが赤く点滅する長さ（ミリ秒）
	var BET_BLINK    = 80;    // ★点滅の間隔（ミリ秒）
	var C_BET        = 17;    // ★左上の「×1.5」の色。17=赤（★危ないことをした印）
	var C_BAR_BACK = 5;    // ★減った側の色。5=炭（「どれだけ減ったか」が見える）
	// ★残量で色が変わる（★上から順に見て、最初に当てはまったものを使う）
	var BAR_STEPS = [
		{ at: 0.60, color: 20 },   // 60%〜   20=緑 #00e436
		{ at: 0.30, color: 19 },   // 30〜60% 19=黄 #ffec27
		{ at: 0.15, color: 18 },   // 15〜30% 18=橙 #ffa300
		{ at: 0.00, color: 17 }    // ★〜15%  17=赤 #ff004d（★もう終わる）
	];

