	// ============================================================
	//   ① GAMEOVER の暗転（黒）／② ゴールの白い光（白）／
	//   ③ エンディングのページ送り（白）／④ 二段ジャンプを授かる暗転（黒）
	//   → ★違うのは**色と進み具合だけ**だった。
	//
	//   ★★★**AIへ: 4か所に書き戻さないこと。** ★「**半透明を使わない**」という
	//     決まりを守る場所が1つなら、★★崩しようがない（→`test/screen.test.js`【2.61】）。
	//   t = 0（何もしない）〜1（覆いきる） / ci = 色の番号（`C_FADE` 黒 / `C_GOAL_LIGHT` 白）
	function fadeRows(t, ci) {
		var lit = Math.round(t * 8);              // ★8段のうち、何段ぶん覆ったか
		if (lit <= 0) return 0;
		ctx.fillStyle = GB[ci];
		if (lit >= 8) { ctx.fillRect(0, 0, W, H); return lit; }   // ★覆いきり（1回で済ませる）
		for (var y = 0; y < H; y++) {
			if (FADE_ORDER.indexOf(y % 8) < lit) ctx.fillRect(0, y, W, 1);
		}
		return lit;
	}
