	                         //   ★★★2026-09-02、坂にも出るようになりました。
	                         //     ★★**まっすぐな1本**（★両端を結ぶ）なので、長くても
	                         //       ★端がめり込みません（★実測: 地面から 10〜17ドット）
	var RAIL_GAP_MIN = 700;  // ★次のレールまでの距離（ドット）。★Lv0 で約10秒
	var RAIL_GAP_MAX = 1600; //   ★Lv0 で約23秒
	var RAIL_COIN    = 1.25; // ★★1ドット乗るごとに入るコイン
	                         //   ★実測: 1本（90ドット）乗り切ると **110枚**
	                         //     ＝ ★★障害物1個（18.72枚）の **約5.9倍**
	                         //   ★★★2026-09-02、★**素通りでは1枚も入らなく**なりました
	                         //     （★前は越えるだけで 18.72枚 入っていた ＝ 8/31 の消し忘れ）
	                         //   ★★★**長さを3倍にしたので、もらえる量も3倍**になりました。
	                         //     ★多すぎると感じたら、ここを下げます（★島さんの持ち場）
	                         //   ★`COIN` のアップグレードがそのまま効きます
	var RAIL_KEEP    = 45;   // ★★他の障害物とこれだけ離す（★★両側が互いを見る＝鳥の教訓）
	                         //   ★★★**実測で決めた**（★5分あたりのコーンの数）:
	                         //     ★レール無し 39.2個 ／ ★★KEEP45 **30.6個** ／
	                         //     ★KEEP60 21.0個 ／ ★KEEP90 22.6個
	                         //   ★★★2026-09-02、★レールが坂にも出るようになったので、
	                         //     ★★**コーンの置き場を奪わなくなりました**（★実測・5分あたり:
	                         //     ★平地だけのとき 37.1個 → ★★★坂にも出るいま **56.3個**）。
	                         //   ★★いまここが効くのは「**丘のスライム・鳥と隣り合うとき**」です
	var RAIL_RETRY   = 50;   // ★★置けなかったとき、何ドット進んでから試し直すか
	                         //   ★★★2026-09-02、坂にも出るようになったので、
	                         //     ★**ここを通ることはめったにありません**
	                         //     （★前は「まっすぐな道が14%しかない」ので毎回ここでした）
	var RAIL_SOUND_ON = 1;   // ★★乗った・降りたの音

	// ============================================================
	// ★★★★★レールの金属音（2026-09-02 島さんの指定）
	// ============================================================
	//
	//   > **島さん「レールに接触したときの効果音を気持ち良くしたい。
	//   >   実際は金属音のはず。脳汁でる音。」**
	//
	//   ★★**金属らしさの正体は「倍音が整数比になっていないこと」**です。
	//     ★ふつうの音（声・笛・弦）は 1 : 2 : 3 : 4 … と**きれいな整数比**。
	//     ★★★叩いた金属の棒は **1 : 2.76 : 5.40 : 8.93** ＝ **半端な比**。
	//       ★この「半端さ」を耳が「金属」と聞き分けます。
	//
	//   ★★前の音は **880 → 1319 の2音**でした。★どちらも整数比に近く、
	//     ★★★**構造的に金属には聞こえません**でした（★AI が仮に置いた音）。
	//
	//   ★★★★**4つを同時に鳴らします**（★順番にではない ＝ 1つの「カーン」になる）。
	//     ★高い倍音ほど**早く消える**（★実物の金属と同じ）。
	//
	//   ★★★★★**島さんが R⑤（クランク＋きらめき）を選びました**（2026-09-02）。
	//     ★金属の「カーン」のあとに、★★**3つ駆け上がるきらめき**が続きます。
	//     ★★★これが「脳汁」の部分（★金属だけだと現実的だが、ごほうび感が薄い）。
	//
	//   ★★聴き比べは **`tools/preview-sound.html` の R⓪〜R⑥**（★島さんの持ち場）
	var RAIL_HZ    = 880;    // ★★音の高さ（★下げると太いトラック／上げると細い手すり）
	var RAIL_RATIO = [1, 2.76, 5.40, 8.93];   // ★★★金属の倍音比（★整数比にしないこと）
	var RAIL_DUR   = [0.24, 0.15, 0.09, 0.05]; // ★高い倍音ほど早く消える

	// ★★★★★きらめき（★金属の「カーン」のあとに続く。★島さんが選んだ R⑤ の部分）
	//   ★形は `[高さ, 長さ, 何ミリ秒後]`。★★**空の配列にすると R① に戻ります**
	//   ★ここは**駆け上がる形**なので、金属の倍音とちがって**整数比でよい**
	//     （★「きらめき」は金属の音ではなく、★★**ごほうびの合図**だから）
	var RAIL_SPARK = [
		[2637, 0.05,  90],
		[3520, 0.05, 140],
		[4699, 0.18, 190]
	];

	// ★★★★★擦れ続ける音（★グラインド中ずっと）。★★**いまは止めてあります**
	//   ★★実物のグラインドは「カーン」で終わらず、★**擦れる音が出続けます**。
	//     ★★★火花とまったく同じ考え方（★**時間ではなく距離で数える**
	//       ＝ 速く走るほど密になる）。
	//   ★候補は `tools/preview-sound.html` の **R⑥**。★1 にすると鳴ります
	//   ★★★**AIへ: 勝手に 1 に戻さないこと**（★`LAND_SOUND_ON` と同じ扱い）
	var RAIL_SCRAPE_ON    = 0;
	var RAIL_SCRAPE_EVERY = 4;     // ★★何ドット進むごとに鳴らすか（★小さいほど密）
	var RAIL_SCRAPE_HZ    = 1600;  // ★擦れの高さ
	var RAIL_SCRAPE_VAR   = 7;     // ★★高さのばらつき（★機械的にしないため）
	var RAIL_SCRAPE_DUR   = 0.030;

	var GATE = global.DotGateArt;
	var KEY  = global.DotKeyArt;
	var CAMP = global.DotCampArt;
	var CAMP_W = CAMP.FRAMES[0].rows[0].length;
	var GATE_W = GATE.FRAMES[0].rows[0].length;
	var KEY_W  = KEY.FRAMES[0].rows[0].length;

	// ★障害物1つの絵と幅（★2か所に持たない）
	function obArt(o) {
		if (o.kind === "rail")  return RAIL;
		if (o.kind === "enemy") return ENEMY;
		if (o.kind === "tori") return TORI;
		if (o.kind === "aosura") return AOSURA;
		if (o.kind === "bird")  return BIRD;
		if (o.kind === "key")  return KEY;
		if (o.kind === "camp") return CAMP;
		// ★★扉は「開いた姿」を持つ。★★**鍵を持っているだけでは開かない**
		//   （★`o.opened` は「鍵を持った状態で**突破した瞬間**」に立つ。→ `passGate()`）
		// ★★★ゴールの扉も同じ絵を借りている（2026-08-22）。
		//   ★★着いた瞬間に `opened` が立つので、**開く様子がそのまま見える**
		if (o.kind === "gate" || o.kind === "goal") {
			return o.opened
				? { FRAMES: GATE.OPEN_FRAMES, FEET_ROW: GATE.FEET_ROW }
				: GATE;
		}
		return CONE;
	}
	function obWidth(o) {
		if (o.kind === "rail")  return RAIL_LEN;
		if (o.kind === "enemy") return ENEMY_W;
		if (o.kind === "tori") return TORI_W;
		if (o.kind === "aosura") return AOSURA_W;
		if (o.kind === "bird")  return BIRD_W;
		if (o.kind === "gate" || o.kind === "goal") return GATE_W;
		if (o.kind === "key")  return KEY_W;
		if (o.kind === "camp") return CAMP_W;
		return CONE_W;
	}

	// ============================================================
	// ■■■ ★★障害物のパターン（2026-08-15 / Phase 2）■■■
	// ============================================================
	//
	//   島さん「**この地形ならどの技を選ぶ？** を発生させる」
	//
	// ■ ★★幅を直書きしない（ここがいちばん大事）
	//
	//   コーンを**何個並べるか**は、技の「越えられる幅」から**毎回計算する**。
	//   ★直書きすると、島さんが `js/frames.js` のコマを速くした瞬間に
	//     幅だけ取り残されて、**理不尽な障害物**になる。
	//
	// ■ ★★「高さ」ではなく「幅」で作る理由
	//
	//   3技の**跳ぶ高さは 25 / 27 / 27 ドットでほぼ同じ**（島さんが描いた絵が決めている）。
	//   → 高さでは使い分けが作れない。**幅なら滞空時間の差がそのまま効く**。
	//
	// ■ ★★★2026-08-15、**アップグレードで越えられる範囲が広がる形**にした
	//
	//   島さん「**技術を要しない。** アップグレードで強くなる」
	//
	//   ★★**コーンの幅は「Lv0 のときの越えられる幅」を基準に決め打ちにする。**
	//     ★★**いまの（強化後の）幅から決めてはいけない。**
	//       それをすると障害物が自分に合わせて大きくなり、
	//       **いつまでも「前は越えられなかったものが越えられた」が起きない**。
	//
	//       狭い … Lv0 でも余裕で越えられる
	//       中   … Lv0 でぎりぎり越えられる
	//       ★広い … ★**Lv0 では越えられない。** アップグレードすると越えられるようになる
	//
	//   → ★**「俺が上手くなった」ではなく「このビルドなら突破できる」**になる
	// ============================================================
	var PATTERN_ON = 1;      // 0 にすると障害物が出なくなる

	// ★その技の「越えられる幅」（ドット）。★表と速さから毎回計算する
	//   ★★これは **Lv0（アップグレード無し）の値**。障害物の大きさを決めるのに使う
	function clearDotsOf(name) {
		for (var i = 0; i < POSES.length; i++) {
			if (POSES[i].name !== name) continue;
			return Math.round(FR.airMs(POSES[i].ms, POSES[i].lifts) / 1000 * SPEED);
		}
		return 0;
	}

	// ★★★いま実際に越えられる幅（★アップグレードが乗ったあと）。
	//   空中の時間 × 速さ。★JUMP は時間を、SPEED は速さを伸ばす ＝ **掛け算になる**
	function curClearDots(name) {
		for (var i = 0; i < POSES.length; i++) {
			if (POSES[i].name !== name) continue;
			return Math.round(
				FR.airMs(POSES[i].ms, POSES[i].lifts) * jumpDurationMul() / 1000 * curSpeed());
		}
		return 0;
	}
	// ★★★「Lv0 のときに越えられる幅」＝ 障害物の大きさを決める基準
	//   ★★アップグレードが乗る前の値なので、**世界の側は永久に変わらない**。
	//     だからこそ「前は越えられなかったコーンが越えられた」が起きる
	//
	//   ★★★**ここを `curSpeed()` に変えないこと**（2026-08-15 / Phase B）。
	//     変えると**障害物が自分に合わせて大きくなり**、
	//     「前は越えられなかったものが越えられた」が**永久に起きなくなる**。
	//
	//       SPEED を上げる → プレイヤーが速くなる
	//       → 同じ障害物を以前より短時間で通過する
	//       → ★★**障害物そのものは大きくならない**
	var BASE_CLEAR = clearDotsOf("OLLIE");

	// ★その幅に収まるコーンの個数（★1個ぶん余裕を残す）
	function conesForDots(dots) {
		return Math.max(1, Math.floor((dots - CONE_W) / CONE_W));
	}

	// ============================================================
	// ■ ★★★「多くても、ギリギリ越えられる幅」（★島さんの指定 2026-08-20）
	// ============================================================
	//
	//   > 島さん「コーンは多くてもギリギリ越えられる幅に設定して。どのレベルでも。
	//   >         たくさん並べる時の話だよ。頻度はいまのままでよい」
	//
	//   ★★並んだコーンの塊は、**いま自分が1回の技で覆いきれる幅**を超えない。
	//     覆いきれる幅 ＝ `curClearDots("OLLIE")`（空中の時間 × ★いまの速さ）。
	//
	//   ★★★これは**天井であって、下限ではない**。
	//     ★パターンが元々もっている個数より**増やす方向には一切効かない**。
	//     → だから「強くなると障害物も大きくなる」にはならない
	//       （★`BASE_CLEAR` は Lv0 のまま。★ここは今までどおり触っていない）。
	//
	//   ★`CLEAR_MARGIN` ＝「ギリギリ」の余裕（ドット）。
	//     ★n個ぶんの幅は `n * CONE_W - 1` ドットなので、
	//       **覆いきれる幅 − 余裕** に収まる最大の個数を出す。
	//     ★0 にすると**1ドットの狂いも許されない**タイミングになる。
	//       6 ＝ Lv0 の速さ（70ドット/秒）で **約86ミリ秒ぶんの猶予**。
	//
	//   ★★頻度（`coneGapMin()` / `nextConeGap()`）には**触っていない**
	//     ＝ 島さんの「頻度はいまのままでよい」。
	//
	//   ⚠ ★★★この天井が入ったことで**変わったこと**（★島さんの判断待ち）:
	//     ・「D 広い」は Lv0 でも越えられるようになった（★越えられない壁が消えた）
	//     ・距離で太る仕組み（`TIER_*`）も、この天井までしか効かなくなった
	//     ★戻すときは `CLEAR_LIMIT_ON = 0`（★1行で昔どおりに戻る）
	// ============================================================
	var CLEAR_LIMIT_ON = 1;   // ★0 = 昔どおり（越えられない幅も出る）
	var CLEAR_MARGIN   = 7;   // ★「ギリギリ」の余裕（ドット）

	// ★★いまの自分が1回の技で覆いきれる、コーンの個数の上限
	function maxConesNow() {
		return Math.max(1,
			Math.floor((curClearDots("OLLIE") - CLEAR_MARGIN + 1) / CONE_W));
	}

	// ★★パターンの表。★`ns` = コーンの個数の並び（★`at` は距離から作る）
	//   ★★`at`（2個目以降の置き場所）を**表に直書きしない**。
	//     直書きすると、下の「距離で太らせる」で**1個目と重なる**（太ったぶんを足し忘れる）
	function buildPatterns() {
		var nNarrow = conesForDots(BASE_CLEAR * 0.55);   // ★Lv0 でも余裕
		var nMid    = conesForDots(BASE_CLEAR * 1.00);   // ★Lv0 でぎりぎり
		var nWide   = conesForDots(BASE_CLEAR * 1.80);   // ★★Lv0 では越えられない
		// ★★★`gap` は「**空いている幅**」（★2026-08-16 に直した）
		//   もとの表は `at: 53`（＝パターンの先頭からの位置）を直書きしていた。
		//   ★下の `patternAt()` で `at` を作り直すとき、うっかり
		//     「1個目の幅 ＋ 53」にしてしまい、**空きが 44 → 53 に広がっていた**
		//     ＝ 島さんに黙って **パターンC が少し易しくなっていた**（回帰）。
		//   → ★`gap` を最初から「空いている幅」にして、意味を1つに固定する
		var gap = Math.round(BASE_CLEAR * 1.3) - CONE_W;   // ★空き = 44ドット
		return [
			{ name: "A 狭い", ns: [nNarrow],          gap: gap },
			{ name: "B 中",   ns: [nMid],             gap: gap },
			{ name: "C 連続", ns: [nNarrow, nNarrow], gap: gap },
			// ★★D は Lv0 では越えられない。**アップグレードで越えられるようになる壁**
			{ name: "D 広い", ns: [nWide],            gap: gap }
		];
	}
	var PATTERNS = buildPatterns();

	// ============================================================
	// ■ ★★★距離で障害物が広がる（2026-08-16 / Phase C）
	//
	//   ★★これは島さんが**選択肢から選んで承認したもの**（2026-08-16）:
	//     「遠くへ行くほど障害物が広くなる」＋「この実装は残してコミットする」
	//   ★★★**島さんが言葉で指示したのではない**（AIが案を出して選んでもらった）。
	//     ★下の引用は「なぜこの案を出したか」の背景であって、指示そのものではない
	//
	//   > 島さん「もう一回走りたいと感じましたが、
	//   >         すぐに成長の限界値に達してしまい終わりました」
	//
	//   ★★天井のひとつは「**立ちはだかるものが増えない**」ことだった。
	//     障害物がずっと最大 63px なので、**JUMP は Lv2 で用済み**になっていた。
	//
	//   → **遠くへ行くほど障害物が広くなる。**
	//
	//   ⚠ ★★2026-08-16 のレビューで分かったこと:
	//     **いまの到達距離（中央 161m）では、1段目（250m）にすら届かない。**
	//     ＝ ★この仕組みは**まだ一度も発動していない**。
	//     ★★扉と鍵が効くと分かってから、`TIER_M` を実測で決め直すこと
	//
	//       強くなる → より遠くへ行ける → そこは前より難しい → さらに強くなる必要がある
	//
	//   ★★★ここが「輪」になるので、レベルを無限に増やすだけのゲームにならない。
	//
	// ■ ★★崩してはいけない決まりは、これで守れる
	//
	//   ・広がるのは**距離**であって、**自分の強さではない**
	//     → ★`BASE_CLEAR` は Lv0 のまま。★**ここを触らないこと**
	//   ・★**同じ場所なら、誰が来ても同じ幅**
	//     → 「前は越えられなかった壁を越せた」は**ちゃんと残る**
	//   ・★種（シード）では決めていない
	//     → 「1500m から急に難しい」は覚えられるが、★**覚えても回避できない**
	//       （強くなるしかない）ので、**覚えゲーにはならない**
	//
	// ■ ★敵（丘の障害物）は広げない
	//     絵が要るため。**小さい障害物**として、そのまま残す
	// ============================================================
	//
	// ■ ★★★ここの数字は「実測で決めた」（2026-08-16。★当てずっぽうではない）
	//
	//   ★★画面は 240px。**障害物は最大でも 190px くらいまでしか作れない。**
	//     → ★**幅では無限に難しくできない。** だから壁は**ルール**（扉と鍵）にした
	//     → JUMP は `js/upgrades.js` で **`maxLevel: 2` に抑えてある**
	//       （★`per` は 1.20 のまま。★変えたのは段数だけ）
	var TIER_ON  = 1;     // ★0 にすると、昔どおり「ずっと同じ幅」に戻る
	var TIER_M   = 250;   // ★何メートルごとに1段きつくなるか
	var TIER_ADD = 1;     // ★1段ごとにコーンが何個増えるか（1個 = CONE_W = 9ドット）
	// ★★増える上限。★D が最大 63 + 9×14 = **189px**（画面の79%）。
	//   ★これ以上は「画面いっぱいのコーン」になって、避けようがなくなる
	var TIER_MAX = 14;

	// ★その場所の「段」（0 から。★上限で止まる）
	function tierAt(distDots) {
		if (!TIER_ON) return 0;
		return Math.min(TIER_MAX, Math.floor(metersOf(distDots) / TIER_M) * TIER_ADD);
	}

	// ★★その場所で出すパターンを作る（★段のぶんだけ太らせて、`at` を作り直す）
	function patternAt(index, distDots) {
		var base = PATTERNS[index % PATTERNS.length];
		var add = tierAt(distDots);
		// ★★★「多くてもギリギリ越えられる幅」の天井（★島さん 2026-08-20）
		var cap = CLEAR_LIMIT_ON ? maxConesNow() : Infinity;
		var obs = [], at = 0;
		for (var i = 0; i < base.ns.length; i++) {
			var n = Math.min(base.ns[i] + add, cap);
			obs.push({ at: at, n: n });
			at += n * CONE_W + base.gap;   // ★★太ったぶんを必ず足す（重なり防止）
		}
		return { name: base.name, obs: obs };
	}

	// そのパターンの全長（ドット）
	function patternLen(p) {
		var last = p.obs[p.obs.length - 1];
		return last.at + last.n * CONE_W;
	}

	// ★いま出している姿。技を出していれば技、そうでなければ地上の姿
	function currentPose() {
		return (st.air >= 0) ? POSES[st.trick] : POSES[st.idle];
	}

	// ★いま出すコマの番号
	function currentFrame() {
		var P = currentPose();
		var ms = (st.air >= 0) ? st.air : st.idleMs;
		var i = FR.frameAt(P.ms, ms);
		return (i < 0) ? P.ms.length - 1 : i;      // 行き過ぎたら最後のコマで待つ
	}

	// ------------------------------------------------------------
	// ■ 音（切っているときは鳴らさない。ここを通さないと切れない）
	// ------------------------------------------------------------
	function sound(freq, dur) {
		if (soundOn && beep) beep(freq, dur);
	}

	// ============================================================
	// ★★★音を「順番に並べて」鳴らす（2026-08-16。★買った瞬間の音のために作った）
	// ============================================================
	//   ★★`sound()` は1つ鳴らすだけ。**旋律にしたいので、時間をずらして並べる道具**を作った。
	//   ★★★1か所に集めてあるのが大事: `setTimeout` を呼び出し側に散らすと、
	//     音を切ったあとも鳴り残る（★ここで `soundOn` を毎回見ている）
	//   ★引数は `[[高さ, 長さ, 何ミリ秒後], ...]`
	function melody(notes) {
		if (!soundOn || !beep) return;
		notes.forEach(function (n) {
			if (n[2] <= 0) { sound(n[0], n[1]); return; }
			setTimeout(function () { sound(n[0], n[1]); }, n[2]);
		});
	}

	// ============================================================
	// ★★★★買えた瞬間の音（★★★2026-08-20、**初代に戻した**）
	// ============================================================
	//
	//   > 島さん「音はかわりに各能力が上がったときに(購入)気持ち良いのをお願いします。
	//   >   脳汁でるような。」（2026-08-16 / ★これで作った初代がこの音）
	//   > 島さん「購入時効果音はもう少し気持ち良くして」（2026-08-16 / ★2度目）
	//   > 島さん「購入した時の音耳に残るような音にして」（2026-08-20 / ★3度目）
	//   > ★★★島さん「**あんますきじゃない。最初に初めて購入音導入したときの音が良かった**」
	//
	//   ■ ★★★AIへ: ここでいちばん大事な教訓（★消さないこと）
	//
	//     ★AIは2度、**理屈で音を「良く」しようとして外した**:
	//       ・2度目 … 音を足して厚くした（10音）
	//       ・3度目 … 桜井資料から「口ずさめる形」を導いて作り直した（5音）
	//     ★★どちらも**筋は通っていたが、島さんの耳には初代が良かった**。
	//
	//     ★★★**音は理屈で決めない。島さんの耳が正。**
	//     ★資料は「なぜ良いか」を説明する道具であって、**良し悪しを決める権限は無い**。
	//     ★★次に音を触りたくなったら、まず `tools/preview-sound.html` で
	//       **鳴らして選んでもらう**（★勝手に差し替えない）。
	//
	//   ■ この音の作り（★初代 ＝ 2026-08-16 の1回目）
	//
	//     ★**駆け上がる**（440 → 660 → 880 → 1320 → 1760）
	//     ★**最後だけ長い**（0.28秒）＝ 着地
	//     ★**着地と同時に 880 を重ねる** ＝ 厚み
	//     ★全部で約 0.46 秒。★45ms 刻みの**等間隔**（★これがこの音の速さ）
	//
	//   ★★★**並べるのは `melody()` の1か所だけ**（★`setTimeout` を散らすと、
	//     音を切ったあとも鳴り残る）
	function buySound() {
		melody([
			[440,  0.05,   0],
			[660,  0.05,  45],
			[880,  0.05,  90],
			[1320, 0.06, 135],
			[1760, 0.28, 180],   // ★★着地（★長い）
			[880,  0.28, 180]    // ★★同時に鳴らして厚みを出す
		]);
	}


	// ============================================================
	// ★★★MAXdrink を使ったときの音（2026-08-22 島さんの指定「心地よい音」）
	// ============================================================
	//
	//   ★★買った音（`buySound`）とは**わざと別のもの**にしてあります:
	//
	//   | | 買った音 | ★この音 |
	//   |---|---|---|
	//   | 速さ | ★速い（45ms 刻み） | ★★**ゆっくり**（90ms 刻み） |
	//   | 形 | 駆け上がって着地 | ★★**下から積み上がって、和音で満ちる** |
	//   | 気持ち | 「やった、買えた」 | ★★★「ふう、助かった」 |
	//
	//   ★★★**音は理屈で決めない。島さんの耳が正**（→ CLAUDE.md 2026-08-20 の教訓）。
	//     ★`tools/preview-sound.html` で聞き比べられます。★違ったら言ってください
	function reviveSound() {
		melody([
			[392, 0.10,   0],   // ★ソ …… 低いところから
			[523, 0.10,  90],   // ★ド
			[659, 0.10, 180],   // ★ミ
			// ★★満ちる和音（★長く伸ばす ＝ ゲージが満タンになる時間）
			[784, 0.45, 270],   //   ソ
			[523, 0.45, 270],   // ＋ド
			[1047, 0.45, 270]   // ＋ド（上）
		]);
	}

	function loadSound() {
		try { soundOn = localStorage.getItem("dotollie-sound") !== "off"; } catch (e) { soundOn = true; }
		global.DotOllie.padIcons.sound = soundOn ? "BTN_SOUND_ON" : "BTN_SOUND_OFF";
		return soundOn;
	}

	function saveSound(on) {
		try { localStorage.setItem("dotollie-sound", on ? "on" : "off"); } catch (e) { /* 保存できなくても遊べる */ }
	}

	// ------------------------------------------------------------
	// ■ ★★いちばん進んだ距離（BEST）—— 2026-08-15 / Phase 3
	//
	//   ★覚え方は**音の入り切りとまったく同じ**（`localStorage` ＋ `try/catch`）。
	//     ★保存できない場所（プライベートモードなど）でも**遊べなくならない**
	//
	//   ★★BEST は**ゲーム性の核心ではない**（島さんの指定）。
	//     「もう一回」の理由を1つ増やすだけのもの。★ここから育てないこと
	// ------------------------------------------------------------
	var best = 0;      // ★ドットではなく**メートル**（画面に出す数字と同じ単位）

	// ============================================================
	// ■ ★★★テストモード（2026-08-22 島さんの指定）
	// ============================================================
	//
	//   > 島さん「テストでエンディングをみたいのだけど、9950ｍまでとばせないかな。
	//   >   例えばタイトル画面でテストモードを選べるようにしてさ」
	//
	//   ★★シェル（`js/shell.js`）のタイトル画面で **TEST 4950m** を選ぶと、
	//     ★**4950m から走り出す**（★5000m のゴールまで約7秒）。
	//     ★★★2026-08-23、ゴールが 5000m へ動いたので**ここも動かしました**
	//       （★★ゴールの**50m 手前**、という関係は変えていません）。
	//   ★★★**BEST（いちばん進んだ距離）は更新しない**ので、★記録が汚れない。
	//     ★これが無いと、テストするたびに BEST が 5000m になって
	//       **本当の記録が上書きされてしまう**
	//   ★★遊びの中身は1つも変えていない（★走り出す場所だけが違う）
	var startAtM = 0;       // ★何メートルから走り出すか（0 = ふつうに 0m から）
	// ★★★★★天気を見るためのテストモード（2026-09-06 島さんの指定）
	//   ★`startAtRain` … この強さの雨が降っている場所から走り出す（0 = ふつう）
	//   ★★`startAtDay` … 昼と夜の時計を、この時刻から始める（★-1 = ふつうに朝から）
	var startAtRain = 0;
	var startAtDay = -1;
	var startAtFish = false; // ★★★★★2026-09-15 島さんの指定: キャンプの池（釣り）から始める
	var testMode = false;   // ★★テストモードのあいだは BEST を更新しない

	// ============================================================
	// ★★★★★覚える場所は、この3つだけを通る（2026-09-21(6) 島さんの指定）
	// ============================================================
	//
	//   ★★★**2026-09-21、「採掘の素材が消える」の原因がここでした。**
	//
	//     ★「テストモードでは localStorage に書かない」という決まりが、
	//     ★★**「なにも覚えない」**まで広がっていて、
	//     ★★★採掘・釣り・コインが**モードに入るたびまっさらから作り直されて**いました。
	//     （★島さんは TEST 4950m で遊ぶことが多いので、★★ほぼ毎回踏んでいた）
	//
	//   ★★★★**直し方**: テスト中は「覚えない」のではなく、
	//     ★★★★★**心の中（`MEM`）だけで覚える**。
	//     ★ localStorage には★★**1バイトも書きません**（★決まりはそのまま守られる）。
	//     ★★でも**アプリを閉じるまでは消えません** ＝ 素材も釣果も残る。
	//
	//   ★★★★★**AIへ: `localStorage` を直に呼ばないこと**。
	//     ★必ず `lsGet` / `lsSet` / `lsDel` を通す（★通さないと、また同じ事故が起きる）
	var MEM = {};           // ★テストモードの「心の中の保存」
	function lsGet(key) {
		// ★★写し取り（copy-on-write）: テスト中でも、まだ書いていないものは
		//   ★**本物を読むだけ**（★BEST などがいままでどおり見える）。★★書き戻しはしない
		if (testMode && Object.prototype.hasOwnProperty.call(MEM, key)) return MEM[key];
		try { return localStorage.getItem(key); } catch (e) { return null; }
	}
	function lsSet(key, val) {
		if (testMode) { MEM[key] = String(val); return true; }
		try { localStorage.setItem(key, String(val)); return true; } catch (e) { return false; }
	}
	function lsDel(key) {
		if (testMode) { MEM[key] = null; return true; }   // ★null = 「消した」の印（★本物を読みに行かない）
		try {
			if (localStorage.removeItem) localStorage.removeItem(key);
			else localStorage.setItem(key, "null");
			return true;
		} catch (e) { return false; }
	}

	function loadBest() {
		try {
			var v = parseInt(lsGet(slotKey("dotollie-best")), 10);
			best = (isFinite(v) && v > 0) ? v : 0;
		} catch (e) { best = 0; }
		return best;
	}

	// ★★超えたときだけ更新する（**同じ距離では更新しない**）
	function updateBest(m) {
		// ★★★テストモードでは**本物の記録を残さない**（2026-08-22）。
		//   ★4950m から始めるので、そのままだと**必ず BEST を塗り替えてしまう**。
		//   ★★★★ 2026-09-21(6): `lsSet` がテスト中は心の中へ書くので、
		//     ★★**ここで止めなくてよくなりました**（★テスト中も BEST が伸びるが、★★外には残らない）
		if (m <= best) return false;
		best = m;
		lsSet(slotKey("dotollie-best"), String(best));
		return true;
	}

	// ============================================================
	// ★★★★★会ったことのある種類（2026-09-04）★★BEST とまったく同じ扱い
	// ============================================================
	//
	//   ★★**ここに入るのは「会った」という事実だけ**（★数は入れない）。
	//     ★数は `st.met` に持ち、★★★**死ねばコイン・レベルと一緒に消えます**。
	//
	//   ★★★**AIへ: ここを「強さ」に使わないこと。**
	//     ★会った種類が増えると強くなる、にした瞬間、
	//     ★★「残るのは記録だけ（力は残らない）」という理屈が崩れます
	var metKinds = {};

	function loadMet() {
		try {
			var o = JSON.parse(lsGet(CAMP_KEY) || "{}");
			metKinds = (o && typeof o === "object") ? o : {};
		} catch (e) { metKinds = {}; }
		return metKinds;
	}

	// ★★初めて会った種類だけ覚える（★2度目からは何もしない ＝ 書き込みが増えない）
	function meetKind(id) {
		if (!CAMPMODE_ON || !id) return false;
		if (metKinds[id]) return false;               // ★もう会っている
		metKinds[id] = 1;
		// ★★★テストモードでは**外に**覚えない（★`lsSet` が心の中へ書く。2026-09-21(6)）
		lsSet(CAMP_KEY, JSON.stringify(metKinds));
		return true;
	}

	function hasMet(id) { return !!metKinds[id]; }

	// ★★モンスターの表に載っているか（★コーンは載っていない ＝ 数えない）
	function isMonster(kind) {
		for (var i = 0; i < MONSTERS.length; i++) if (MONSTERS[i].id === kind) return true;
		return false;
	}

	// ★★★越えた1体を数える（★呼ぶのは「払う」のと同じ1か所だけ）
	function countMet(kind) {
		if (!CAMPMODE_ON || !st) return false;
		if (!isMonster(kind)) return false;
		st.met[kind] = (st.met[kind] || 0) + 1;   // ★数 … ★★死ねば消える
		if (meetKind(kind)) st.moment = "NEW CREATURE MET"; // ★★★種類 … ★永久に残る
		return true;
	}

	// ============================================================
	// ■■■ ★★アップグレード（2026-08-15 / Phase B）■■■
	// ============================================================
	//
	//   ★**表（何があるか・いくらか・どれくらい強くなるか）は `js/upgrades.js`**（島さんの持ち場）。
	//     ★ここは「**どこに効かせるか**」だけを知っている
	//
	//   ★★覚え方は 音・BEST・コインと**まったく同じ**（`localStorage` ＋ `try/catch`）
	var UP = global.DotUpgrades;
	var PR = global.DotProgression;
	var upgLv = {};        // id → いまのレベル（0 から）
	var unlocked = {};     // id → 覚えている技かどうか

	// ============================================================
	// ★★★使うと無くなるもの（アイテム）—— 2026-08-22 島さんの指定
	// ============================================================
	//   > 島さん「MAXdrinkを描きました。ショップで購入出来る回復アイテムです。」
	//
	//   ★`bag[id]` = 何本持っているか。★★**買うと増え、使うと減ります**。
	//   ★★★**死んだら無くなります**（★コイン・レベル・技とまったく同じ扱い）。
	//     ★これは「走りながら組み立てて、死んだら最初から」を守るため
	//     （→ CLAUDE.md「★★★★2026-08-16、この作品の形が変わった」）
	var bag = {};
	// ★★★そのランで「何本買ったか」（2026-08-22 島さんの指定）。
	//   ★値段が買うたびに10倍になるので、**買った回数**が要ります。
	//   ★★使った本数ではありません（★使っても値段は戻りません）。
	//   ★死ぬと 0 に戻ります（★コイン・レベルと同じ）
	var buys = {};

	// ★★MAXdrink の絵（★島さんが描いたもの。AIは置く場所を決めるだけ）
	//   もと: `assets/parts/MAXdrink-0001.aseprite` →「絵を反映する.bat」→ `js/parts-art.js`
	var DRINK_ICON = (global.DotPartsArt && global.DotPartsArt.MAXdrink)
		? global.DotPartsArt.MAXdrink.FRAMES[0] : null;

	function loadUpg() {
		upgLv = {}; unlocked = {}; bag = {}; buys = {};
		try {
			var raw = lsGet("dotollie-upg");
			var o = raw ? JSON.parse(raw) : null;
			if (o && o.lv) upgLv = o.lv;
			if (o && o.un) unlocked = o.un;
			if (o && o.bag) bag = o.bag;          // ★持ち物（2026-08-22）
			if (o && o.buys) buys = o.buys;       // ★★何本買ったか（値段が上がるので要る）
		} catch (e) { upgLv = {}; unlocked = {}; bag = {}; buys = {}; }
		return upgLv;
	}

	function saveUpg() {
		// ★★★★★テスト中は覚えない（2026-09-03。★`updateBest` と同じ考え方）
		//   ★★テストモードは**お金を持って始まります**（1T）。
		//     ★それを覚えてしまうと、★★★**次にふつうに始めたとき 1T のまま**になります
		//     （★実際にそうなって、テストが捕まえました）。
		//   ★★★テストで**本物の記録を汚さない**のが、この作品の決まりです。
		//   ★★★★ 2026-09-21(6): `lsSet` がテスト中は心の中へ書くので、ここで止めなくてよくなりました
		lsSet("dotollie-upg", JSON.stringify({ lv: upgLv, un: unlocked, bag: bag, buys: buys }));
	}

	// ★何本持っているか
	function bagCount(id) { return bag[id] || 0; }
	// ★★そのランで何本買ったか（★次の値段を出すのに使う）
	function buyCount(id) { return buys[id] || 0; }
	// ★★★その道具の「次の値段」
	function itemCost(u) { return UP ? UP.itemCostOf(u, buyCount(u.id)) : u.cost; }

	// ★その強化がいま何倍か（★買っていなければ 1 倍 ＝ 何も変わらない）
	function upgMul(id) {
		var u = UP && UP.find(id);
		return u ? UP.mulOf(u, upgLv[id] || 0) : 1;
	}

	function upgLevel(id) { return upgLv[id] || 0; }

	// ============================================================
	// ★★★★★転生（プレステージ）―― 2026-09-12 島さんの指定
	// ============================================================
	//
	//   > **島さん「プレステージ(転生システム)」**
	//   > **島さん「「残るのは記録だけ」←こだわらない」**
	//
	//   ★★★★★**これは、島さんが外した 5 つ目の決まりです**
	//     （★半透明 08-30 / 色の制限 09-02 / ぼかし・拡大 09-12 に続く）。
	//     ★★これまでは「★★★**力になるものは 1 つも残さない**」でした。
	//     ★★★★**AI へ: 勝手に戻さないこと。決めたのは島さんです。**
	//
	//   ■ 島さんが決めた 4 つ
	//
	//   ```
	//   持ち帰る   … ★**上限が伸びる**（★稼ぎの倍率でも、新系統でもない）
	//   引き金     … ★★**どれか 1 項目でも MAX になったら**お店に出る
	//   伸びる範囲 … ★★★**転生した瞬間に MAX だった項目だけ**
	//   差し出す   … コイン・レベル・道具 ＋ ★**いま走った距離**（★★BEST は残る）
	//   ```
	//
	//   ★「MAX にした項目だけ伸びる」が設計の芯です。
	//     ★★**早く転生する（1 項目だけ伸びる）**か、
	//     ★★**もっと育ててから転生する（重いが複数伸びる）**か ―― ★★★毎周選べます。
	var PRESTIGE_ON   = 1;    // ★★0 にすると仕組みごと止まる（★`GATE_ON` / `BET_ON` と同じ作法）
	var PRESTIGE_STEP = 3;    // ★★一度の転生で、上限が何段伸びるか
	                          //   ★★★**実測してから島さんが決めます**（★いまは仮の 3）
	// ============================================================
	// ★★★★★知らせるのは「画面」ではなく「パネル」（2026-09-12 島さんの指定）
	// ============================================================
	//
	//   > **島さん「特殊フェードインとは画面を光らせるのではなく
	//   >   新項目のパネルについてです。ではこのパネルを
	//   >   グリッチフェードインでお願いします。」**
	//
	//   ★前は**画面ぜんぶを光らせて**いました。★★島さんの意図は
	//     ★★★**新しく出てきたパネルそのもの**でした。
	//
	//   ★★**グリッチフェードイン** … パネルを横の帯に切って、
	//     ★帯ごとに**横へずらし**、★★**いくつかの帯を抜く**。
	//     ★★★それを**カタカタと数段階だけ**動かして、だんだん揃っていきます。
	//   ★★★★仕掛けは、頭上の数字の「グリッチフェード」（`POP_FADE === 3`）と同じ
	//     ＝ ★**`popNoise()` を使う**（★★**`Math.random()` は呼ばない**。
	//     ★★★呼ぶと**世界のサイコロがずれます** ―― 2026-09-12 に実際に踏んだ罠）
	var PRESTIGE_GLITCH_MS    = 700;   // ★フェードインの長さ（ミリ秒）
	var PRESTIGE_GLITCH_BANDS = 7;     // ★★パネルを横に何本の帯へ切るか
	var PRESTIGE_GLITCH_SHIFT = 8;     // ★帯を横へずらす最大（ドット）
	var PRESTIGE_GLITCH_STEPS = 6;     // ★★カタカタ動く段数（★なめらかにしない）
	var PRESTIGE_GLITCH_DROP  = 0.55;  // ★★★出はじめに、帯が抜ける割合

	// ============================================================
	// ★★★★★押しまちがいを防ぐ、一段の問いかけ（2026-09-12 島さんの指定）
	// ============================================================
	//
	//   > **島さん「重要な選択なので押し間違いを防ぐためにも
	//   >   一段選択肢をはさみましょう。」**
	//
	//   ★★キャンプの「CAMP?」と**まったく同じ形**です
	//     （★島さんが描いた YES / NO のボタンをそのまま使います）。
	//   ★★★転生は**取り返しがつきません**（★育てたものを差し出す）。
	//     ★★★★**AI へ: ここを飛ばせるようにしないこと**（★キャンプの CAMP? と同じ）
	var PRESTIGE_ASK_TEXT = "REBORN?";
	var PRESTIGE_WORD = "REBORN";  // ★お店に出る言葉（★島さんの持ち場。
	                               //   ★★フォントにある字だけ＝大文字。
	                               //   ★★★`test/sprites.test.js` が見張ります）

	// ★★この項目の、いまの天井（★転生で伸びたぶんを足す）
	//   ★★★★**上限を見るのはこの 1 か所だけ**。
	//     ★前は `shopRows()` と `canBuy()` の 2 か所で見ていました。
	//     ★★離すと「★★★**片方だけ直す**」事故が起きます（★この作品で 2 度踏んでいます）。
	// ★★★★★伸びた天井の**控え**を持ちます（2026-09-12）
	//   ★`PR.snapshot()` は**丸ごとコピー**するので、★★毎コマ呼ぶと重い。
	//   ★★★お店を開いているあいだは `shopRows()` が毎コマ回るので、
	//     ★**読むのは旅のはじめと、転生した瞬間だけ**にしてあります。
	var prestigeCaps = {};
	var openedPanels = {}, journeyRank = 0;
	function reloadCaps() {
		var profile = (PR && !testMode) ? PR.snapshot() : {};
		prestigeCaps = profile.caps || {}; openedPanels = profile.panels || {}; journeyRank=profile.rank || 0;
	}

	function capOf(u) {
		if (!u || u.maxLevel === null || u.maxLevel === undefined) return null;   // ★上限なし
		if (!PRESTIGE_ON || testMode) return u.maxLevel;
		return u.maxLevel + (prestigeCaps[u.id] || 0);
	}

	// ★★★いま MAX に届いている項目の id 一覧（★転生で伸びるのはこれだけ）
	function maxedIds() {
		if (!UP) return [];
		var out = [];
		UP.UPGRADES.forEach(function (u) {
			var cap = capOf(u);
			if (u.id !== "shoes" && u.id !== "railpass" && cap !== null && upgLevel(u.id) >= cap) out.push(u.id);
		});
		return out;
	}

	// ★転生の行を出すか（★★どれか 1 項目でも MAX なら出る）
	function canPrestige() {
		return !!(PRESTIGE_ON && PR && !testMode && st && maxedIds().length > 0);
	}
	function magnetRadius() { return upgLevel("magnet") ? UP.magnetRadius(upgLevel("magnet")) : (knowsTrick("KICKFLIP") ? 10 : 0); }
	function recoverDistance() { return UP.recoverDistance(upgLevel("recover")); }
	function updateRecover(distance, dt) {
		st.recoverFlash = Math.max(0, (st.recoverFlash || 0) - dt);
		if (!upgLevel("recover") || st.phase !== "play" || st.stamina <= 0 ||
			st.stamina >= st.staminaMax) { st.recoverProgress = 0; return; }
		var interval = recoverDistance();
		st.recoverProgress = (st.recoverProgress || 0) + distance;
		if (st.recoverProgress >= interval) {
			var heal = Math.floor(st.recoverProgress / interval);
			st.stamina = Math.min(st.staminaMax, st.stamina + heal);
			st.recoverProgress %= interval;
			if (st.stamina >= st.staminaMax) st.recoverProgress = 0;
			st.recoverFlash = 0.45;
			sound(1040, 0.045);
		}
	}

	// ============================================================
	// ■ ★★★持ち物（2026-08-16 / Phase C）
	//
	//   ★★**永久に覚える。** 一度取った鍵は、次のランでも、次の日でも持っている。
	//     ★これが無いと「探索 → **準備** → 再訪 → 突破」の**準備**が意味を持たない
	//     （毎ラン取り直しなら、ただの拾い物になる）。
	//
	//   ★覚え方は 音・BEST・コイン・アップグレードと**まったく同じ**（`try/catch`）
	//   ★★キーは `dotollie-items`。★既存の4つ（sound / best / upg / coins）と衝突しない
	// ============================================================
	var items = {};        // id → 持っているか

	function loadItems() {
		items = {};
		try {
			var raw = lsGet("dotollie-items");
			var o = raw ? JSON.parse(raw) : null;
			// ★★配列は弾く（★通すと `items` が配列になり、以後の保存が効かなくなる）
			if (o && typeof o === "object" && !Array.isArray(o)) items = o;
		} catch (e) { items = {}; }
		return items;
	}

	function saveItems() {
		// ★★★★★テスト中は覚えない（2026-09-03。★`updateBest` と同じ考え方）
		//   ★★テストモードは**お金を持って始まります**（1T）。
		//     ★それを覚えてしまうと、★★★**次にふつうに始めたとき 1T のまま**になります
		//     （★実際にそうなって、テストが捕まえました）。
		//   ★★★テストで**本物の記録を汚さない**のが、この作品の決まりです。
		//   ★★★★ 2026-09-21(6): `lsSet` がテスト中は心の中へ書く
		lsSet("dotollie-items", JSON.stringify(items));
	}

	function hasItem(id) { return !!items[id]; }

	// ★拾った。★★**すでに持っていたら何も起きない**（音もポップも二重に出さない）
	function giveItem(id) {
		if (items[id]) return false;
		items[id] = true;
		saveItems(); touchSave();
		return true;
	}

	// ============================================================
	// ■ ★★★ぜんぶ最初に戻す（2026-08-16。★島さんの指定で**扉ボタン**に付けた）
	//
	//   > 島さん「扉ボタンですべてのステータスをリセット出来るようにして。(テストのため)」
	//
	//   ★消すのは**育ったもの**だけ:
	//     コインの貯金 / アップグレードのレベル / 覚えた技 / いちばん進んだ距離 /
	//     ★**拾った持ち物（鍵）**（2026-08-16 / Phase C）
	//   ★**音の入り切りは消さない**（育ったものではなく「設定」なので）
	//
	//   ★★これは**テストのための仕掛け**です。要らなくなったら
	//     下の `RESET_ON_EXIT` を **0** にすれば、扉ボタンはただ「もどる」だけに戻ります。
	// ============================================================
	// ★★★2026-08-16、**0 にした**（島さんの指定で GAMEOVER から必ずタイトルへ戻るため）。
	//   ★★1 のままだと、**死ぬたびにタイトルへ戻る → そのたびに BEST まで消える**。
	//     ★育てたものは GAMEOVER でもう消えているので、ここで消す物は残っていない。
	//     ★★消えてはいけない **BEST（唯一ランをまたぐ記録）だけが道連れ**になっていた
	var RESET_ON_EXIT = 0;      // ★1 = ぜんぶ消す / 0 = ただ「もどる」だけ
	//   ★★2026-08-16: 🚪 は**液晶の外から一時停止メニューの中へ移した**ので、
	//     「遊びの中の扉」と押し間違える道は消えている
	var exitToMenu = null;      // ★シェルが渡してくれる「メニューへ戻す」

	// ============================================================
	// ★★★★GAMEOVER で、育てたものを全部なくす（2026-08-16。★島さんの指定）
	// ============================================================
	//
	//   > 島さん「なので死んだら(GAMEOVER)ステータスもリセットされる」
	//
	//   ★★★これで、この作品は**ランの中で育てて、死んだら消える**形になった。
	//     ★★お店で買ったもの（レベル・技・コイン）は**そのランのあいだだけのもの**。
	//
	//   ■ ★★なぜこれで筋が通るのか（★他の決めごとと全部つながっている）
	//     ・コインが**越えた瞬間に財布へ入る** … 走りながら使うため
	//     ・**ショップボタンが液晶の外にある** … 走りながら開くため
	//     ・**清算がない** … 持ち越す物が無いのだから、清算する物も無い
	//
	//   ■ ★★消さないもの（★「育てたもの」ではないから）
	//     ・**BEST**（いちばん進んだ距離）… ★★記録。★これだけが唯一ランをまたぐ
	//     ・**音の入り切り** … 設定
	// Hybrid rule: clear the run only; learned actions and journey records live in PR.
	function resetStatus() {
		if (st) { st.fishing = null; st.fishBtn = ""; st.live = null; st.drone = null; st.dj = false; }
		coins = 0;
		upgLv = {};
		unlocked = PR ? PR.snapshot().tricks : {};
		bag = {};                   // ★★★持ち物も無くなる（★コインやレベルと同じ）
		buys = {};                  // ★★買った回数も忘れる ＝ 値段が 120 に戻る
		items = {};                 // ★拾った鍵も忘れる（★保留中の仕組み）
		// ============================================================
		// ★★★★★テストモードでは「覚えているもの」に1ドットも触らない（2026-09-09）
		// ============================================================
		//
		//   ★`saveCoins` / `saveUpg` / `saveItems` には `if (testMode) return;` があるのに、
		//     ★★**ここだけ `localStorage` を直に消していました**。
		//   ★★★その結果、★**TEST 4950m / TEST RAIN を選ぶたびに、
		//     ふつうの遊びの 財布・レベル・技・道具が消えていました**
		//     （★`start()` は testMode のとき必ずここを通ります）。
		//
		//   ★★上の「その場の値を空にする」は**そのまま残します**
		//     （★テストは、いままでどおり**さらな状態から**始まります）。
		//     ★★★消さないようにしたのは、★**覚えているほう（localStorage）だけ**です。
		//
		//   ★2026-09-03 の決まり「★★テストは記録を汚さない」に、ここもそろえました。
		//   ★★★**AIへ: この1行を外さないこと**（★外すと、また島さんの記録が消えます）。
		//   ★★★★ 2026-09-21(6): `lsSet` がテスト中は心の中だけを消すので、
		//     ★★**島さんの本物の記録はここでは決して消えません**
		lsSet("dotollie-coins", "0");
		lsSet("dotollie-upg", JSON.stringify({ lv: {}, un: {} }));
		lsSet("dotollie-items", "{}");
		return true;
	}

	//   ★★2026-08-23、`resetStatus()` と同じ中身が並んでいたのでまとめた。
	//   ★★★**AIへ: 中身をここに書き戻さないこと**（★消すものが増えたとき、
	//     ★★**片方だけ直す**という事故が構造的に作れなくなる）
	function resetAll() {
		if (PR) PR.clear();   // ★テスト中は「記憶だけモード」なので、★★外の記録は消えない（2026-09-21(6)）
		reloadCaps();
		resetStatus();              // ★★育てたものを全部消す（★中身はあちら1か所だけ）
		best = 0;                   // ★★★ここだけが違い ＝ **記録も消す**
		lsSet(slotKey("dotollie-best"), "0");
		return true;
	}

	// ============================================================
	// ■ ★★どこに効かせるか（★表は `js/upgrades.js`。ここは当て方だけ）
	// ============================================================
	//   SPEED   … 速さ           → 距離が伸びる
	//   JUMP    … ★コマの進みを遅くする → 滞空が伸びる → ★越えられる幅が広がる
	//   STAMINA … ランの長さ
	//   COIN    … ★★障害物1個あたりのコイン（2026-08-16。★前は「最後に掛ける倍率」）
	function curSpeed()   { return SPEED + 5 * upgLevel("speed"); }
	// ★★「ジャンプ力」ではなく「**ジャンプ持続倍率**」。
	//   ★★★絵を引き伸ばして高さを変えるのではなく、**同じ絵をゆっくり再生する**。
	//     → `CLAUDE.md` の「高さは絵が決める／物理を足し戻さない」を守っている
	// ★★★2026-08-16、島さんの指定で **JUMP のアップグレードは廃止**した。
	//   > 「ジャンプレベルは廃止。」
	//
	//   ★★仕組みはここに残してある（★`js/upgrades.js` に "jump" が無いので、いまは必ず 1）。
	//     ★1 ＝ **島さんが描いた絵のコマを、そのままの速さで送る**
	//     ＝ 滞空も越えられる幅も、`js/frames.js` の時間がそのまま出る
	//   ★戻したいときは `js/upgrades.js` に "jump" の行を足すだけ（★ここは触らない）
	function jumpDurationMul() { return upgMul("jump"); }
	// ★★★2026-08-16、島さんの指定で**整数の「回数」に丸める**。
	//   > 「体感出来る最小の成長をもっと序盤に設定したい」
	//   ★スタミナは「あと何回ミスできるか」なので、5.4回 では**何も変わっていない**。
	//     ★★丸めることで、**1段買えば必ず1回ぶん増える**（＝ 買った実感が出る）
	function curStaminaMax()   { return STAMINA_MAX + upgLevel("stamina"); }
	// ★★障害物を1つ越えたときのコイン（★COIN Lv で増える）。
	//   ★2026-08-16、COIN は「最後にまとめて掛ける倍率」だった。
	//     ★★**1個あたりの枚数**に変えた（島さん「コイン獲得枚数が上がるように」）
	function curCoinPer()      { return COIN_PER * upgMul("coin"); }

	// ★★その技を覚えているか。★オーリー（tap）は最初から使える
	function knowsTrick(name) {
		var id = String(name).toLowerCase();
		if (!UP || !UP.findUnlock(id)) return true;   // ★アンロックの表に無いもの＝最初から使える
		return !!unlocked[id];
	}

	// ------------------------------------------------------------
	// ■ ★★貯めたコイン（2026-08-15 / 成長型コア）
	//   ★覚え方は BEST とまったく同じ。★保存できなくても遊べる
	//   ★これがアップグレードの元手になる（Phase B）
	// ------------------------------------------------------------
	var coins = 0;

	function loadCoins() {
		try {
			var v = parseInt(lsGet("dotollie-coins"), 10);
			coins = (isFinite(v) && v > 0) ? v : 0;
		} catch (e) { coins = 0; }
		return coins;
	}

	function saveCoins() {
		// ★★★★★テスト中は覚えない（2026-09-03。★`updateBest` と同じ考え方）
		//   ★★テストモードは**お金を持って始まります**（1T）。
		//     ★それを覚えてしまうと、★★★**次にふつうに始めたとき 1T のまま**になります
		//     （★実際にそうなって、テストが捕まえました）。
		//   ★★★テストで**本物の記録を汚さない**のが、この作品の決まりです。
		//   ★★★★ 2026-09-21(6): `lsSet` がテスト中は心の中へ書く
		lsSet("dotollie-coins", String(coins));
		return coins;
	}

	function addCoins(n) {
		coins += n;
		touchSave();          // ★★旅の記録のほうも、このあとまとめて書く（2026-09-21(6)）
		return saveCoins();
	}

	// ============================================================
	// ■ ★★★★★旅のセーブ（2026-09-13 島さんの指定 ／ Astra の方針を引き継いだ）
	// ============================================================
	//   ★保存するのは一時停止の「SAVE+QUIT」を押したときだけ。
	//   ★★CONTINUE で読んだら消す（★1つのセーブを何度もやり直しに使えない）。
	//   ★★★GAMEOVER でも消す（★「死んだら最初から」を崩さない）。★テストでは書かない
	// ★★★★★セーブスロット（2026-09-13）。★保存名はスロットごと（→ js/progression.js の slotKey）
	function slotKey(base, n) {
		return (PR && PR.slotKey) ? PR.slotKey(base, n) : base;
	}
	function saveKey(n) { return slotKey("dotollie-save-v1", n); }
	// A deadline, not simulation dt: menus, suspension and reload cannot extend the boost.
	var boostMemory = {};
	function boostDeadline(n) {
		var key=slotKey("dotollie-boost-v1",n);
		if(Object.prototype.hasOwnProperty.call(boostMemory,key))return boostMemory[key];
		try { var value=Number(lsGet(key));return boostMemory[key]=Number.isFinite(value)&&value>0?value:0; }
		catch(e){return boostMemory[key]||0;}
	}
	function setBoostDeadline(value) {
		if(testMode && value>0)return;
		var key=slotKey("dotollie-boost-v1");boostMemory[key]=value;
		lsSet(key,String(value));
	}
	function boostView(n) {
		var end=(testMode && n===undefined)?0:boostDeadline(n),left=end-Date.now();
		var seconds=Math.max(0,Math.ceil(left/1000)),active=left>0;
		return {active:active,remaining:seconds,multiplier:active?5:1,urgent:active&&left<=30000,
			text:active?"BOOST ×5 "+String(Math.floor(seconds/60)).padStart(2,"0")+":"+String(seconds%60).padStart(2,"0"):
				(end && left>-1500?"BOOST END":"")};
	}
	function boostMultiplier() { return !testMode && boostDeadline()>Date.now()?5:1; }
	var SAVE_ST = ["dist", "stamina", "staminaMax", "hp", "hpMax", "dayMs", "dj", "met", "coin",
		"betMul", "betCount", "goalBorn", "goalDone", "gateBorn", "gatePassed", "mileIndex",
		"hits", "picksGot", "campSeen", "lastMark", "phase", "phaseMs", "speedMs", "air", "airJumps", "djBase", "trick",
		"idle", "idleMs", "nextPush", "cones", "picks", "nextCone", "nextEnemy", "nextBird", "nextRail", "nextPick", "nextAosura",
		"grind", "grindEndWx", "grindCoin", "grindPaid", "grindDots", "slowMs", "live", "recoverProgress"];
	//   ★★★★★ 2026-09-21(6): **キャンプからでも保存できます**。
	//     ★前は一時停止メニューからしか呼べず、
	//     ★★**キャンプで遊んだ分はまるごと保存できませんでした**。
	//     ★キャンプの中にいるときは `campPhase` も一緒に保存します（★戻るとキャンプ）
	function saveRun() {
		if (!st || st.phase === "over" || st.stamina <= 0) return false;
		var data = { v: 1, seed: WD.getSeed(), m: meters(), coins: coins, upgLv: upgLv,
			unlocked: unlocked, bag: bag, buys: buys, items: items, st: {} };
		SAVE_ST.forEach(function (k) { data.st[k] = st[k]; });
		data.grindIndex = st.cones.indexOf(st.grindRail);
		// ★★キャンプにいたなら、戻ったときもキャンプ（★`mine` / `fish` / `trip` は外に出してから）
		data.camp = (st.campPhase === "in" || st.campPhase === "mine" || st.campPhase === "fish" || st.campPhase === "trip") ? 1 : 0;
		// ★★★★★**このセーブをどこで作ったか**を、★**セーブ自身に**書きます（2026-09-22）。
		//   ★★前は旅の記録の `resumeMode` だけを見ていて、
		//   ★★★**昔キャンプで 1 回 SAVE しただけで、以後ずっとキャンプから始まる**事故になりました。
		data.mode = data.camp ? "camp" : "run";
		data.rev = (PR && PR.snapshot ? (PR.snapshot().rev || 0) : 0);
		return lsSet(saveKey(), JSON.stringify(data));
	}
	function peekSave(n) {
		try {
			var o = JSON.parse(lsGet(saveKey(n)));
			return (o && o.v === 1 && Number.isFinite(o.seed) && o.st && Number.isFinite(o.st.dist) && o.st.dist>=0 &&
				Number.isFinite(o.st.stamina) && o.st.stamina>0 && Number.isFinite(o.coins) && o.coins>=0 &&
				o.upgLv && typeof o.upgLv === "object") ? o : null;
		} catch (e) { return null; }
	}
	function deleteSave() { lsDel(saveKey()); }
	function applySave(o) {
		coins = Number(o.coins) || 0;
		upgLv = o.upgLv || {}; bag = o.bag || {}; buys = o.buys || {}; items = o.items || {};
		for (var id in (o.unlocked || {})) if (o.unlocked[id]) unlocked[id] = true;
		SAVE_ST.forEach(function (k) { if (o.st && o.st[k] !== undefined) st[k] = o.st[k]; });
		st.grindRail = st.grind ? st.cones[o.grindIndex] || null : null;
		if(st.grind && !st.grindRail) st.grind=0;
		if(!o.st.cones && !st.goalDone) st.goalBorn=false; // Older saves did not include the visible goal.
		st.paused=true; st.pauseBtn=""; st.tapArmed=false; clearActionAssist();
		if(st.live && st.live.sinceClear===null) st.live.sinceClear=Infinity;
		saveCoins(); saveUpg(); saveItems();
	}
	// ★NEW GAME で「置き換える旅」があるか（★セーブか、覚えた技・転生・釣果・走った記録）
	//   ★`n` を渡すと、切り替えずにそのスロットを覗く（★タイトルのスロット一覧用）
	function hasJourney(n) {
		if (peekSave(n)) return true;
		if (!PR) return false;
		var p = (n && PR.peek) ? PR.peek(n) : PR.snapshot();
		if (!p) return false;
		return p.rank > 0 || !!p.doubleJump || p.lastDistance > 0 ||
			Object.keys(p.tricks || {}).length > 0 || Object.keys(p.caps || {}).length > 0 ||
			Object.keys(p.fish || {}).length > 0;
	}

	// ------------------------------------------------------------
	// ■ 状態
	// ------------------------------------------------------------
	// ★★`instant` = **やり直し**（2026-08-15 / Phase 3）
	//   島さん「クラッシュ → タップ → **即スタート**。ここは『もう一回』を成立させるうえで重要」
	//
	//   ★**初回は今までどおり**（`enter 500ms → READY 800ms → GO 500ms` の 1.8秒）。
	//     2026-08-12 に島さんが設計した「**どんな世界に来たかを見る間**」を壊さないため。
	//   ★★**やり直しのときだけ** `play` から始める。
	//     ただし**走り出しの加速は残す**（`speedMs = 0` から）。
	//     島さんの指定「**GOでいきなりトップスピードはおかしい**」はやり直しでも同じ
	function reset(seed, instant) {
		// ★★どの世界に入るかを決める（→ js/world.js）
		//   ★シェルから種を渡されたら**それを使う**（SEED ID 画面で見せた番号と必ず一致する）。
		//     渡されなければ、いままでどおり自分で引く（テストはこの道を通る）
		if (typeof seed === "number") WD.setSeed(seed); else WD.newSeed();
		PD.reset();      // ★世界が変わったので、焼いてあった背景の紙を捨てる
		st = {
			// ★★スタートの段。
			//   "enter"(世界を見せるだけ) → "ready" → "go"(動き出す) → "play"
			//   ★enter と ready は**世界が止まっている**
			phase: instant ? "play" : firstPhase(),
			phaseMs: 0,
			speedMs: 0,     // ★GO からの経過（走り出しの加速に使う）
			dist: 0,      // 進んだ距離（ドット）
			air: -1,      // ★技の進み具合（ミリ秒）。-1 = 転がっている
			assistClock: 0, inputBuffer: null, grindGrace: null, cornerShift: 0,
			assistPrevLift: null,
			trick: 0,     // ★いま出している技（POSES の何番目か）。air >= 0 のときだけ意味を持つ
			// ★地上の姿（技を出していないとき）
			// ★★始まりは「立ち」。**プッシュ（走り出し）は GO の瞬間から**（島さん 2026-08-12）
			//   ★世界が止まっているのに蹴っているのは変なので、GO まで待つ
			idle: I_STANDBY,
			idleMs: 0,      // その姿の進み具合（ミリ秒）
			nextPush: 0,    // 次にプッシュするまでの残り（秒）
			paused: false,
			// ★三角コーン。画面の右から流れてくる。中身は { x } だけ
			cones: [],
			nextCone: 0,   // 次のコーンを出すまでの残り距離（ドット）
			nextEnemy: 0,   // ★次の敵（丘の障害物）を出すまでの残り距離
			// ★★★★拾えるコイン（2026-08-23 島さんの指定）
			picks: [],      // ★いま画面にあるコイン（★{ x, lift, taken }）
			nextPick: 0,    // ★次の弧を出すまでの残り距離
			picksBorn: 0,   // ★このランで出した弧の数（★実測用）
			picksGot: 0,    // ★★拾った枚数（★実測用）
			pickBeat: 0, pickQuiet: false,
			conesBorn: 0,  // ★これまでに出したコーンの数（テストが見張るためだけの数）
			// ★★★★レール（2026-08-31 島さんの指定）
			grind: 0,        // ★★いま乗っているか（0/1）
			grindRail: null, // ★いま乗っているレール（★降りるときに印を付けるため）
			grindEndWx: 0,   // ★乗っているレールの右端（★世界の座標）
			grindCoin: 0,    // ★このレールで貯まったコイン（★小数のまま持つ）
			grindPaid: 0,    // ★そのうち、もう財布へ入れたぶん
			grindDots: 0,    // ★★このレールで進んだ距離（★テストと実測が見る）
			trackDots: 0,    // ★★★★トラックの火花のものさし（2026-08-31）
			nextRail: 0,     // ★次のレールまでの距離
			railsBorn: 0,    // ★これまでに出したレールの数（★実測用）
			scrapeDots: 0,   // ★★★擦れ続ける音を「距離で」数える（★火花と同じ）
			scrapeStep: 0,   // ★★高さを少しずつ変えるための番号
			enemiesBorn: 0,  // ★これまでに出した敵の数
			birdsBorn: 0,    // ★★★★これまでに出した飛ぶ敵の数（2026-08-23）
			// ★★★★ゴールの扉（2026-08-22。★5000m のエンディング）
			goalBorn: false,  // ★このランで扉をもう置いたか（★1回だけ）
			goalDone: false,  // ★★このランでもうエンディングを見たか（★二度は出さない）
			endMs: 0,         // ★エンディングの進み具合（ミリ秒）
			endPage: 0,       // ★★★いま何ページ目を見せているか（2026-08-22）
			pageMs: 0,        // ★★そのページを見せはじめてからの時間（2026-08-23）
			// ★★★★二段ジャンプ（2026-08-22 島さんの指定）
			dj: false, // Every journey starts without double jump; buy SHOES during this run.
			airJumps: 0,      // ★いまの滞空で、もう何回跳んだか
			djBase: 0,        // ★★二段目を出したときの「足元の高さ」（★下駄）
			giftMs: 0,        // ★授かる場面の進み具合（ミリ秒）
			giftRang: false,  // ★喜びの音をもう鳴らしたか（★二度鳴らさない）
			// ★★扉と鍵（2026-08-16 / Phase C）
			gateBorn: false,  // ★このランで扉をもう出したか（★決まった距離に**1回だけ**）
			gateSeen: false,  // ★このランで扉が画面に出たか（★実測用）
			gatePassed: false,// ★★このランで扉を**突破したか**
			keysBorn: 0,      // ★このランで出した鍵の数（★実測用）
			gotKeyNow: false, // ★★このランで鍵を拾ったか（★実測用）
			nextKey: KEY_TRY_GAP,  // ★次に鍵を抽選するまでの残り距離
			// ★★★キャンプ・HP・死亡（2026-08-16 / Phase D）
			hp: HP_MAX,       // ★★0 になったら死亡（★未確定分を全部失う）
			hpMax: HP_MAX,
			died: false,      // ★★このランは「死んだ」か（★撤退とは違う）
			campBorn: 0,      // ★次に出すキャンプは何個目か
			campsSeen: 0,     // ★このランで出会ったキャンプの数（★実測用）
			campSel: 0,       // ★キャンプの選択（0=キャンプする / 1=このまま進む）
			campStopMs: 0,    // ★キャンプに着いてから選べるようになるまで
			campObj: null,    // ★いま選んでいるキャンプ
			gateStopMs: 0,    // ★★扉で止められたあと、リザルトへ行くまでの残り（見せる時間）
			gateFlashMs: 0,   // ★扉が光っている残り（★描画だけ）
			// ★★次に置くパターン（A→B→C→D の巡回）。★種では決めない
			patIndex: 0,
			// ★★ラン終了のときに残す記録。over のときだけ意味を持つ
			reached: 0,      // そのプレイで進んだ距離（メートル）
			newBest: false,  // ★BEST を更新したか
			earned: 0,       // ★そのランで稼いだコイン
			// ★★走行の経済（2026-08-15 / 成長型コア）
			stamina: curStaminaMax(),     // ★0 になったらラン終了
			staminaMax: curStaminaMax(),  // ★★このランの満タン（★バーの割合に使う）
			gainFlashMs: 0,        // ★コインが増えた瞬間の跳ね（★描画だけ）
			// ★★★★★転生（2026-09-12）。★どちらも**見た目だけ**です
			prestigeMs: 0,         // ★パネルのグリッチフェードインの残り（ミリ秒）
			prestigeAsk: false,    // ★★「REBORN?」を聞いているところ
			prestigeBtn: "",       // ★★★いま押しているボタン（"yes" / "no"）
			prestigeSeen: false,   // ★★行が出るのをもう知らせたか
			shopOpen: false,       // ★★ショップボタンで開いているか（2026-08-16）
			// ★★★★★キャンプモード（2026-09-04 島さんの指定）
			//   ★**お店とまったく同じ形**（★開くと世界が止まる ＝ `update()` の early return）。
			//   ★★だから **`dayMs`（夜の時計）も自動的に止まります**
			campSeen: false,       // ★★このランで一度でも開いたか（★ボタンを光らせるのに使う）
			// ★★★★★キャンプの中（2026-09-04 島さんの指定）
			//   "" = 入っていない / "ask" = CAMP? / "in" = 中 / "sleep" = 出ますか
			//   ★★★★★2026-09-04(5)、**"box" が増えました**（★リュックサックの中身）
			//     "" / "ask" / "in" / "bag"（リュックに近づいた）/ "box"（中身）/
			//     "sleep"（出ますか）/ "fade"（眠りにつく暗転）
			campPhase: "", trip: null,
			lastMark: PR ? PR.snapshot().lastDistance : 0, moment: "", hpGrowMs: 0,
			fishing: null, fishBtn: "", // 釣果はこのランだけ。再訪時は保持。
			campBagMs: 0,          // ★リュックに近づいてからの時間（★通りすがりよけ）
			// ★★★★★いま指で押しているボタン（2026-09-04）。"" / "yes" / "no"
			//   ★押しているあいだだけ、島さんの「押した絵」（緑）に変わります
			campBtn: "",
			campX: 0, campY: 0,    // ★中のプレイヤーの居場所（★240×160 の紙の中）
			starMs: 0,             // ★★★★★次の星までの時計（2026-09-05）
			rainMs: 0,             // ★★★★★次の雨粒までの時計（2026-09-06）
			nextAosura: 0,         // ★★★★★次の青スライムまで（2026-09-05）
			aosuraBorn: 0,         // ★出た数（★実測のため）
			campVX: 0, campVY: 0,  // ★★いま歩いている向き（★指のスライドで決まる）
			// ★★★★★キャンプの中を歩く姿（2026-09-05、島さんが描いた）
			campDir: CAMP_DIR0,    // ★いま向いているほう（★止まっても覚えている）
			campWalkMs: 0,         // ★★歩いた時間（★コマを送るための時計）
			campExitMs: 0,         // ★出口に足を入れてからの時間（★誤って出ないための「間」）
			saveBtn: "", saveOkMs: 0,   // ★★★★★キャンプの SAVE 看板（2026-09-21(6)）
			roadBtn: "",               // ★★★★★キャンプから本編へ戻る ROAD 看板（2026-09-22）
			distCommitted: 0,      // ★★総距離にもう繰り入れたところ（★二重に数えない）
			// ★★★★★キャンプを出るときの「間」（2026-09-04(4) 島さんの指定）
			campFadeMs: 0,         // ★暗くなっていく途中（ミリ秒）
			campDarkMs: 0,         // ★★まっ暗のまま待っている時間（2026-09-04(6)）
			campReadyMs: 0,        // ★★★朝の音のあと、READY が出るまでの残り
			wakeMs: 0,             // ★★明るくなっていく残り（ミリ秒）
			// ★★★朝スタートした場所（★ここの周りには何も置かない）。
			//   ★★**null ＝ まだ一度も朝スタートしていない**
			//     （★0 は「世界の原点」という**本物の場所**なので、0 で判断しない）
			wakeWx: null,
			// ★★★このランで越えたモンスターの数（★種類ごと）。
			//   ★★★★**死ねば消えます**（★コイン・レベル・技とまったく同じ）。
			//     ★永久に残るのは「会った種類」だけ（→ `metKinds`）
			met: {},
			overFadeMs: 0,         // ★★GAMEOVER の暗転が、どこまで進んだか（2026-08-16）
			coin: 0,               // ★★積分した稼ぎ（毎コマ「距離 × そのときの倍率」を足す）
			// ★★★★絵を動かすための時計（2026-08-27。★敵のコマ送りに使う）
			//   ★★**見た目だけの時計**。★遊び（当たり判定・距離・コイン）には1ドットも触りません。
			//   ★★★止まっているとき（PAUSE / READY / エンディング）は進みません
			animMs: 0,
			// ★★★★★昼と夜の時計（2026-09-02 島さんの指定）。★見た目だけ
			//   ★★**プレイしている時間**（★止まっているあいだは進まない）。
			//   ★★★死んだら 0 に戻る ＝ **そのランのあいだだけ**（★コイン・技と同じ）
			dayMs: 0,
			hitFlash: 0,           // ★★★★ダメージのフラッシュ。★残りコマ数（2026-08-27）
			reviveMs: 0,           // ★★MAXdrink で全回復した演出の残り（2026-08-22）
			// ★★★★BET（2026-08-23 島さんの指定）。★どれも**そのランのあいだだけ**
			betMul: 1,             // ★いまコインが何倍か（★1 = 賭けていない）
			betCount: 0,           // ★何回賭けたか
			betFlashMs: 0,         // ★払った瞬間の点滅の残り
			slowMs: 0,             // ★ぶつかったあとの減速の残り
			hits: 0,               // ★ぶつかった回数（★テストと実測が見る）
			// ★★報酬フィードバック（2026-08-15）
			pops: [],              // ★頭上に出る数字（★1か所に集約）
			// ★★★★跳んだ軌跡のきらめき（2026-08-30 島さんの指定）
			//   ★★**世界の座標**で持つ（★画面ではない）＝ 置いたら地面と一緒に後ろへ流れる
			sparks: [],            // ★いま出ている粒
			sparkMs: 0,            // ★次の1粒までの時計
			// ★★★★★つぶまき（2026-08-31 島さんが名づけた仕組み）
			//   ★★**跳ぶときのけむりも、着地のけむりも、ぜんぶこの1つの入れ物**。
			//   ★きらめきと同じく**世界の座標**で持つ（★置いたら後ろへ流れる）
			dusts: [],             // ★いま舞っている粒（★＝つぶまきの粒）
			shakeMs: 0,            // ★★揺れの残り（★描画だけ）
			mileIndex: 0,          // ★次に出す距離の節目
			// ★★コインのカウントアップ（★表示だけ。貯金には触らない）
			countMs: 0,
			// ★★お店のカーソル。★**0 = START** なので、タップ1回で即もう一回
			shopSel: 0,
			// ★お店で「押したけど、まだ離していない」か（→ `inputUp` の説明）
			tapArmed: false
		};
		// ★★★テストモード: 決めた距離から走り出す（2026-08-22 島さんの指定）。
		//   ★★地形も背景も**種と場所から毎回その場で計算している**ので、
		//     いきなり 4950m に置いても**そこの景色がちゃんと出る**（★貯めていない強み）
		if (startAtM > 0) st.dist = startAtM * SCORE_DOTS;
		// ============================================================
		// ★★★★★「雨のところから走り出す」（2026-09-06 島さんの指定）
		// ============================================================
		//
		//   > 島さん「雨をすぐ見たいから、タイトルに TEST 4950m と並べて
		//   >   TEST あめ(プラスα便利機能)をたしてください。」
		//
		//   ★★天気は**種と場所**で決まるので、★★★**強く降っている場所を探して、
		//     そこへ置くだけ**です（★天気の仕組みには1ドットも触っていません）。
		//   ★少し手前に置くので、★★**だんだん強くなって、やがて止む**まで見られます。
		//   ★★★見つからなければ、いちばん強かったところへ置きます（★必ずどこかで降る）
		//   ★★★★★**ゴールより手前で探すこと**（★ここを間違えて一度踏んだ罠）。
		//     ★探す幅を広げすぎると、★★**ゴール（5000m）より先から走り出して**、
		//     ★★★**走り出して数秒でエンディングが始まりました**（★実際にそうなった）。
		if (startAtRain > 0 && RAIN_ON) {
			var far = (GOAL_M - RAIN_TEST_MARGIN_M) * SCORE_DOTS;   // ★ここまでで探す
			var bx = -1, bestR = 0;
			for (var rx = 0; rx < far; rx += 50) {
				var rr = rainAt(rx);
				if (rr > bestR) { bestR = rr; bx = rx; }
				if (bestR >= startAtRain) break;
			}
			// ★見つからなければ、★★**その幅でいちばん強かったところ**を使う
			if (bx >= 0) {
				// ★★★少し手前へ戻して、**強くなっていくところから**見せる。
				//   ★★ただし「**もう降っている**」ところまで
				//     （★戻しすぎると、★★★晴れから始まってしまいます）
				var sx = bx;
				for (var back = 25; back <= RAIN_TEST_BEFORE; back += 25) {
					var px = bx - back;
					if (px < 0) break;
					if (rainAt(px) < RAIN_TEST_MIN) break;
					sx = px;
				}
				st.dist = sx;
			}
		}
		// ★★★★★昼と夜の時計を、途中から始める（★天気をぜんぶ見るため）
		//   ★時計は `st.dayMs` の**1つだけ**（★新しい時計は足していません）
		if (startAtDay >= 0) st.dayMs = startAtDay;
		st.nextCone = nextConeGap();
		st.nextEnemy = nextEnemyGap();
		st.nextTori = nextToriGap();      // ★★★★丘の敵その2（鳥）。2026-08-27
		st.nextAosura = nextAosuraGap();  // ★★★★★丘の敵その3（青スライム）。2026-09-05
		st.nextRail = nextRailGap();      // ★★★★レール（2026-08-31）
		st.nextBird = nextBirdGap();      // ★★★★飛ぶ敵（2026-08-23）
		st.nextPush = nextPushWait();
		// ★★やり直しは「もう走り出している」ところから始める。
		//   ★プッシュ（蹴り出し）も GO のときと同じように入れる（`goNow()` と同じ形）
		if (instant) {
			st.idle = I_PUSH;
			st.idleMs = 0;
		}
	}

	function meters() { return Math.floor(st.dist / SCORE_DOTS); }
	function metersOf(dots) { return Math.floor(dots / SCORE_DOTS); }

	// ------------------------------------------------------------
	// ■ ★地面の読み方（2026-08-11）
	//   ★**ドット単位に丸めてから**世界を読む。
	//     丸めないと、地面が1ドット未満でにじんで**ちらつく**（ドット絵が濁る）
	// ------------------------------------------------------------
	function worldX() { return Math.round(st.dist); }        // 画面の左端は世界のどこか

	// 画面の col 列目の「地面の面」の行。★小さいほど高い
	function groundRowAt(col) { return GROUND - WD.groundAt(worldX() + col); }

	// スケーターの足元の行（＝いま乗っている地面）
	// ★★主役が乗る行。★★★**描くところも拾うところも、全部ここを通る**
	//   ★だから `RIDER_SINK` をここに入れるだけで、★★**見た目と当たり判定が必ずさわる**
	function riderFootX() { return RIDER_X + RIDER_FOOT + (st ? st.cornerShift || 0 : 0); }
	function riderGroundRow() { return groundRowAt(riderFootX()) + RIDER_SINK; }
	// ★★★主役の足が、いま画面の何行目にいるか
	//   ★★**高さを2か所に書かないための1か所**（★きらめきもテストの覗き窓もここを通す）。
	//     ★2026-08-22、当たり判定の数字だけ直して**絵を描くところを直し忘れた**事故があった
	function riderFootRow() { return riderGroundRow() - 1 - currentLift(); }

	// 次のコーンまでの間隔をランダムに引く
	// ★★1回の技のあいだに進む距離（★いまの速さとジャンプ倍率で**毎回計算する**）
	//   ★直書きしないこと。★島さんが `js/frames.js` のコマを速くしたら、ここも自動で追従する
	function trickTravelDots() {
		return FR.totalMs(POSES[poseIndex("OLLIE")].ms) * jumpDurationMul() / 1000 * curSpeed();
	}

	// ============================================================
	// ■■■ ★★★★拾えるコインの「一列」（2026-08-23 島さんの指定）■■■
	// ============================================================
	//
	//   > 島さん「コインは「弧」でなく横に整列にしてください。とりこぼしがあってもいい。
	//   >   そのほうがマグネットが生きる。」
	//
	//   ★★★**高さは島さんの跳躍の絵（`lifts`）から取る**（★直書きしない）。

	// ★★コインを置く高さ ＝ **オーリーがいちばん高く上がるところ**
	//   ★★★＝「跳んで届くいちばん上」。★島さんが絵を変えたら、ここも自動で追従する
	function pickLift() {
		var P = POSES[poseIndex("OLLIE")], best = 0;
		for (var i = 0; i < P.lifts.length; i++) if (P.lifts[i] > best) best = P.lifts[i];
		return best;
	}

	// ★★並びを1つ引く（★表の `weight` にしたがう。★種では決めない）
	function pickPattern(beat) {
		var options = PICK_PATTERNS;
		if (typeof beat === "number") {
			options = PICK_PATTERNS.filter(function (p) { return p.phase === beat % 4; });
		}
		var total = 0, i;
		for (i = 0; i < options.length; i++) total += options[i].weight;
		var r = Math.random() * total;
		if (total <= 0) return options[0];
		for (i = 0; i < options.length; i++) {
			r -= options[i].weight;
			if (r < 0) return options[i];
		}
		return options[options.length - 1];
	}

	// ★1つの並びのかたち … [{ dx（先頭からの横のずれ）, lift（足元の高さ）}, …]
	//   ★★**同じ段は全部おなじ高さ**（★横に整列）。★2段のときは2つぶん入る
	//   ★★★高さは「跳んで届くいちばん上」× 表の `lift`（★直書きしない）
	function pickRow(pat) {
		pat = pat || PICK_PATTERNS[0];
		var base = pickLift();
		if (base < PICK_MIN_LIFT) return [];      // ★低すぎるなら置かない（★走って取れる）
		var out = [];
		for (var r = 0; r < pat.rows.length; r++) {
			var row = pat.rows[r];
			var lift = Math.round(base * row.lift);
			if (lift < PICK_MIN_LIFT) continue;   // ★低すぎる段は置かない
			for (var k = 0; k < row.n; k++) out.push({ dx: k * row.step, lift: lift });
		}
		return out;
	}

	// ★並びの横幅（★障害物と重ねないための確かめに使う）
	function pickRowW(row) {
		var w = 0;
		for (var i = 0; i < row.length; i++) if (row[i].dx > w) w = row[i].dx;
		return row.length ? w + PICK_W : 0;
	}

	// ============================================================
	// ★★★★列を「水平」に置く（2026-08-23 島さんの指摘）
	// ============================================================
	//
	//   > 島さん「コインが整列になっていないパターンがありました。
	//   >   おそらく地面と平行の高さに置かれているためと思われます。
	//   >   そのため、坂道にあるコインが整列でないです。平地は合格です。
	//   >   ジャンプで届く位置かつ水平においてください。そのほうが美しいです。」
	//
	//   ★★前は**1枚ずつ「その場所の地面」から高さを取っていた**ので、
	//     ★坂では列が**地面と平行に傾いて**いた。
	//   → ★★★**列の下でいちばん高い地面**を1つ選び、★そこから全部おなじ高さにする。
	//
	//   ★★「いちばん高い地面」を基準にするのが大事:
	//     ★★★どこか1枚でも地面に近づくと、★**走っているだけで拾えてしまう**。
	//     ★高いほうに合わせておけば、★列のどこでも「跳んで届く高さ」が保証される。
	//
	//   ★★★以後、コインは**画面の行（`y`）**で持つ（★地面からの高さでは持たない）。
	//     ★この作品はカメラが上下に動かないので、★**行は変わらない**
	function makeRow(x0, pat) {
		var row = pickRow(pat);
		if (!row.length) return [];
		// ★★★並びの下でいちばん高い地面（★行の数字が小さいほど高い）。
		//   ★★**並びぜんぶで1つの基準**を使うので、★2段でも**平行**にそろう
		var top = Infinity;
		for (var i = 0; i < row.length; i++) {
			var gx = x0 + row[i].dx + Math.floor(PICK_W / 2);
			var gr = groundRowAt(gx);
			if (gr < top) top = gr;
		}
		var out = [];
		for (i = 0; i < row.length; i++) {
			// ★`y` = コインの**足元の行**（★全部おなじ ＝ 水平）
			out.push({ x: x0 + row[i].dx, y: top - 1 - row[i].lift });
		}
		return out;
	}

	// ★次の弧までの距離をランダムに引く（★種では決めない ＝ 覚えゲーにしない）
	function nextPickGap() {
		return PICK_GAP_MIN + Math.random() * (PICK_GAP_MAX - PICK_GAP_MIN);
	}
	function pickRowAllowed(row) {
		var wx = worldX();
		return row.every(function (p) { return !inNoSpawn(wx + p.x - 1) && !inNoSpawn(wx + p.x + PICK_W + 1); });
	}

	// ★★1枚いくらか（★`PICK_SCALES` が 1 のときだけ COIN のレベルが効く）
	function pickValue() {
		return PICK_SCALES ? Math.max(1, Math.round(curCoinPer() * 2 / 20)) : PICK_VALUE;
	}

	// ★★★障害物どうしの最小の間隔（→ 上の「欠陥」の説明）
	//   ★直書きの `CONE_GAP_MIN` は「下駄」として残す（★遅いときはこちらが効く）
	function coneGapMin() { return Math.max(CONE_GAP_MIN, trickTravelDots() * GAP_SAFETY); }
	function enemyGapMin() { return Math.max(ENEMY_GAP_MIN, trickTravelDots() * GAP_SAFETY); }

	function nextConeGap() {
		// ★ばらつきの幅（170-80）はそのまま。**下限だけが速さについてくる**
		return coneGapMin() + Math.random() * (CONE_GAP_MAX - CONE_GAP_MIN);
	}

	// ★丘の敵までの間隔をランダムに引く（★種で決めない ＝ 覚えゲーにしない）
	function nextEnemyGap() {
		return enemyGapMin() + Math.random() * (ENEMY_GAP_MAX - ENEMY_GAP_MIN);
	}

	// ★★★★丘の敵その2（鳥）。★下限はスライムとまったく同じ作り（★速さについてくる）
	function toriGapMin() { return Math.max(TORI_GAP_MIN, trickTravelDots() * GAP_SAFETY); }
	function nextToriGap() {
		return toriGapMin() + Math.random() * (TORI_GAP_MAX - TORI_GAP_MIN);
	}
	// ★★★★★青スライム（2026-09-05）。★下限の作り方はコーン・敵と**まったく同じ**
	//   （★速さについてくる ＝ 強くなっても「越えられない間隔」にならない）
	function aosuraGapMin() { return Math.max(AOSURA_GAP_MIN, trickTravelDots() * GAP_SAFETY); }
	function nextAosuraGap() {
		return aosuraGapMin() + Math.random() * (AOSURA_GAP_MAX - AOSURA_GAP_MIN);
	}

	// ★★★★レールまでの間隔（★種で決めない ＝ 覚えゲーにしない）
	function nextRailGap() {
		return RAIL_GAP_MIN + Math.random() * (RAIL_GAP_MAX - RAIL_GAP_MIN);
	}

	// ★★★★レールと他の障害物が「ケンカしないか」を見る（2026-08-31）
	//
	//   ★★**両側が互いを見ます**（★鳥のときの教訓。★片側だけでは防げない）:
	//     ★レールを置くとき   … まわりに**何か**（コーン・敵）がいないか  → `railClashAt`
	//     ★★コーンを置くとき … その範囲に**レールだけ**が無いか          → `railNearAt`
	//
	//   ★理由: ★★避ける動きと乗る動きが同時に来ると、★★★**1ボタンでは処理できない**
	//
	//   ■ ★★★★ここで踏んだ重大なバグ（2026-08-31。★実測で見つけた）
	//     ★はじめ、コーンを置くときにも「**何か**が近くにあるか」を見ていました。
	//     ★★するとコーンが**自分たちどうしで弾き合い**、
	//       ★★★**5分あたり 39.2個 → 18.8個 と半分以下**になっていました。
	//     → ★**コーンを置くときは、レールだけを見る**（`railNearAt`）。
	//       ★★これで「レールのために遊びの数字を変えない」が守れます
	function railClashAt(wx, len, onlyRail) {
		if (!RAIL_ON) return false;              // ★止めていれば、既存の動きは1ドットも変わらない
		var a0 = wx - RAIL_KEEP, a1 = wx + len + RAIL_KEEP;
		for (var i = 0; i < st.cones.length; i++) {
			var o = st.cones[i];
			if (o.wx === undefined) continue;
			if (onlyRail && o.kind !== "rail") continue;   // ★★★コーン側はレールだけを見る
			var b0 = o.wx, b1 = o.wx + obWidth(o);
			if (b1 >= a0 && b0 <= a1) return true;
		}
		return false;
	}
	// ★★コーンを置くときに使う（★**レールだけ**を見る）
	function railNearAt(wx, len) { return railClashAt(wx, len, true); }

	// ★★★★「ケンカにならないか」を見る（2026-08-27 島さんの指定）
	//   > 島さん「他の障害物とケンカにならないように出現率を調整してください」
	//   ★★これから置こうとする場所の**まわり `TORI_KEEP` ドット**に、
	//     ★ほかの障害物（コーン・スライム・扉…）が居たら**置きません**。
	//   ★★★出現率を下げるだけでは「たまたま重なる」が起きます。★ここで**構造的に**防ぎます
	//   ★★★★2026-08-27、**両方が互いを見ます**。
	//     ★はじめは鳥だけが見ていましたが、★★**鳥を置いたあとにスライムが近づいて**きて、
	//       ★実測で「3ドットしか離れていない組み合わせ」が20個できました。
	//     ★★★片側だけでは防げません（★置く順番はどちらが先か分からない）。
	function tooCloseForTori(wx, mine) {
		for (var i = 0; i < st.cones.length; i++) {
			var o2 = st.cones[i];
			if (o2.taken) continue;
			if (mine && o2.kind === mine) continue;      // ★同じ種類どうしは、それぞれの間隔にまかせる
			var w2 = obWidth(o2) || 0;
			if (Math.abs((o2.wx || 0) - wx) < TORI_KEEP + w2) return true;
		}
		return false;
	}

	// ★★★★飛ぶ敵（2026-08-23 島さんの指定）
	//   ★下限はコーン・敵と**まったく同じ作り**（★速さについてくる）
	function birdGapMin() { return Math.max(BIRD_GAP_MIN, trickTravelDots() * GAP_SAFETY); }
	function nextBirdGap() {
		return birdGapMin() + Math.random() * (BIRD_GAP_MAX - BIRD_GAP_MIN);
	}

	// ★★★鳥と地上の障害物は、これだけ離す（ドット）
	//   ★★**「1回の技で進む距離」**から作る（★直書きしない）。
	//     ★跳んでいるあいだに鳥が来なければ、★★★**避けようがない場面が作れない**
	function birdKeepAway() { return Math.ceil(trickTravelDots() * GAP_SAFETY); }

	// ★その世界の位置の近くに、**地上の障害物**がいるか
	//   ★★鳥どうしは見ない（★並んでいても「跳ばない」で全部よける）
	function groundObstacleNear(wx, dist) {
		for (var i = 0; i < st.cones.length; i++) {
			var o = st.cones[i];
			if (o.kind === "bird" || o.kind === "key") continue;
			if (o.wx === undefined) continue;
			if (Math.abs(o.wx - wx) < dist + obWidth(o)) return true;
		}
		return false;
	}

	// 次にプッシュするまでの待ち時間をランダムに引く
	function nextPushWait() {
		return PUSH_EVERY_MIN + Math.random() * (PUSH_EVERY_MAX - PUSH_EVERY_MIN);
	}

	// ★★走り出す前（enter / READY）の姿を進める
	//   ★**立ちをループするだけ。** たまに出るプッシュの時計は動かさない
	//     （世界が止まっているのに蹴り出したら変。プッシュは GO の瞬間から）
	function updateStandby(dt) {
		st.idleMs += dt * 1000;
		var P = POSES[st.idle];
		if (FR.frameAt(P.ms, st.idleMs) < 0) st.idleMs = 0;   // 繰り返す
	}

	// ★地上の姿を進める（技を出していないときだけ動く）
	//   ・ニュートラル … ずっとループ。たまにプッシュへ切り替わる
	//   ・プッシュ     … 1回流れたらニュートラルへ戻る
	function updateIdle(dt) {
		st.idleMs += dt * 1000;
		var P = POSES[st.idle];
		var done = (FR.frameAt(P.ms, st.idleMs) < 0);
		if (P.idle === "loop") {
			if (done) st.idleMs = 0;                       // 繰り返す
			st.nextPush -= dt;
			if (st.nextPush <= 0) {                        // ★たまにプッシュ
				st.idle = I_PUSH;
				st.idleMs = 0;
			}
		} else if (done) {                                 // "once" が終わった
			st.idle = I_STANDBY;
			st.idleMs = 0;
			st.nextPush = nextPushWait();
		}
	}

	// ------------------------------------------------------------
	// ■ ★★スタートの段を進める
	//   ready … 世界は止まっている（姿だけ動く）
	//   go    … もう動いている。文字が出ているだけ
	// ------------------------------------------------------------
	// ★どの段から始まるか（★0 にした段は飛ばす）
	function firstPhase() {
		if (ENTER_MS > 0) return "enter";
		if (READY_MS > 0) return "ready";
		return (GO_MS > 0) ? "go" : "play";
	}

	// ★世界が止まっている段か（enter と ready は止まっている）
	function isFrozen(phase) {
		return phase === "enter" || phase === "ready";
	}

	// ------------------------------------------------------------
	// ■ ★★走り出しの加速 —— いまトップスピードの何割で進んでいるか（0〜1）
	//   ★かける時間は**プッシュの絵の長さ**そのもの（直書きしない）
	// ------------------------------------------------------------
	function accelSpan() { return FR.totalMs(POSES[I_PUSH].ms) / Math.pow(1.18, upgLevel("wheels")); }

	function accelFactor() {
		if (!ACCEL_ON) return 1;
		var span = accelSpan();
		if (span <= 0) return 1;
		var t = st.speedMs / span;
		if (t >= 1) return 1;
		var s = t * t * (3 - 2 * t);            // 両端がゆるやかな曲線
		return ACCEL_START + (1 - ACCEL_START) * s;
	}

	function goNow() {
		st.phase = (GO_MS > 0) ? "go" : "play";
		st.phaseMs = 0;
		// ★★ここで走り出す ＝ プッシュ（蹴り出し）はこの瞬間から（島さん 2026-08-12）
		//   ★GO より前は世界が止まっているので、蹴っていたら変
		st.idle = I_PUSH;
		st.idleMs = 0;
		st.nextPush = nextPushWait();
		sound(990, 0.07);          // ★低→高で「始まる」
	}

	// ============================================================
	// ★★★★エンディングのあと、もう一度 READY / GO を出す（2026-08-23 島さんの指定）
	// ============================================================
	//
	//   > 島さん「エンディング後再スタートするとき再度READY/GO入れて。」
	//
	//   ★★**走り出しの加速もやり直す**（`speedMs = 0`）。
	//     ★エンディングのあいだ世界は止まっていたので、★★**そこから改めて走り出す**のが自然。
	//   ★★★走り出す前は**立って待つ**（★`enter`/`ready` と同じ。★蹴っていたら変）。
	//   ★段の進み方は `updatePhase()` に任せる（★2か所に持たない）
	// ============================================================
	// ★★★★★「立って待つ姿」に戻す（2026-09-05。★★1か所にまとめた）
	// ============================================================
	//
	//   ★★世界が長く止まったあと（★エンディング／キャンプの朝）に、
	//     ★**その前の一瞬**がそのまま残ってしまう場所です。
	//
	//   ★★★2026-09-04(7)(8) で、キャンプの朝について島さんが2つ指摘しました:
	//     > 島さん「スケーターが地面と接地していること。」
	//     > 島さん「朝、✨が空中にありました。」
	//   ★★★★2026-09-05、島さんが**エンディングのあとも**確かめるよう言われ、
	//     ★**まったく同じことが起きていました**（★跳んだまま扉に着くと、
	//     　★★READY で**扉の上に浮いたまま**／★★★きらめきも空中に残っていた）。
	//
	//   → ★★**同じことを2か所に書かない**（★つぶまきと同じ決まり）。
	//     ★片方だけ直す事故が、この作品では何度も起きています
	//
	//   ★★★**消すのは見た目だけ。** ★距離・コイン・体力・当たり判定・
	//     越えた数・障害物には**1つも触りません**（★テストが毎回数えます）
	function standStill() {
		// --- ★地面へ戻す（★跳んでいても、レールに乗っていても）---
		st.air = -1;              // ★技をやめて、地面へ
		st.trick = 0;
		st.djBase = 0;            // ★★二段ジャンプの下駄も外す
		st.airJumps = 0;
		st.grindRail = null;      // ★★★レールからも降りる
		st.grind = 0;
		st.grindDots = 0;
		st.idle = I_STANDBY;      // ★★立って待つ
		st.idleMs = 0;
		// --- ★★世界に置いたままの「粒」を消す ---
		st.sparks = [];           // ★★跳んだ軌跡のきらめき
		st.sparkMs = 0;           // ★次の1粒までの時計も、はじめから
		st.dusts = [];            // ★★つぶまきの粒（★土けむり・着地けむり・火花）
		st.pops = [];             // ★頭上の "+18"
		st.shakeMs = 0;           // ★★揺れの残り
		st.slowMs = 0;            // ★★ぶつかったあとの減速
		st.hitFlash = 0;          // ★ダメージの赤いフラッシュ
	}

	function readyAgain() {
		st.speedMs = 0;             // ★★加速をやり直す（★止まったところから）
		// ★★★★★立って待つ姿に戻す（2026-09-05 島さんの確認で分かった）
		//   ★跳んだまま扉に着くと、★★**READY で扉の上に浮いたまま**でした
		//     （★実測: いちばん浮いたとき **25ドット**）。
		//   ★★★きらめきも空中に残っていました（★キャンプの朝とまったく同じ）
		standStill();
		if (READY_MS > 0) {
			st.phase = "ready";
			st.phaseMs = 0;
			sound(660, 0.06);       // ★READY の音（★はじめのときと同じ）
			return;
		}
		goNow();                    // ★READY を飛ばす設定なら、そのまま GO
	}

	function updatePhase(dt) {
		if (st.phase === "play") return;
		st.phaseMs += dt * 1000;
		if (st.phase === "enter") {
			if (st.phaseMs < ENTER_MS) return;
			// ★世界を見せる間が終わった → READY へ（READY が 0 なら そのまま GO）
			if (READY_MS > 0) {
				st.phase = "ready";
				st.phaseMs = 0;
				sound(660, 0.06);
			} else {
				goNow();
			}
		} else if (st.phase === "ready") {
			if (st.phaseMs >= READY_MS) goNow();
		} else if (st.phaseMs >= GO_MS) {
			st.phase = "play";
			st.phaseMs = 0;
		}
	}

	// ============================================================
	// ■■■ ★★当たり判定と転倒（2026-08-15 / Phase 2）■■■
	// ============================================================
	//
	//   ■ ★★縦は「足が地面についているコマ」だけ
	//     `lifts > 0`（＝島さんの絵の中で足が浮いている）あいだは**ぶつからない**。
	//     ★これが「越えられる幅」の実体。**物理の判定は作っていない**
	//
	//   ■ ★★横は「主役の足の位置」1点だけ（島さんの指定 2026-08-15）
	//     島さん「腕や頭がコーンに触れたから死亡、はゲームコアの検証を邪魔する」
	//     ★見たいのは「**跳べばコーンを越えられる**」ことだけ。
	//     ★足の位置は地面を読むのと**同じ列**を使う（2か所に持たない）
	//
	//   ★**障害物の外形を1ドットも太らせていない**（既存の決まり）
	// ============================================================
	// ★★★★二段目は「タップしたところ」から跳ぶ（2026-08-22 島さんの指定）
	// ============================================================
	//
	//   > 島さん「二段ジャンプの二回はタップしたところを基準としてほしい。
	//   >   そうじゃないとさらに高くとべない。」
	//
	//   ★★前 … 二段目も**足元 0（地面の高さ）から**絵が始まっていた
	//            → ★いったん落ちてから跳び直す形になり、**高くならなかった**
	//   ★★後 … ★★★**タップした瞬間の高さを「下駄」にして、その上に絵を重ねる**
	//
	//   ★★下駄は、二段目の絵が進むにつれて**まっすぐ 0 へ戻していく**。
	//     ★これが無いと、絵が終わった瞬間に**地面へストンと瞬間移動**して見える。
	//     ★★★物理は1つも足していません（★高さを決めているのは、いまも島さんの絵）。
	//
	//   ★`djBase` … タップした瞬間の足元の高さ（ドット）。★地上から跳ぶときは 0
	//   ★★★★2026-08-23、**ここを直しました**（島さんの指摘）:
	//     > 島さん「二段ジャンプの二回目がジャンプの途中でなく地面からとなっています。」
	//
	//     ★★★**下駄を `currentLift()` にしか足していなかった**のが原因でした。
	//       ★`currentLift()` は**当たり判定**にしか使われていません。
	//       ★★**絵を描くところ（`drawSkater()`）は、絵のコマだけで高さを決めていた**
	//         ので、★★★見た目は**まったく動いていませんでした**。
	//     → ★下駄を `djLift()` として切り出し、★★**描くところにも足しました**。

	// ★★絵がいちばん高くなる時点（ミリ秒）。★**絵から測る**＝直書きしない
	//   ★島さんがコマの長さを変えたら、ここも自動でついてくる
	// ★★★★★その姿の中で、**落ちてくる途中に「この高さ」になるコマ**を探す（2026-08-31）
	//
	//   > **島さん「レールの末端で勝手にオーリーアウトしないで。」**
	//
	//   ★★レールの末端では、★★★**跳ばずに、その高さから落ちてくる**必要があります。
	//     ★島さんの絵（オーリー）には「上がる」と「落ちる」が両方入っているので、
	//     ★★**落ちる側の、ちょうどその高さのコマ**から流せば、跳ね上がりません。
	//   ★★★**物理は1つも足していません**（★絵の後半を切り出して流すだけ）
	function fallStartMs(P, lift) {
		var top = poseTopMs(P);
		for (var i = 0; i < P.lifts.length; i++) {
			var ms = FR.startMs(P.ms, i);
			if (ms < top) continue;              // ★上がっている間は飛ばす
			if (P.lifts[i] <= lift) return ms;   // ★★落ちてきて、その高さになったところ
		}
		return FR.totalMs(P.ms);
	}

	function poseTopMs(P) {
		var best = -1, idx = 0;
		for (var i = 0; i < P.lifts.length; i++) {
			if (P.lifts[i] > best) { best = P.lifts[i]; idx = i; }
		}
		return FR.startMs(P.ms, idx);
	}

	// ★★二段目の「下駄」だけ（★絵そのものの跳躍は、コマの `y` に入っている）
	//
	//   ★★★**上がりきるまでは、タップした高さをそのまま保つ**（2026-08-23）。
	//     ★はじめは「技の進み具合で、まっすぐ減らす」形にしていたが、
	//       ★★**上がっている途中から減り始める**ので「さらに高く」が薄まっていた。
	//     ★★★いまは:
	//       タップした瞬間 … 下駄まるごと      ＝ **タップしたところが基準**
	//       絵の頂点       … 下駄 ＋ 絵の跳躍  ＝ ★★**いちばん高い**
	//       着地           … 0                 ＝ ★地面へ戻る（★瞬間移動しない）
	function djLift() {
		// ★★★★レールに乗っているあいだは、レールの高さ（2026-08-31）
		//
		//   ★★★**ここに入れるのが要**です。
		//     ★`drawSkater()` は `currentLift()` を**通りません**。
		//       絵の高さは絵（`FEET_ROW` と `f.y`）が持ち、★★コードが足すのは**下駄だけ**。
		//     ★★★だから「乗っている高さ」も**下駄で持つ**しかない
		//       （★`currentLift()` に足すと、★★**数字だけ上がって絵が動かない**
		//         ＝ 2026-08-22 に踏んだ事故とまったく同じことが起きます）。
		//   ★★★★2026-08-31、**そのレールの絵の上面**から逆算するようにしました
		//     （★`RAIL_LIFT` を直に返すと、★★坂ぎわで1行ずれます → `railTopRowAt`）
		if (st && st.grind) return st.grindRail ? railLiftOf(st.grindRail) : RAIL_LIFT;
		if (!st || !st.djBase || st.air < 0) return 0;
		var P = currentPose();
		var total = FR.totalMs(P.ms);
		var top = poseTopMs(P);              // ★絵がいちばん高くなるところ
		if (total <= top) return 0;
		if (st.air <= top) return st.djBase; // ★★上がりきるまでは、そのまま保つ
		// ★そのあと、着地までにまっすぐ 0 へ戻す
		var t = (st.air - top) / (total - top);
		return Math.round(st.djBase * (1 - Math.max(0, Math.min(1, t))));
	}

	function currentLift() {
		// ★★★★レールの高さは `djLift()` が返します（2026-08-31）。
		//   ★★ここでは**何も足しません**。★★★描くところ（`drawSkater()`）も
		//     同じ `djLift()` を通るので、**絵と数字が必ずそろいます**
		var P = currentPose();
		return P.lifts[currentFrame()] + djLift();
	}

	function assistsActive() {
		return st && !st.paused && !st.shopOpen && !st.campPhase &&
			(st.phase === "play" || st.phase === "go") && st.stamina > 0;
	}
	function clearActionAssist() {
		if (!st) return;
		st.inputBuffer = null; st.grindGrace = null;
	}
	function knownAction(how) {
		for (var i = 0; i < POSES.length; i++)
			if (POSES[i].how === how) return knowsTrick(POSES[i].name);
		return false;
	}
	function bufferAction(how) {
		if (!assistsActive() || !knownAction(how)) return;
		st.inputBuffer = { how: how, until: st.assistClock + PLAY_ASSIST.bufferMs };
	}
	function launchRailOut(lift, dots) {
		if (dots >= 45) learnJourneyAction("pop", "POP LEARNED");
		clearActionAssist();
		st.trick = poseIndex("OLLIE"); st.air = 0; st.airJumps = 1;
		st.djBase = lift;
		if (RAIL_SOUND_ON) sound(990, 0.06);
	}
	function coyoteRailOut() {
		if (!assistsActive()) return false;
		var grace = st.grindGrace;
		if (!grace || st.assistClock > grace.until + 0.000001 || st.air < 0) return false;
		// Leave from the current falling height: no teleport back up, no second rail payout.
		launchRailOut(currentLift(), grace.dots);
		return true;
	}
	function consumeBufferedAction() {
		if (!assistsActive()) { clearActionAssist(); return; }
		var pending = st.inputBuffer;
		if (!pending) return;
		if (st.assistClock > pending.until + 0.000001) { st.inputBuffer = null; return; }
		if (st.air >= 0 && !st.grind) return;
		st.inputBuffer = null;
		if (st.grind) endGrind(true);
		global.DotOllie.trick(pending.how);
	}

	// ============================================================
	// ■■■ ★★★★レールに乗る・降りる（2026-08-31 島さんの指定）■■■
	// ============================================================

	// ============================================================
	// ★★★★★レールは「まっすぐな1本」（2026-09-02 島さんの指摘で直した）
	// ============================================================
	//
	//   > **島さん「レールの坂での形は地面の傾斜にそのまま合わせると不自然に感じた。
	//   >   その理由は『登って下る』もしくは『下って上る』は現実にはみない」**
	//
	//   ★★★**そのとおりでした。** ★はじめ AI は**地面の凹凸をそのままなぞらせ**ました。
	//     ★★実測すると、★★★**22.1% のレールが、1本の中で向きを変えて**いました。
	//     ★現実のレール（階段の手すり・スケートパークのレール）は**必ずまっすぐ**です。
	//
	//   ★★→ **両端の高さを結んだ、1本のまっすぐな線**にしました。
	//     ★端は、その場所の地面から `RAIL_LIFT` ドット上。★あいだは**まっすぐ**。
	//     ★★★だから**1本の中で向きが変わることが、構造として起きません**。
	//
	//   ★★実測（★120万本ぶん試した）:
	//     ★地面から線までの高さは **10〜17ドット**（★ふつうは14）。
	//     ★★★**地面にめり込むことも、浮きすぎることもありません** ＝ 置く場所を選ばない。
	//   ★★支柱の長さは場所ごとに変わります（★これが現実のレールの姿）。
	//
	//   ★★★★**乗る高さも、この線から出します**（★描くところと1か所を共有）。
	//     ★2026-08-22 と 2026-08-31 に2度踏んだ「数字だけ動いて絵が動かない」事故を、
	//     ★★構造で塞いであります。

	// ★その絵の「上面が地面から何行上か」（★絵から出す。★直書きしない）

	function railCoinPerDot() { return curCoinPer() * 3 * (1 + upgLevel("rail") * 0.2) / RAIL_LEN * boostMultiplier(); }
	function learnJourneyAction(id, label) {
		if (unlocked[id]) return;
		unlocked[id] = true; st.moment = label;
		if (PR) PR.learn(id);
		syncShopUnlocks(true);
		addPop(label, "gain");
		var notice = st.pops[st.pops.length - 1];
		if (notice && notice.text === label) notice.y = Math.max(32, notice.y - currentLift());
		giftSound();
	}
	function drawJourneyMarks() {
		var markX = st.lastMark * SCORE_DOTS + RIDER_X + RIDER_FOOT - worldX();
		if (st.lastMark > 0 && markX > -30 && markX < W) {
			var gy = groundRowAt(Math.round(markX));
			ctx.fillStyle = GB[15]; ctx.fillRect(Math.round(markX), gy - 13, 1, 13);
			ctx.fillRect(Math.round(markX) + 1, gy - 13, 4, 3);
			global.DotFont.drawText(ctx,"LAST",Math.round(markX) - 12,gy - 23,GB[15]);
		}
	}

	function railArtTop(wx) {
		var f = RAIL.FRAMES[0];
		return (GROUND - WD.groundAt(wx)) - 1 - RAIL.FEET_ROW + f.y;
	}
	// ★★レールの上面の行。★`off` = レールの左端から何ドット目か（0〜RAIL_LEN-1）
	//   ★★★**世界の座標から出します**（★画面の座標だと、丸めで1ドット揺れる）
	function railRowAtOff(o, off) {
		if (!RAIL) return 0;
		var a = railArtTop(o.wx);
		var b = railArtTop(o.wx + RAIL_LEN - 1);
		var t = off / (RAIL_LEN - 1);
		if (t < 0) t = 0; else if (t > 1) t = 1;
		return Math.round(a + (b - a) * t);
	}
	// ★★そのレールに乗るための「足元の高さ」
	//   ★★★まっすぐな線なので、★**場所によって 10〜17 のあいだで変わります**
	//     （★乗れる余裕は ±8 なので、どこでも跳べば届きます）
	function railLiftOf(o) {
		var foot = riderFootX();
		return riderGroundRow() - 1 - railRowAtOff(o, foot - Math.round(o.x));
	}

	// ============================================================
	// ★★★★★レールに触れた瞬間の金属音（2026-09-02 島さんの指定）
	// ============================================================
	//   ★★**4つを同時に**鳴らします（★`melody()` に「0ミリ秒後」で渡す）。
	//   ★★★**`setTimeout` を直に書かないこと**（★既存の決まり:
	//     「音を並べるのは `melody()` の1か所だけ」。★散らすと**音を切っても鳴り残る**）
	function railSound() {
		if (!RAIL_SOUND_ON) return;
		var notes = [];
		for (var i = 0; i < RAIL_RATIO.length; i++) {
			var f = Math.round(RAIL_HZ * RAIL_RATIO[i]);
			if (f > 17000) continue;              // ★高すぎると耳に痛い
			notes.push([f, RAIL_DUR[i], 0]);
		}
		// ★★★きらめきを足す（★島さんが選んだ R⑤）。★`RAIL_SPARK` を空にすれば消える
		for (i = 0; i < RAIL_SPARK.length; i++) notes.push(RAIL_SPARK[i]);
		melody(notes);
	}

	// ★★★擦れ続ける音（★`RAIL_SCRAPE_ON` が 1 のときだけ）
	//   ★★2つを同時に鳴らすだけ（★同じく整数比にしない ＝ 金属）
	function railScrape() {
		var b = RAIL_SCRAPE_HZ + (st.scrapeStep % RAIL_SCRAPE_VAR) * 60;
		st.scrapeStep++;
		melody([[b, RAIL_SCRAPE_DUR, 0],
			[Math.round(b * RAIL_RATIO[1]), RAIL_SCRAPE_DUR * 0.75, 0]]);
	}

	// ★★乗る。★**技をやめて、立ち姿のままレールの高さに留まる**
	//   ★★★姿は**仮**です（★いまは立ち姿 STANDBY）。
	//     ★島さんがグラインドの絵を描いたら、`js/frames.js` に1行足して差し替えます
	function startGrind(rl) {
		st.grindGrace = null;
		st.grind = 1;
		st.grindRail = rl;        // ★★どのレールに乗っているか（★降りるときに印を付ける）
		st.grindEndWx = rl.wx + RAIL_LEN;
		st.grindCoin = 0;
		st.grindPaid = 0;
		st.grindDots = 0;
		st.air = -1;              // ★技は終わり（★`currentPose()` が立ち姿を返す）
		st.djBase = 0;
		st.airJumps = 1;
		// ★★★★★島さんが描いたグラインドの姿（2026-09-02）
		//   > **島さん「レール上のふるまい(グラインド)を描きました。」**
		//   ★★前は**立ち姿のまま**でした（★AI の仮）。★いまは島さんの絵です
		st.idle = I_GRIND;
		st.idleMs = 0;
		railSound();              // ★★★金属音（2026-09-02 島さんの指定）
	}

	// ★★降りる。★★★**オーリーの絵を流して降りる**（★下駄をレールの高さから 0 へ）
	//   ★これは二段ジャンプが既にやっている動き ＝ **地面へ瞬間移動しません**
	//   ★★`jump` が真なら「自分から跳び出した」（★タップ）
	function endGrind(jump) {
		var total = st.grindPaid;
		if (total > 0 && upgLevel("live")) {
			queueLiveTip(liveClear(total));
		}
		// ★★★★このレールには、もう乗りません（2026-08-31）
		//
		//   ★★これが無いと、★★★**跳び出した次のコマで、また同じレールに乗ります**
		//     （★下駄でレールの高さにいるので、条件がそのまま成り立ってしまう）。
		//   ★★★**1本のレールに乗れるのは1回だけ** ＝ 跳び出す判断に意味が生まれる
		// ★★★★★降りる高さは、**そのレールの絵の上面**から取る（★坂でずれないように）
		var offLift = st.grindRail ? railLiftOf(st.grindRail) : RAIL_LIFT;
		if (st.grindRail) st.grindRail.done = 1;
		st.grindRail = null;
		st.grind = 0;
		st.grindCoin = 0;
		st.grindPaid = 0;
		st.trick = poseIndex("OLLIE");
		st.airJumps = 1;
		// ============================================================
		// ★★★★★末端では**勝手に跳ばない**（2026-08-31 島さんの指定）
		//
		//   > **島さん「レールの末端で勝手にオーリーアウトしないで。」**
		//
		//   ★★**オーリーアウト ＝ 自分でタップして跳び出すこと**。
		//     ★★★レールが終わっただけで勝手に跳ぶのは、**やっていない技が出る**のと同じ。
		//
		//   ★どちらも同じオーリーの絵を流しますが、★★**どこから流すか**が違います:
		//
		//       ★タップ（自分で跳ぶ）… ★**はじめから**（`air = 0`）＋ 下駄
		//                                 → ★★レールの高さから、さらに上がって落ちる
		//       ★★末端（勝手に降りる）… ★★★**落ちてくる途中から**（`fallStartMs`）
		//                                 → ★**上がらない**。★★レールの高さから地面へ落ちるだけ
		//
		//   ★★★★はじめ「頂点から」流したら、★**足元が38ドットまで跳ね上がりました**
		//     （★頂点のコマは、絵そのものが25ドット上がっているため）。
		//   → ★★**絵が「その高さまで落ちてきた」コマ**から流すのが正しい。
		//
		//   ★★★**物理は1つも足していません**。★島さんの絵の後半を切り出して流すだけ
		// ============================================================
		if (jump) {
			launchRailOut(offLift, st.grindDots);
		} else {
			st.grindGrace = { until: st.assistClock + PLAY_ASSIST.coyoteMs, dots: st.grindDots };
			st.air = fallStartMs(POSES[st.trick], offLift);
			st.djBase = 0;
			var peak = Math.max.apply(null, POSES[st.trick].lifts);
			if (offLift > peak) { st.air = poseTopMs(POSES[st.trick]); st.djBase = offLift - peak; }
		}
		if (total > 0) addPop("+" + shortNum(total), "gain");
	}

	// ★★★★★トラックの火花を撒く（2026-08-31 島さんの指定。★つぶまきで作る）
	//   ★★**ボードとレールが擦れているところ**から、後ろへ飛び散る
	function addTrackSparks() {
		if (!TRACK_ON || !DUST_ON) return;
		var g = riderGroundRow();
		var lift = currentLift();                    // ★★いま乗っている高さ
		for (var i = 0; i < TRACK_NUM; i++) {
			var jx = Math.round((Math.random() * 2 - 1) * TRACK_SPREAD);
			pushDust({
				wx: worldX() + riderFootX() + TRACK_X + jx,
				y: g - 1 - lift + TRACK_Y,           // ★★★レールの面（★足元と同じ行）
				vx: -TRACK_BACK * (0.6 + Math.random() * 0.4),   // ★★後ろへ速く
				// ★★★★**上へ強く、下へ弱く**（2026-08-31 島さんの指定「上方向にも散らせたい」）
				//   ★負が上。★★`TRACK_DOWN` を 0 にすると**上だけ**へ散る
				vy: -TRACK_UP * (Math.random() * (1 + TRACK_DOWN) - TRACK_DOWN),
				life: TRACK_MS * (0.7 + Math.random() * 0.3),
				grav: TRACK_GRAV, cols: TRACK_COLS, kind: 2,
				lcol: TRACK_LATE,                    // ★★消え際は橙（★冷めていく）
				dimRate: 0                           // ★★★はじめは**ぜんぶ濃い**（★明るく）
			});
		}
	}

	// ★★★乗っているあいだを進める（★コインが増え続ける ＝ 島さんの指定）
	function updateGrind(moved) {
		if (!st.grind) return;
		// ★★★★トラックの火花（★出続ける ＝ 島さんの指定）
		//   ★★**進んだ距離**で数える（★速く走るほど密になる）
		st.trackDots += moved;
		while (st.trackDots >= TRACK_EVERY) { st.trackDots -= TRACK_EVERY; addTrackSparks(); }
		// ★★★★★擦れ続ける音（★いまは `RAIL_SCRAPE_ON = 0` で止めてあります）
		//   ★火花とまったく同じ数え方（★**距離で数える** ＝ 速いほど密になる）
		if (RAIL_SCRAPE_ON && RAIL_SOUND_ON) {
			st.scrapeDots += moved;
			while (st.scrapeDots >= RAIL_SCRAPE_EVERY) {
				st.scrapeDots -= RAIL_SCRAPE_EVERY;
				railScrape();
			}
		}
		var paidDistance = Math.max(0, Math.min(moved, RAIL_LEN - st.grindDots));
		st.grindDots += paidDistance;
		if (st.grindDots >= 45) learnJourneyAction("kickflip", "KICKFLIP LEARNED");
		st.grindCoin += paidDistance * railCoinPerDot();
		// ★★整数になったぶんだけ、**静かに**財布へ（★ポップは降りたときに1回）
		var whole = Math.floor(st.grindCoin) - st.grindPaid;
		if (whole > 0) { gainCoin(whole, "grind"); st.grindPaid += whole; }
		// ★終端まで来たら降りる
		if (worldX() + riderFootX() >= st.grindEndWx) endGrind(false);
	}

	// ★★★★レールに乗れるか見る（★拾えるコインと**まったく同じ形**の判定）
	//   ★★足の高さが合っていなければ乗りません（★島さんの指定「高さを合わせたら乗る」）
	function tryGrind() {
		if (!RAIL_ON || st.grind) return;
		if (st.phase !== "play" || st.air < 0) return;
		var lift = currentLift();
		var foot = riderFootX();
		for (var i = 0; i < st.cones.length; i++) {
			var o = st.cones[i];
			if (o.kind !== "rail" || o.done) continue;   // ★★一度降りたレールには乗らない
			var rx = Math.round(o.x);
			var gap = rx - foot;
			if (gap > PLAY_ASSIST.cornerPx || foot >= rx + RAIL_LEN) continue;
			// ★★★**そのレールの絵の上面**から高さを出す（★まっすぐな線の、その場所）
			var target = railLiftOf(o);
			var descending = st.assistPrevLift !== null && lift < st.assistPrevLift;
			var crossed = descending && st.assistPrevLift >= target && lift <= target &&
				st.assistPrevLift - target <= RAIL_TAKE_Y + 2 && target - lift <= RAIL_TAKE_Y + 2;
			if (Math.abs(lift - target) > RAIL_TAKE_Y && !crossed) continue;
			// Only nudge a near corner when the feet are already within 2px of its top.
			if (gap > 0) {
				if (Math.abs(lift - target) > PLAY_ASSIST.cornerPx) continue;
				st.cornerShift = Math.min(PLAY_ASSIST.cornerPx, st.cornerShift + gap);
			}
			startGrind(o);
			return;
		}
	}

	// ============================================================
	// ■■■ ★★ポップアップ —— **1か所に集約する**（2026-08-15）■■■
	// ============================================================
	//
	//   ★既存の決まり「**まん中に出す文字は1か所を通す**」と同じ思想。
	//     ★★**発生源ごとに個別に描かない。** 越えた・ぶつかった・節目、全部ここを通す
	//
	//   ★x は主役の中心／y は頭のすこし上から上昇／★画面の上端で止まる／
	//     ★寿命で必ず消える（★溜まり続けない）
	// ★★★★★その文字列を**数字の面（5×7）で出せるか**（2026-09-12）
	//   ★数字の面には、HUD が出す字しか入っていません。
	//   ★★だから「KICKFLIP」のような言葉は、★★★**自動で本文の面に戻ります**
	//     （★こうしておけば、★★**字が黙って欠けることが構造的に起きません**）。
	function popFace(text) {
		var F = global.DotFont, N = F.NUM;
		if (!N) return F;
		for (var i = 0; i < text.length; i++) if (!N.has(text.charAt(i))) return F;
		return N;
	}

	function addPop(text, kind) {
		if (!POP_ON) return;
		var F = popFace(text);
		var w = F.textWidth(text.length);
		// ★主役の中心にそろえる。画面からはみ出さないように寄せる
		var cx = RIDER_X + RIDER_FOOT;
		var x = Math.max(0, Math.min(W - w, Math.round(cx - w / 2)));
		var y = Math.max(0, riderGroundRow() - POP_TOP_GAP);
		if (st.pops.length >= POP_MAX) st.pops.shift();   // ★古いものから捨てる
		// ★`small` … 数字の面で出しているか（★飛ばせるのはこれだけ）
		// ============================================================
		// ★★★★★`dir`（パラボラでどちらへ飛ぶか）に**サイコロを使わない**
		// ============================================================
		//
		//   ★はじめ `Math.random()` で決めていたところ、
		//   ★★`test/magnet.test.js` が**落ちました**。
		//
		//   ★★★理由: ★**サイコロは世界と共用**です。
		//     ★見た目が 1 つ余分に振るだけで、★★**その先の障害物やコインの出方がずれます**。
		//     ★★★マグネットの段ごとにポップの数が違うので、
		//       ★**段によって世界が変わってしまっていました**。
		//
		//   ★★★★だから**交互に左右へ**振ります（★見た目だけの数え。★★サイコロを使わない）。
		//   ★★**AI へ: 見た目のために `Math.random()` を呼ばないこと**
		//     （★この作品の決まり「★★★見た目は遊びに 1 ドットも触らない」は、ここまで含みます）。
		st.popFlip = (st.popFlip || 0) + 1;
		st.pops.push({ text: text, kind: kind, x: x, y: y, ms: 0,
			small: (F === global.DotFont.NUM) ? 1 : 0,
			dir: (st.popFlip % 2) ? 1 : -1 });
	}

	// ★i 番目の節目は何メートルか（★表を使い切ったら、あとは一定間隔で広がる）
	function milestoneAt(i) {
		if (i < MILESTONES.length) return MILESTONES[i];
		return MILESTONES[MILESTONES.length - 1] +
			MILESTONE_STEP * (i - MILESTONES.length + 1);
	}

	function updatePops(dt) {
		for (var i = st.pops.length - 1; i >= 0; i--) {
			st.pops[i].ms += dt * 1000;
			if (st.pops[i].ms >= POP_MS) st.pops.splice(i, 1);   // ★必ず消える
		}
	}

	// ★★★★跳んだ軌跡のきらめき —— 出す（2026-08-30 島さんの指定）
	//
	//   ★★置く場所は**主役の足元**。★高さは `riderFootRow()`（＝ 絵を描くのと同じ式）
	//     から作るので、★★★**島さんが絵を描き替えたら、跡も黙って追従します**
	//   ★★★覚えるのは**世界の座標**（`wx`）。★だから置いたあとは動かず、
	//     ★★画面のほうが進んでいく ＝ **跡が後ろへ流れる**（★島さんの「手前から後ろ」）
	function addSpark() {
		if (!SPARK_ON) return;
		if (st.sparks.length >= SPARK_MAX) st.sparks.shift();   // ★古いものから捨てる
		// ★★★形は毎回ちがう ＋ 置く場所も少しずらす（2026-08-30 島さんの指定）
		//   ★★ずらすのは**見た目だけ**。★当たり判定にも遊びにも1ドットも触りません
		var jx = Math.round((Math.random() * 2 - 1) * SPARK_JITTER_X);
		var jy = Math.round((Math.random() * 2 - 1) * SPARK_JITTER_Y);
		st.sparks.push({
			wx: worldX() + riderFootX() + jx,
			y: riderFootRow() + jy,
			ms: 0,
			kind: Math.floor(Math.random() * SPARK_KINDS.length),
			// ★★★★点滅のずれ（2026-08-31）。★これが無いと**全部が同時に**点滅します
			ph: Math.random(),
			// ★★★透明度50%の粒を混ぜる（★島さんの指定）
			dim: (Math.random() < SPARK_DIM_RATE) ? 1 : 0
		});
	}

	// ★★きらめきを進める（★寿命が来たら**必ず**消える）
	//   ★★★空中にいるあいだだけ置いていく。★地上では時計を満タンにしておくので、
	//     ★**跳んだ瞬間に1粒目がすぐ出ます**（★跳ぶ処理には1文字も触らずに済む）
	function updateSparks(dt) {
		if (SPARK_ON && st.air >= 0) {
			st.sparkMs += dt * 1000;
			while (st.sparkMs >= SPARK_EVERY) { st.sparkMs -= SPARK_EVERY; addSpark(); }
		} else {
			st.sparkMs = SPARK_EVERY;   // ★次に跳んだ瞬間、すぐ1粒目が出るように
		}
		for (var i = st.sparks.length - 1; i >= 0; i--) {
			st.sparks[i].ms += dt * 1000;
			if (st.sparks[i].ms >= SPARK_MS) st.sparks.splice(i, 1);   // ★必ず消える
		}
	}

	// ★★★★跳んだときの土けむり —— 出す（2026-08-31 島さんの指定）
	//
	//   > **島さん「地面の埃や草などの小粒が舞うといい感じにならないかな。
	//   >   ０〜５粒程度がフワッと舞い降りる。」**
	//
	//   ★★★**地面を弾いた瞬間に、一度だけ**まとめて出します（★きらめきは滞空中ずっと）。
	//   ★★覚えるのは**世界の座標**（`wx`）＝ 置いたあとは地面と一緒に後ろへ流れる
	//   ★★★高さは `riderGroundRow()` を通す（★足元と同じ1か所。★2か所に書かない）
	// ============================================================
	// ■■■ ★★★★★「つぶまき」 —— 粒を撒いて、舞わせて、消す仕組み ■■■
	// ============================================================
	//
	//   > **島さん（2026-08-31）が名づけました。**
	//     ★★AI が「跳ぶときのけむり」と「着地のけむり」に別々の名前を付けようとしたら、
	//     ★★★島さん「**エフェクトをわたしとあなたで作り上げたシステムのことだよ**」。
	//
	//   ■ ★★つぶまき ＝ **これ1つで、いろんな粒が作れる仕組み**
	//
	//     ★1ドットの粒を**世界の座標に撒く**。★★粒ごとに持つのは5つだけ:
	//
	//         `vx` `vy` … ★はじめの速さ（★よこ・たて）
	//         `grav`    … ★★落ち方（★小さいほど「フワッ」と浮く）
	//         `life`    … ★寿命（★ミリ秒）
	//         `col`     … ★色（★表から1つ引く）
	//         `dim`     … ★★半透明かどうか
	//
	//     ★★★**この5つを変えるだけで、まったく別のものに見えます**:
	//
	//         跳ぶときのけむり … ★緑・**後ろへ**・高く（5〜7）・長い（760ms）
	//         着地のけむり     … ★★土色・**左右へ**・低く（2〜3）・短い（520ms）
	//
	//   ■ ★★★★守ること（★新しい粒を足すときも同じ）
	//     1. ★★**描くところ（`drawDusts`）と消えるところ（`updateDusts`）は1か所のまま**。
	//        ★★★種類が増えても**2か所に書かない**（★これがこの仕組みの芯）
	//     2. ★★★**色は実測で選ぶ**（★「緑だから」で選ばない）。
	//        ★粒が実際に通る背景を数えて、★★溶ける割合がいちばん低いものにする
	//        （★実測の例: 跳ぶ 緑21% ／ 着地 土7.8%・緑24.8%）
	//     3. ★★**世界の座標で持つ**（★画面の座標にすると、粒が主役について回る）
	//     4. ★★**高さは `riderGroundRow()` を通す**（★足元と同じ1か所）
	//     5. ★★★**遊びに1ドットも触らない**（★距離・体力・コイン・当たり判定・障害物）
	//
	//   ■ ★「きらめき」（`st.sparks`）とは**別の仕組み**です
	//     ★きらめき … ★★**動かない粒を置いていく**（＝軌跡）。★速さも重力も持たない
	//     ★★つぶまき … ★★★**撒いた粒が舞う**（★初速と重力を持つ）
	//
	//   ★★★★**これから作れるもの**（★まだ作っていない）: 雨・雪・花びら・水しぶき …
	//     ★どれも「5つの数字」を変えるだけで作れます

	// ★★★★粒を1つ撒く（★**跳ぶときも着地のときも、必ずここを通る**）
	//   ★★寿命（`life`）と落ち方（`grav`）を粒ごとに持たせてあるので、
	//     ★★★**跳ぶけむり（760ms）と着地のけむり（520ms）が、同じ入れ物で共存できる**
	function pushDust(o) {
		if (st.dusts.length >= DUST_HELD) st.dusts.shift();   // ★古いものから捨てる
		st.dusts.push({
			wx: o.wx, y: o.y, vx: o.vx, vy: o.vy,
			ms: 0, life: o.life, grav: o.grav,
			kind: o.kind || 0,       // ★★0＝跳んだとき / 1＝着地 / 2＝トラックの火花
			col: o.cols[Math.floor(Math.random() * o.cols.length)],
			// ★★★★消え際の色（2026-08-31。★つぶまきに足した6つ目）
			//   ★書かなければ、いままでどおり `C_DUST_LATE`（暗い緑）に落ちます。
			//   ★★火花は**暗い緑になると不自然**なので、★★★冷めていく色（橙）を指す
			lcol: (o.lcol === undefined ? C_DUST_LATE : o.lcol),
			// ★★はじめから薄い粒を混ぜるか（★火花は 0 ＝ ぜんぶ濃い）
			dim: (o.dimRate === undefined ? DUST_DIM_RATE : o.dimRate) > Math.random() ? 1 : 0,
			// ★★★★★流れる速さ（2026-09-05。★つぶまきに足した7つ目）
			//   ★1 = 地面と同じ（★いままでどおり）／ ★★0 に近いほど、その場に留まる。
			//   ★★★書かなければ 1 なので、けむりも火花も**1ドットも変わりません**
			par: (o.par === undefined ? 1 : o.par),
			// ★★★★★一等星か（2026-09-05）。★書かなければ 0（＝ふつうの粒）
			big: o.big ? 1 : 0,
			// ★★★★★点滅のずれ（2026-09-05。★きらめきの `ph` とまったく同じ役目）
			//   ★★これが無いと、★★★**全部が同時に**点いたり消えたりします
			ph: Math.random(),
			// ★★★★★この星はまたたくか（2026-09-05 島さんの指定）。
			//   ★書かなければ 0（＝ずっと点いている）。★★星だけが使います
			tw: o.tw ? 1 : 0,
			// ★★★★★この星のまたたきの速さ（2026-09-05 島さんの提案）。
			//   ★書かなければ 0 ＝ **みんなと同じ速さ**（★けむりも火花も使いません）
			bms: o.bms || 0,
			// ★★★★★地面に届いたとき、しぶきを上げるか（2026-09-06 島さんの指定）。
			//   ★★書かなければ 0（★けむりも火花も星も、いままでどおり静かに消えます）
			splash: o.splash ? 1 : 0
		});
	}

	// ============================================================
	// ★★★★★夜空の星を1つ置く（2026-09-05 島さんの指定）
	// ============================================================
	//   ★★**つぶまきの数字を変えただけ**です（★新しい仕組みは1つも作っていません）:
	//     ★速さ 0 ／ ★重力 0 ／ ★★流れる速さ ほぼ 0 ／ ★寿命は長めでばらばら
	function addStar() {
		if (!STAR_ON || !DUST_ON) return;
		var ox = worldX();
		// ★★★★★一等星は「真夜中」だけ（2026-09-05 島さんの指定）
		var deep = nightAlpha() >= NIGHT_A1 * STAR_BIG_FROM;
		var big = deep && Math.random() < STAR_BIG_RATE;
		pushDust({
			// ★★画面の好きなところへ（★`par` を掛けた世界の座標に直して置く）
			wx: ox * STAR_PAR + Math.random() * W,
			y: Math.random() * STAR_ROWS,
			vx: 0, vy: 0, grav: 0,          // ★★★動かない（★これが星）
			life: STAR_LIFE0 + Math.random() * (STAR_LIFE1 - STAR_LIFE0),
			// ★★一等星は**いちばん明るい色だけ**（★ふつうの星は3色から）
			cols: big ? [STAR_COLS[0]] : STAR_COLS,
			lcol: STAR_COLS[0],             // ★消え際も星の色のまま（★暗い緑に落とさない）
			dimRate: big ? 0 : STAR_DIM_RATE,   // ★★★一等星は薄くならない
			par: STAR_PAR,
			big: big ? 1 : 0,
			// ★★★★★またたく星と、ずっと点いている星を混ぜる（2026-09-05 島さんの指定）
			tw: (Math.random() < STAR_BLINK_RATE) ? 1 : 0,
			// ★★★★★またたきの速さも、星ごとにばらつかせる（2026-09-05 島さんの提案）
			bms: STAR_BLINK_MS * (1 + (Math.random() * 2 - 1) * STAR_BLINK_JIT),
			kind: 3                         // ★★3 ＝ 空のもの（★描く場所が「土」「光」と別）
		});
	}

	// ★★★夜の濃さに合わせて、星を出し続ける（★呼ぶのは `update()` の1か所だけ）
	function updateStars(dt) {
		if (!STAR_ON || !DUST_ON || !NIGHT_ON) return;
		var a = nightAlpha();
		if (a < STAR_MIN_A) { st.starMs = 0; return; }   // ★昼と、明けきったあとは出さない
		// ★★出す間隔 ＝ 寿命のまんなか ÷ 出したい数 ÷ 夜の濃さ
		//   ★これで「暮れはじめは まばら、完全な夜でいちばん多い」が自然に出ます
		var ratio = Math.min(1, a / NIGHT_A1);
		// ★★★★★雨の夜は、星が減る（2026-09-06 島さんの指定）
		//   > 島さん「夜で雨の時は星の数を減らした方が自然」
		//   ★★減らすのは「**これから生まれる数**」だけ。
		//     ★★★すでに出ている星は消しません（★パッと消えると不自然）。
		//       ★寿命が来た順に、自然にまばらになります
		ratio *= Math.max(0, 1 - RAIN_STAR_CUT * rainAmount());
		if (ratio <= 0) { st.starMs = 0; return; }   // ★どしゃ降り ＝ 雲で星が見えない
        var every = ((STAR_LIFE0 + STAR_LIFE1) / 2) / Math.max(1, STAR_MAX) / ratio;
		st.starMs += dt * 1000;
		var guard = 0;
		while (st.starMs >= every && guard++ < 64) { st.starMs -= every; addStar(); }
	}


	// ============================================================
	// ★★★★★降水量 ―― **数える場所は、ここ1か所だけ**（2026-09-06 島さんの指定）
	// ============================================================
	//
	//   ★戻すのは 0（降っていない）〜 1（いちばん強い雨）。
	//   ★★粒の数も、乗算の濃さも、**必ずここを通します**
	//     （★2か所で数えると、★★★数字と見た目がずれます ＝ この作品で2度踏んだ事故）。
	//
	//   ■ ★★★**種と場所**から、その場で計算します（★天気を覚える変数は1つもない）
	//     ★`js/world.js` の地面とまったく同じ作り方（★杭を打って、なめらかにつなぐ）。
	//     ★★サイコロ（`Math.random`）は**使いません** ＝
	//       ★★★**同じ場所へ戻れば、同じ天気**。★テストでも必ず同じになります。
	//   ★乱数の元は `DotWorld.rand`（★**正はあちら1つ**。★2か所に書かない）
	function rainWave(x, period, salt) {
		if (!WD || !WD.rand) return 0;
		var g = x / period, i = Math.floor(g), t = g - i;
		var a = WD.rand(i, salt), b = WD.rand(i + 1, salt);
		return a + (b - a) * (t * t * (3 - 2 * t));      // ★なめらかにつなぐ
	}

	// ============================================================
	// ★★★★★天気を決め打ちにする（2026-09-06）★★テストと道具のためだけの口
	// ============================================================
	//   ★★**遊びの中からは1回も呼びません**（★`_setStars()` とまったく同じ扱い）。
	//   ★★★なぜ要るか: ★雨が降ると**乗算レイヤーが濃くなる**ので、
	//     ★★画面の色が「42色そのまま」ではなくなります。
	//     ★★★色でものを見分けている見張り（★木・コイン・パレット）は、
	//       ★**晴れの日に測る**のが正しい。→ ★★テストは `_forceRain(0)` から始めます。
	//   ★null に戻せば、いつもどおり**種と場所**から決まります
	var rainForce = null;

	// ★★世界の場所 `x` の降水量（0〜1）
	//   ★★★うねりを2枚重ねる（★大きな天気 ＋ 小さなむら）＝ **降りかたが一様にならない**
	function rainAt(x) {
		if (rainForce !== null) return rainForce;
		if (!RAIN_ON) return 0;
		var sd = WD ? WD.getSeed() : 0;
		var v = 0.75 * rainWave(x, RAIN_PERIOD, sd + 5150) +
			0.25 * rainWave(x, RAIN_PERIOD / 3, sd + 5151);
		if (v <= RAIN_THRESH) return 0;                  // ★晴れ
		var u = (v - RAIN_THRESH) / (1 - RAIN_THRESH);   // ★0〜1 へ伸ばす
		if (u > 1) u = 1;
		var s = u * u * (3 - 2 * u);                     // ★★降りはじめ・止みぎわをなめらかに
		// ★★★★★「降り出したら、もう少ししっかり」（2026-09-09 島さんの指定）。
		//   ★かけるのは**ここ1か所だけ**（★降水量を数える場所は増やさない）。
		//   ★★0 は 0 のまま・1 は 1 のままなので、★★★**両端のなめらかさは崩れません**
		return (RAIN_FULL === 1) ? s : Math.pow(s, RAIN_FULL);
	}

	// ★いまの降水量（★呼ぶのはここから。★世界の場所は `worldX()` の1か所）
	function rainAmount() { return st ? rainAt(worldX()) : 0; }

	// ★★★★★雨粒を1つ降らせる（★つぶまきの数字を変えただけ）
	function addRain() {
		if (!RAIN_ON || !DUST_ON) return;
		var x = Math.random() * (W + RAIN_SPAWN_X);      // ★画面の右外からも降らせる
		// ★★★★★この1本は「遠くを降っているすじ」か（2026-09-09 島さんの「少し混ぜて」）。
		//   ★★決めるのは**1本につき1回**（★下の `for` の外）。
		//   ★★★すじの中の粒は**必ず同じ速さ**でないと、落ちながら形がほどけます
		var far = (Math.random() < RAIN_SLOW_RATE) ? RAIN_SLOW_SCALE : 1;
		// ★★★★★遠いものは、**落ちるのも・横に流れるのも、同じだけ遅い**。
		//   ★★だから `vx` も `vy` も `par` も、**同じ `far` で遅く**します。
		//   ★★★こうすると傾き（`slope`）から `far` が**丁度消えます** ＝
		//     ★**近くの雨とまったく同じ角度**で、★★速さだけが遅い。
		//   ★（★★前は `vy` だけ遅くしていたので、★★★遅い粒だけが 40 度近く寝ていました）
		var vy = RAIN_VY * far * (1 + (Math.random() * 2 - 1) * RAIN_VJIT);
		var vx = RAIN_VX * far * (1 + (Math.random() * 2 - 1) * RAIN_VJIT);
		var par = far;                 // ★★流れる速さも同じだけ遅い（★★★ここが軌道をそろえる要）
		// ★★★★画面の上で、横へ流れる速さ（★走るほど寝て見える）
		//   ★粒は `wx - ox * par` の場所に出るので、★★引くのも `curSpeed() * par`
		var vdx = vx - curSpeed() * par;
		var slope = vdx / vy;          // ★これに沿って粒を並べる ＝ ★★すじが進む向きとそろう
		// ============================================================
		// ★★★★★どこで消えるか（2026-09-12 島さんの指定でこう決めた）
		// ============================================================
		//
		//   > **島さん「宙で消える粒があってもよい。」**
		//
		//   ★だから**地面まで無理に降ろしません**。★★寿命はこれまでどおり、
		//     **降り出した列の地面**までの時間で決めます。
		//     ★★★粒は落ちながら横へ流れるので、★**丘が上がっていく先**では
		//     地面の手前で消えます（★★島さんの「あってもよい」はこれ）。
		//
		//   ★★★★逆に、**地面より下へ行ってしまう**のは別です。
		//     ★前はそういう粒を**地面の線に押し付けて**描いていたので、
		//     ★★**雨粒が地面を滑って**見えていました（★実測 6.7%、1〜2コマ）。
		//     ★★★そちらは `updateDusts()` で**触れたところで消します**。
		var g = groundRowAt(Math.round(x)) - 1;
		var flight = (g - RAIN_SPAWN_Y) / vy * 1000;
		// ★★同じ色・同じ濃さで1本にする（★1本の中でチラチラしない）
		var col = RAIN_COLS[Math.floor(Math.random() * RAIN_COLS.length)];
		var dim = (Math.random() < RAIN_DIM_RATE) ? 1 : 0;
		// ★★★★★すじの長さも、同じだけ短くする（2026-09-12）
		//   ★すじは「★★**速さのぶんだけ伸びた残像**」です。
		//   ★★★遅く見える粒が同じ長さのすじを引くと、★**棒が飛んでいる**ように見えます
		var nLen = Math.max(2, Math.round(RAIN_LEN * far));
		var wet = RAIN_SPLASH_ON && (Math.random() < RAIN_SPLASH_RATE);
		for (var k = 0; k < nLen; k++) {
			var dy = k * RAIN_GAP;                       // ★後ろのつぶほど、上に・進む逆側に
			pushDust({
				// ★★★★★粒は `wx - ox * par` の場所に出るので、
				//   ★★置きたい画面上の場所から逆算しておく（★`par` = 1 なら昔どおり）
				wx: worldX() * par + x - slope * dy,
				y: RAIN_SPAWN_Y - dy,
				vx: vx, vy: vy, par: par,
				grav: 0,                   // ★★重力なし ＝ 一定の速さで落ちる（★終端速度）
				life: Math.max(60, flight + dy / vy * 1000),
				cols: [col],
				lcol: col,                 // ★消え際も雨の色のまま（★暗い緑に落とさない）
				dimRate: dim,              // ★★1本まるごと 濃いか薄いか
				splash: (wet && k === 0) ? 1 : 0,   // ★★★★★先頭だけ、地面で跳ねる
				kind: 4                    // ★★4 ＝ 雨（★描く場所が「土」「光」「空」と別）
			});
		}
	}

	// ★★★降水量に合わせて、雨を降らせ続ける（★呼ぶのは `update()` の1か所だけ）
	//   ★★星（`updateStars`）とまったく同じ形です
	function updateRain(dt) {
		if (!RAIN_ON || !DUST_ON) { if (st) st.rainMs = 0; return; }
		var r = rainAmount();
		if (r <= 0) { st.rainMs = 0; return; }           // ★晴れ
		// ★★出す間隔 ＝ 画面を落ちきる時間 ÷ 出したい数 ÷ 降水量
		var cross = (H - RAIN_SPAWN_Y) / RAIN_VY * 1000;
		var every = cross / Math.max(1, RAIN_MAX) / r;
		st.rainMs += dt * 1000;
		var guard = 0;
		while (st.rainMs >= every && guard++ < 128) { st.rainMs -= every; addRain(); }
	}

	// ============================================================
	// ★★★★★小さな水しぶき（2026-09-06 島さんの指定）
	// ============================================================
	//
	//   > **島さん「雨粒が地面にぶつかったとき小さな水しぶきが起きる
	//   >   パターンも混ぜて。つぶまきで」**
	//
	//   ★呼ばれるのは `updateDusts()` の**1か所だけ**（★雨粒の寿命が来たところ）。
	//   ★★寿命は「**上がって戻るまで**」（★着地のけむりで作った形とまったく同じ）
	//     ＝ ★★★**地面に張り付きません**。
	function addSplash(d) {
		if (!RAIN_SPLASH_ON || !RAIN_ON || !DUST_ON) return;
		// ★★★★★粒の画面上の場所は `wx - ox * par`（★遠い雨は `par` が 1 でない）。
		//   ★★ここを `par` なしで計算すると、★★★**遠い雨のしぶきだけがとんでもない場所**に出ます
		var x = Math.round(d.wx - worldX() * ((d.par === undefined) ? 1 : d.par));
		if (x < 0 || x >= W) return;              // ★画面の外では撒かない（★見えないので無駄）
		var g = groundRowAt(x) - 1;               // ★その列の地面のすぐ上
		var n = RAIN_SPLASH_MIN +
			Math.floor(Math.random() * (RAIN_SPLASH_NUM - RAIN_SPLASH_MIN + 1));
		for (var i = 0; i < n; i++) {
			// ★★左右どちらへ跳ねるかは、つぶごとに決める
			var dir = (Math.random() < 0.5) ? -1 : 1;
			var v0 = RAIN_SPLASH_RISE * (0.6 + Math.random() * 0.4);
			var flight = 2 * v0 / RAIN_SPLASH_GRAV * 1000;   // ★上がって戻るまで（ミリ秒）
			pushDust({
				// ★しぶきは**見えている地面の上**のものなので、★★地面と同じ速さで流す（`par` = 1）
				wx: worldX() + x,
				y: g,
				vx: dir * RAIN_SPLASH_SIDE * (0.4 + Math.random() * 0.6),
				vy: -v0,                          // ★マイナスが上
				grav: RAIN_SPLASH_GRAV,
				life: flight,
				cols: RAIN_SPLASH_COLS,
				lcol: RAIN_SPLASH_COLS[0],        // ★消え際も水の色のまま（★暗い緑に落とさない）
				dimRate: RAIN_SPLASH_DIM,
				kind: 5                           // ★★5 ＝ 水しぶき（★雨と一緒に描く）
			});
		}
	}
	// 二段目を受け付けた空間に、2ドットだけ残す。既存のつぶまきで80ms後に消す。
	function addAirKick(lift) {
		if (!DUST_ON) return;
		var x = worldX() + riderFootX();
		var y = riderGroundRow() - lift;
		for (var side = -1; side <= 1; side += 2) {
			pushDust({
				wx: x + side, y: y, vx: side * 12.5, vy: 25,
				grav: 0, life: 80, cols: [16], lcol: 16, dimRate: 0, kind: 6
			});
		}
	}

	function addDust() {
		if (!DUST_ON) return;
		// ★★出る数は毎回ちがう（★０のときもある ＝ 毎回は出ない）
		var n = DUST_MIN + Math.floor(Math.random() * (DUST_NUM - DUST_MIN + 1));
		var g = riderGroundRow();
		for (var i = 0; i < n; i++) {
			var jx = Math.round((Math.random() * 2 - 1) * DUST_SPREAD);
			pushDust({
				wx: worldX() + riderFootX() + DUST_X + jx,
				y: g - DUST_Y,                                // ★ボードの面のあたり
				vx: -DUST_BACK * Math.random(),               // ★★後ろへ（★弾かれた向き）
				vy: -DUST_RISE * (0.6 + Math.random() * 0.4), // ★上向き（★マイナスが上）
				life: DUST_MS, grav: DUST_GRAV, cols: DUST_COLS, kind: 0
			});
		}
	}

	// ★★★★着地のけむり —— 出す（2026-08-31）
	//
	//   ★★★**跳ぶときと、見た目で別物にしてある**:
	//     ★跳ぶとき … 後ろへ流れながら、**高くゆっくり**舞う
	//     ★★着地   … **左右へ**速く散って、**低くすぐ**消える
	//
	//   ★★**必ず出ます**（★跳ぶときは０粒もある）。★地面は必ず叩くため
	function addLandDust() {
		if (!DUST_ON || !LAND_ON) return;
		var n = LAND_MIN + Math.floor(Math.random() * (LAND_NUM - LAND_MIN + 1));
		var g = riderGroundRow();
		for (var i = 0; i < n; i++) {
			var jx = Math.round((Math.random() * 2 - 1) * LAND_SPREAD);
			// ★★★左右どちらへ散るかは、粒ごとに決める（★跳ぶときは「後ろだけ」）
			var dir = (Math.random() < 0.5) ? -1 : 1;
			// ★★★★寿命は「**地面に戻るまで**」（2026-08-31。★実測で分かったこと）
			//   ★★はじめは全部 520ms にしていましたが、★弱く弾かれた粒は
			//     ★★★**早く地面に着いて、そこから寿命まで張り付いて**いました。
			//   ★★土の粒が**地面の土の上**にあると、色が同じで**消えて見えます**
			//     （★実測: いちばん悪い瞬間で「25%しか見えない」になっていた）。
			//   → ★★**上がって戻ってくる時間**を粒ごとに出して、それを寿命にする
			//     ＝ ★★★**どの粒も「舞い降りたところ」で消える**（★張り付かない）
			var v0 = LAND_RISE * (0.5 + Math.random() * 0.5);
			var flight = 2 * v0 / LAND_GRAV * 1000;   // ★上がって戻るまで（ミリ秒）
			pushDust({
				// ★★★**ボードの端から、外へ**（★まん中から出すと、絵に隠れて見えない）
				wx: worldX() + riderFootX() + LAND_X + dir * LAND_EDGE + jx,
				y: g - LAND_Y,
				vx: dir * LAND_SIDE * (0.4 + Math.random() * 0.6),
				vy: -v0,
				life: Math.min(LAND_MS, flight + LAND_HOLD),
				grav: LAND_GRAV, cols: LAND_COLS, kind: 1
			});
		}
	}

	// ★★★★着地の音（★★**まだ鳴りません**。`LAND_SOUND_ON = 0`）
	//   ★★★音は島さんの持ち場。★`tools/preview-sound.html` で聴き比べてから決めます
	function landSound() {
		if (!LAND_SOUND_ON) return;
		melody([[150, 0.05, 0], [110, 0.06, 40]]);   // ★仮: 低く短い2音（「ドッ」）
	}

	// ★★★★★つぶまきの粒を進める（★寿命が来たら**必ず**消える。★ここ1か所）
	//   ★★★ここにあるのは「舞い上がって落ちる」だけ。★★**遊びの物理ではありません**
	//     （★主役の跳ぶ高さも滞空も、いままでどおり**島さんの絵**が決めています）
	function updateDusts(dt) {
		// ★★★★★地面に届いた雨粒を、いったん覚えておく（2026-09-06 島さんの指定）。
		//   ★★**この場で撒かない**理由: `pushDust()` は上限に達すると
		//     ★★★**いちばん古い粒を捨てます**（`shift`）。★数えている途中で
		//     並びがずれると、★**1つぶ見落とす**ことがあります。
		//   ★だから「消す」を終えてから、まとめて撒きます
		var wet = null;
		for (var i = st.dusts.length - 1; i >= 0; i--) {
			var d = st.dusts[i];
			d.ms += dt * 1000;
			if (d.ms >= d.life) {
				// ★★★★★小さな水しぶき（★寿命が来た ＝ 地面に届いた）
				if (d.splash) (wet || (wet = [])).push(d);
				st.dusts.splice(i, 1); continue;   // ★必ず消える
			}
			d.vy += d.grav * dt;      // ★だんだん落ちてくる（★粒ごとの落ち方）
			d.wx += d.vx * dt;
			d.y += d.vy * dt;
			// ============================================================
			// ★★★★★雨は「**地面に着いたら**」消える（2026-09-12 に直した）
			// ============================================================
			//
			//   ★前は**時計だけ**（`life`）で消していました。
			//   ★★ところが粒は 1 コマで 4.3 ドットも進むので、
			//     ★★★**地面の手前でパッと消える**ことがありました
			//     （★実測: **26% が 3 ドット以上宙で消えて**いた。★★最大 7.3 ドット）。
			//
			//   ★★★いまは**地面に触れたところ**で消します。
			//     ★しぶきも**ちゃんと地面の上**から上がります。
			//   ★★`life` は**保険として残してあります**（★上で見ている）。
			//   ★★★消す処理を増やしていません（★つぶまきの決まり：この 1 か所だけ）
			if (d.kind === 4) {
				var rgc = Math.round(d.wx - worldX() * ((d.par === undefined) ? 1 : d.par));
				var rg = groundRowAt(rgc) - 1;
				if (d.y >= rg) {
					d.y = rg;                                  // ★めり込ませない
					if (d.splash) (wet || (wet = [])).push(d);
					st.dusts.splice(i, 1);
				}
			}
		}
		// ★★★★★地面に届いた雨粒の数だけ、しぶきを上げる（★撒くのはここ1か所）
		if (wet) for (var q = 0; q < wet.length; q++) addSplash(wet[q]);
	}

	// ★★★コインを増やす（2026-08-16。★倍率のかわり）
	//   ★★順序を崩さないこと: **コインを増やす → ポップを出す → 左上が反応**
	//   ★★★出す数字は**実際に増えた量**から作る（★表示だけ直書きしない）
	//   ★★★2026-08-16、島さんの報告で直した:
	//     > 「ショップが機能していない。なにも購入出来ない。」
	//
	//     ★原因: 稼ぎを**ランが終わるまで貯金に入れていなかった**。
	//       前は「お店 ＝ ランが終わったあとの画面」だけだったので、それで足りていた。
	//       ★★走っている途中に開けるようになった瞬間、**残高がいつも古い**ことになり、
	//         1本目は必ず 0 ＝ **何も買えない**。
	//     → ★★**越えた瞬間に、その場で貯金に入れる。**
	//       ★「越えたら即コイン」という島さんの指定に、貯金の動きも合わせた形
	// ★★★`kind` に "pick" を渡すと、**拾ったときの音**（チャリーン）になる（2026-08-23）。
	//   ★何も渡さなければ、いままでどおり「越えたときの軽いチャリン」
	function gainCoin(n, kind, count) {
		// ★★★★BET（2026-08-23）。★賭けたぶんだけ増える（★賭けていなければ ×1）
		//   ★★ここ1か所に掛ける ＝ **越えたコインも拾ったコインも、両方に効く**
		n = Math.floor(n * ((st && st.betMul) || 1));
		// Round each coin before batching, preserving fractional BET's original payout.
		n *= count || 1;
		// Grind distance already accrued its multiplier; tips retain their earned amount in flight.
		if(kind!=="grind")n*=boostMultiplier();
		if (n <= 0) return;
		if (!kind) queueLiveTip(liveClear(n));
		st.coin += n;
		addCoins(n);                          // ★★★その場で貯金に入る（＝すぐ買える）
		// ★★★★レールに乗っているあいだは**静かに入る**（2026-08-31）。
		//   ★毎コマ「+1」が飛ぶとうるさいので、★★**ポップは降りたときに1回**だけ出す
		//   ★左上のコインは増え続けるので、「増えている」ことは見えます
		if (kind === "grind") { st.gainFlashMs = GAIN_FLASH_MS; return; }
		if (kind === "pick") {
			st.gainFlashMs = GAIN_FLASH_MS;
			if (st.pickPop && st.pickPop.ms < 450 && st.pops.indexOf(st.pickPop) >= 0) {
				st.pickPop.amount += n;
				st.pickPop.text = "+" + shortNum(st.pickPop.amount);
				st.pickPop.x = Math.max(0, RIDER_X + RIDER_FOOT - Math.round(popFace(st.pickPop.text).textWidth(st.pickPop.text.length) / 2));
			} else {
				addPop("+" + shortNum(n), "gain");
				st.pickPop = POP_ON ? st.pops[st.pops.length - 1] : null;
				if (st.pickPop) st.pickPop.amount = n;
			}
			if (!st.pickSoundUntil || st.animMs >= st.pickSoundUntil) {
				coinSound(); st.pickSoundUntil = st.animMs + 120;
			}
			return;
		}
		addPop("+" + shortNum(n), "gain");
		st.gainFlashMs = GAIN_FLASH_MS;
		// ★★★2026-08-16、島さんの一言で足した:
		//   > 「コイン清算したときのあの気持ちいい音がなくなったのは寂しいよね。」
		//
		//   ★★数え上げの音（ラン終了）は**消えていない**（★確かめた。1.2秒で15回鳴る）。
		//     ★★★でも**お金が入る瞬間がランの途中に移った**のに、そこが無音だった。
		//   → ★**越えた瞬間に軽く「チャリン」**。
		//
		//   ★★★これは**AIが足したもの**（島さんは「買った瞬間」を頼んだ）。
		//     ★うるさければ**この1行を消すだけ**で無音に戻る。
		//   ★★わざと軽く・低めにしてある（1320／0.04秒）＝
		//     ★★**買った瞬間の着地音（1760・0.28秒）とぶつからないように**
		//
		//   ★★★2026-08-23、**拾ったコインだけ別の音**にした（島さんの指定）:
		//     > 島さん「コインに触れたときの効果音をチャリーンに変えたいです。」
		sound(1320, 0.04);
	}

	// ============================================================
	// ★★★★コインを拾ったときの「チャリーン」（2026-08-23 島さんの指定）
	// ============================================================
	//
	//   > 島さん「コインに触れたときの効果音をチャリーンに変えたいです。
	//   >   いくつか聴き比べて選びたい。より気持ちの良い音にしたい。」
	//
	//   ★★★2026-08-23、島さんが **C②（きらめき三段）** を選びました:
	//     > 島さん「この選べるシステムとてもよいです。C②きらめき三段に設定してください。」
	//
	//   ★★AIへ: **勝手に差し替えないこと**（→ CLAUDE.md 2026-08-20 の教訓
	//     「音は理屈で決めない。島さんの耳が正」）。
	//     ★候補は `tools/preview-sound.html` の C⓪〜C⑤（★いまの音は **C②**）。
	//
	//   ★C②の作り: **細かく3段のぼって、最後だけ長く伸ばす**
	//     ★のぼりが「チャリチャリ」／★★最後の伸びが「〜ン」の余韻
	function coinSound() {
		melody([
			[1319, 0.04,  0],    // ★ミ
			[1760, 0.04, 45],    // ★ラ
			[2637, 0.45, 90]     // ★★ミ（上）… ★長く伸ばす（★これが余韻）
		]);
	}

	// ============================================================
	// ★★★★★青スライムの「いまのコマ」の高さ（2026-09-06 島さんの指定）
	// ============================================================
	//   ★★★**`enemyFrame()` を通すのが要**です（★`drawCones()` と同じコマ）。
	//     ★別々に数えると、★★**当たり判定と絵がずれます**
	//       （★2026-08-22 と 08-31 に2度踏んだ罠）。
	//   ★返すのは「地面から何ドット上か」。★★描くところの式から逆算しています:
	//       描く行 = 地面の行 - 1 - FEET_ROW + f.y
	//       → ★絵のてっぺんの浮き = FEET_ROW - f.y
	//       → ★★足元の浮き       = FEET_ROW - (f.y + 絵の高さ - 1)
	function aosuraFrameOf(o) {
		var A = obArt(o);
		if (!A || !A.FRAMES) return null;
		return { A: A, f: A.FRAMES[enemyFrame(o, A)] };
	}
	function aosuraTopLift(o) {                    // ★絵のてっぺん
		var t = aosuraFrameOf(o);
		return t ? t.A.FEET_ROW - t.f.y : 0;
	}
	function aosuraFootLift(o) {                   // ★★足元（★0 = 地面にいる）
		var t = aosuraFrameOf(o);
		return t ? t.A.FEET_ROW - (t.f.y + t.f.rows.length - 1) : 0;
	}

	// ★いまぶつかっているコーンの番号（無ければ -1）
	function hitConeIndex() {
		if (st.phase !== "play" && st.phase !== "go") return -1;
		// ============================================================
		// ★★★★飛ぶ敵が入ったので、ここは**行ごとの判定**になった（2026-08-23）
		// ============================================================
		//   ★前は `if (currentLift() > 0) return -1;` で**すぐに戻って**いた
		//     （★跳んでいれば何にも当たらない ＝ ★★**跳ぶコストが無い**）。
		//   ★★飛ぶ敵は**その逆**なので、行ごとに見る形にした:
		//
		//     ★鳥      … 足元が `BIRD_LIFT` 以上のときだけ当たる
		//     ★それ以外 … 足元が 0 のときだけ当たる（★いままでどおり）
		//
		//   ★★★**地上では鳥に絶対に当たりません** ＝ 「跳ばない」はいつでも安全。
		var lift = currentLift();
		var foot = riderFootX();
		for (var i = 0; i < st.cones.length; i++) {
			var o = st.cones[i];
			// ★★★扉と鍵はここでは扱わない（2026-08-16 / Phase C）。
			//   ★理由は2つ:
			//     ① 扉は**跳んでも当たる**（ルールの壁）。上の `currentLift()` の
			//        早い戻りに引っかかると、跳んだだけで通れてしまう
			//     ② 速さが上がると1コマで扉の幅より進むので、**すり抜ける**
			//   → どちらも「足の列に届いた最初のコマで決める」やり方で解いてある
			//     （`update()` の中。`resolved` の印を見ること）
			// ★★★ゴールの扉も、ここでは扱わない（2026-08-22）。
			//   ★着いた瞬間の判定は「足の列に届いた最初のコマ」で1回だけ行う（下の `resolved`）
			if (o.kind === "gate" || o.kind === "key" || o.kind === "camp" ||
				o.kind === "goal") continue;
			// ★★★★鳥だけ、当たる高さが逆（2026-08-23）
			if (o.kind === "bird") { if (lift < BIRD_LIFT + PLAY_ASSIST.hitInset) continue; }
			// ★★★★★レールは**ぶつかりません**（2026-08-31。★島さんがテストプレイして決めた）
			//
			//   > **島さん「乗らない選択も出来るようにしたい。つまり障害物でない。素通り可。」**
			//
			//   ★★これで「**乗る／乗らない**」を選べるようになりました:
			//     ★跳ばない       … ★★**素通り**（★何も起きない）
			//     ★★高さを合わせる … ★★★**乗る**（★コインが増え続ける）
			//
			//   ★★★**失敗が無くなった**ので、核（技術を要しない）にさらに合います。
			//     ★★乗れたら得、乗れなくても損はしない ＝ **ボーナスだけ**
			else if (o.kind === "rail") continue;
			// ============================================================
			// ★★★★★青スライムの「飛び上がり」だけ、空中でも当たる（2026-09-06 島さんの指定）
			// ============================================================
			//   > **島さん「ブルースライムの飛び上がりに触れた時ダメージを受けるように」**
			//
			//   ★★**地面にいるコマは、いままでどおり**（★跳べば素通り）。
			//   ★★★跳び上がっているコマだけ、**主役の足元が絵のてっぺんより下なら当たる**。
			//     ★高さは `aosuraTopLift()`（★★**描いているコマとまったく同じ**）から取る
			else if (o.kind === "aosura" && lift > 0) {
				if (!AOSURA_AIR_ON) continue;            // ★昔どおり（★素通り）
				if (aosuraFootLift(o) <= 0) continue;    // ★地面にいるコマ ＝ 跳べば素通り
				// ★★頭を越えている ＝ 当たらない（★`AOSURA_AIR_MARGIN` のぶん見逃す）
				if (lift + AOSURA_AIR_MARGIN + PLAY_ASSIST.hitInset > aosuraTopLift(o)) continue;
			}
			else if (lift > 0) continue;                 // ★跳んでいる＝地上の物には当たらない
			var cx = Math.round(o.x);                    // ★描くときと同じ丸め方
			// Existing collision uses a single foot column, already smaller than the sprite.
			// Keep that generous model and reject 2px grazes at either obstacle edge.
			var inset = Math.min(PLAY_ASSIST.hitInset, Math.floor((obWidth(o) - 1) / 2));
			if (foot >= cx + inset && foot < cx + obWidth(o) - inset) return i;
		}
		return -1;
	}

	// ============================================================
	// ■■■ ★★ぶつかっても死なない（2026-08-15 / 成長型コア）■■■
	// ============================================================
	//
	//   島さん「**技術を要しない。** 大量のアップグレード、数値のインフレ、
	//           数ある強化要素からどれを選ぶかによって自分好みの強力な組み合わせを作る楽しさ」
	//
	//   ★★**失敗はゲームオーバーではなく「コスト」**。
	//     ただし「何をやっても走れる」だと**コーンを避ける意味が消える**ので、
	//     ★**「避けないと損する」**程度の重さにしてある:
	//
	//       成功（越えた） … 倍率が上がる
	//       失敗（当たった）… ★減速 ＋ ★倍率が 0 に戻る ＋ ★スタミナが余分に減る
	//
	//   ★これで**技術は要らないが、ゲーム内の行動には意味が残る**
	function onHit(i) {
		clearActionAssist();
		if (upgLevel("live")) { var l = liveState(); l.viewers = Math.floor(l.viewers * 0.25); l.combo = 0; l.notice = "WIPEOUT"; l.noticeMs = 1400; }
		st.cones.splice(i, 1);          // ★当たったコーンは消す（毎コマ当たり続けないように）
		st.hits++;
		st.recoverProgress = 0;
		st.recoverFlash = 0;
		// ★★★2026-08-16、島さんの指定で**ぶつかるとスタミナが減る**ようになった。
		//   ★スタミナ ＝ 「**あと何回ミスできるか**」（★時間では減らない）
		//   ★CAMP_ON のときだけ HP がその役目を持つ（★いまは保留中）
		if (CAMP_ON) {
			st.hp -= 1;
			if (st.hp <= 0) { st.hp = 0; onDeath(); return; }
		} else {
			st.stamina -= HIT_STAMINA;
		}
		// ★★★倍率は消えたので、ぶつかっても**失うものは「回数」と「越えられなかったコイン」**。
		//   ★越えられなかった ＝ `gainCoin` が呼ばれない ＝ **稼ぎ損ねる**のが損
		st.slowMs = HIT_SLOW_MS;        // ★しばらく減速する
		st.shakeMs = SHAKE_MS;          // ★★揺れる（★描画だけ。遊びには触らない）
		st.hitFlash = HIT_FLASH_FRAMES; // ★★★★光る（★これも描画だけ）
		sound(220, 0.12);
	}

	// ============================================================
	// ■■■ ★★★扉と鍵の3つの出来事（2026-08-16 / Phase C）■■■
	// ============================================================

	// ★★鍵を拾った。★★**ぶつかりではない**（倍率も減らない・スタミナも減らない）
	//   ★★**強い音**にする（島さん「普通のコインとは明らかに違うと身体的に分かること」）
	function takeKey(c) {
		var isNew = giveItem("key");
		c.taken = 1;
		if (!isNew) return;                 // ★すでに持っていたら、静かに素通り
		st.gotKeyNow = true;
		// ★★上がっていく音（★コインのチャリンとも、ぶつかりの低い音とも違う）
		sound(880, 0.10);
		setTimeout(function () { sound(1320, 0.10); }, 70);
		setTimeout(function () { sound(1760, 0.22); }, 150);
		addPop("KEY", "gain");
		st.gainFlashMs = GAIN_FLASH_MS;
	}

	// ★★★鍵を持って扉に届いた ＝ **使った瞬間**。ここで初めて開いた姿になる
	//   ★★「持っているだけ」では開かない（島さんの指定）。
	//     ★理由: 鍵取得 →「何に使うんだ？」→ 再訪 → 接触 → **開く** の
	//       いちばん最後が体験の山だから
	function passGate(c) {
		var firstTime = !hasItem("gateOpened");
		c.opened = true;
		st.gatePassed = true;
		// ★★**一度開けた扉は、次のランからも開いたまま**（★進歩の痕跡を残す）
		giveItem("gateOpened");
		if (!firstTime) return;                 // ★2回目からは静かに通る
		sound(330, 0.14);
		setTimeout(function () { sound(660, 0.22); }, 110);
	}

	// ★★鍵が無い ＝ **行き止まり**。★★跳んでも越えられない（＝ ルールの壁）
	//   ★★**転んだのではない。** スタミナを使い切って、そのランが終わる
	//   ★★★稼いだコインは**残る**（既存どおり。「全部失う」にはしない）
	//
	//   ⚠ ★★保留事項（島さんの指摘 2026-08-16）:
	//     「初見で"何かわからないものに触ったら全部終了"は強すぎるかもしれない。
	//       初回だけ強制停止＋少し後退＋扉演出のほうが検証しやすい」
	//     → ★**今回は現仕様のまま実装し、実機評価で判断する**（★勝手に変えない）
	function blockedByGate(c) {
		st.stamina = 0;                 // ★★ここまで
		st.slowMs = HIT_SLOW_MS;
		st.shakeMs = SHAKE_MS;          // ★★揺れる（★描画だけ）
		// ★★「止められた」を見せる時間（→ `update()` の説明）。★遊びには触らない
		st.gateStopMs = GATE_STOP_MS;
		st.gateFlashMs = GATE_STOP_MS;  // ★扉が光る（★描画だけ）
		// ★★★音は「ぶつかった（220Hz）」とはっきり変える。
		//   ★低いところから**下がっていく**＝「開かない・行き止まり」
		sound(200, 0.16);
		setTimeout(function () { sound(150, 0.16); }, 130);
		setTimeout(function () { sound(110, 0.34); }, 260);
	}

	// ============================================================
	// ■■■ ★★★★5000m のエンディング（2026-08-22 島さんの指定）■■■
	// ============================================================
	//
	//   ★★**世界を止めて演出を流すだけ。遊びの数字には1つも触りません。**
	//     ・距離も稼ぎも増えない（★`update()` の早い戻りで止まる）
	//     ・★★スタミナも減らない ＝ ★エンディング中に GAMEOVER にならない

	// ★★ゴールの扉に着いた。★★**必ず開く**（鍵は要らない）
	function reachGoal(c) {
		c.opened = true;              // ★★扉が開いた姿に変わる（→ `obArt()`）
		// ★★★着いた瞬間の距離を、ちょうど 5000m（`GOAL_M`）にそろえる。
		//   ★なぜ要るか: 障害物は「画面の上を1コマぶんずつ左へ動く」ので、
		//     足の列に届く瞬間は**必ず少し行き過ぎる**（★速いほど大きい）。
		//     ★★そのままだと画面の数字が **9999m** のままエンディングに入る。
		//   ★足すのは**1メートル未満**（★1コマぶんの端数だけ）。★減らすことはしない
		if (st.dist < GOAL_M * SCORE_DOTS) st.dist = GOAL_M * SCORE_DOTS;
		st.phase = "ending";
		st.endMs = 0;
		st.endPage = 0;               // ★★★かならず1ページ目から（2026-08-22）
		st.pageMs = 0;
		st.shopOpen = false;          // ★開けっぱなしのお店があれば閉じる
		st.paused = false;
		goalSound();
	}

	// ============================================================
	// ★★★★扉の前後は「何も置かない」（2026-08-23 島さんの指定）
	// ============================================================
	//
	//   > 島さん「扉前後20ｍは障害物などおかないようにしてください。」
	//
	//   ★★見るのは「**そこに立つ場所**（世界のどこか）」であって、
	//     ★「いま何メートル走ったか」ではない。
	//     ★★★世界の位置は動かないので、**一度あけたら、あいたまま**になる
	function inGoalClear(wx) {
		if (!GOAL_ON) return false;
		return Math.abs(metersOf(wx) - GOAL_M) <= GOAL_CLEAR_M;
	}

	// ★エンディングの時間だけを進める（★世界は止まったまま）
	function updateEnding(dt) {
		st.endMs += dt * 1000;
		if (!endShown()) return;              // ★白い光のあいだは、まだページが始まっていない
		st.pageMs += dt * 1000;
		// ★★★最後のページは自動で進まない（★`CONTINUE` を待つ）
		if (st.endPage >= GOAL_PAGES.length - 1) {
			if (st.pageMs > GOAL_PAGE_MS) st.pageMs = GOAL_PAGE_MS;
			return;
		}
		// ★★4秒たったら、次のページへ（島さんの指定）
		if (st.pageMs >= GOAL_PAGE_MS) { st.endPage++; st.pageMs = 0; }
	}

	// ============================================================
	// ★★★★ページの「隠れ具合」（0 = よく見える / 1 = まっ白で見えない）
	// ============================================================
	//
	//   ★出はじめ … 1 → 0（★フェードイン）
	//   ★終わりぎわ … 0 → 1（★フェードアウト）
	//   ★★最後のページは**消えない**（★`CONTINUE` を出したままにする）
	function pageHide() {
		if (!endShown()) return 0;
		if (st.pageMs < GOAL_FADE_MS) return 1 - st.pageMs / GOAL_FADE_MS;
		if (st.endPage >= GOAL_PAGES.length - 1) return 0;
		var t = st.pageMs - (GOAL_PAGE_MS - GOAL_FADE_MS);
		if (t <= 0) return 0;
		return Math.max(0, Math.min(1, t / GOAL_FADE_MS));
	}

	// ★白い光が、どこまで広がったか（0〜1）
	function endLightT() {
		return Math.max(0, Math.min(1, (st.endMs - GOAL_OPEN_MS) / GOAL_LIGHT_MS));
	}

	// ★★文字（クレジット）が出ているか。★★ここまで来たら、次のタップは CONTINUE
	function endShown() { return st.endMs >= GOAL_OPEN_MS + GOAL_LIGHT_MS; }

	// ★★★ショートカット（島さんの指定「エンディング(ショートカット可)」）。
	//   ★演出の途中で押したら、**一気に文字のところまで飛ぶ**
	function endSkip() {
		st.endMs = GOAL_OPEN_MS + GOAL_LIGHT_MS;
		st.pageMs = 0;                        // ★ここから1ページ目が始まる
	}

	// ★★★CONTINUE ＝ **その先へ**（島さんの指定「その後は②へ」）。
	//   ★★★育てたもの（コイン・レベル・技・道具・スタミナ）を**1つも失わない**。
	//     ★ここで消すと、13分かけて組んだビルドが**達成した直後に**消えることになる。
	//     ★消えるのは、これまでどおり **GAMEOVER のときだけ**（→ `resetStatus()`）
	//   ★`goalDone` を立てるので扉はもう出てこない（★開いた扉はそのまま後ろへ流れる）
	function continueRun() {
		st.goalDone = true;
		st.endMs = 0;
		st.endPage = 0;
		// ★★★★まだ二段ジャンプを持っていなければ、**授かる場面**へ（2026-08-22 島さんの指定）
		//   > 島さん「エンディングでコンテニュー後画面タップで暗転し…」
		//   ★★ここで走り出さずに、暗転 → JUMP → ×2 を見せてから走り出す
		// SHOES teaches double jump; the ending no longer enters the JUMP x2 scene.
		// ★★★もう一度 READY / GO を出してから走り出す（2026-08-23 島さんの指定）
		readyAgain();
	}

	// ============================================================
	// ■■■ ★★★★二段ジャンプを授かる場面（2026-08-22 島さんの指定）■■■
	// ============================================================
	//
	//   ★★**世界は止まったまま。** 距離もコインも増えず、スタミナも減りません
	//     （★エンディングとまったく同じ扱い）。

	function updateGift(dt) {
		st.giftMs += dt * 1000;
		// ★★★「×2」が出た瞬間に、**喜びの音を1回だけ**鳴らす（★島さんの指定）
		//   ★あわせて、ここで**二段ジャンプが手に入る**（★見えた瞬間＝使える瞬間）
		if (!st.giftRang && giftX2()) {
			st.giftRang = true; st.moment = "DOUBLE JUMP LEARNED";
			st.dj = true;
			if (PR) PR.learn("doubleJump");
			giftSound();
		}
	}

	// ★暗転の進み具合（0〜1）
	function giftFadeT() { return Math.max(0, Math.min(1, st.giftMs / GIFT_FADE_MS)); }
	// ★★「JUMP」が出ているか（★暗転しきってから1秒後）
	function giftWord() { return st.giftMs >= GIFT_FADE_MS + GIFT_WORD_MS; }
	// ★★「×2」が出ているか（★JUMP からさらに1秒後）
	function giftX2() { return st.giftMs >= GIFT_FADE_MS + GIFT_WORD_MS + GIFT_X2_MS; }

	// ★★★授かる場面を終えて、走り出す（★ここから二段ジャンプ）
	function giftDone() {
		if (PR) PR.learn("doubleJump");
		st.dj = true;              // ★★念のため（★音より先に押されても必ず渡す）
		st.giftMs = 0;
		// ★★★もう一度 READY / GO を出してから走り出す（2026-08-23 島さんの指定）
		readyAgain();
	}

	// ★★★★喜びの効果音（★★★2026-08-22、島さんが**合格**と決めた音）
	//   > 島さん「喜びの効果音は合格です。」
	//   ★★AIへ: **勝手に差し替えないこと**（→ CLAUDE.md 2026-08-20 の教訓）。
	//     ★候補は `tools/preview-sound.html` の J①〜J③（★いまの音は J①）
	//   ★買った音（速い）とも、回復の音（ゆっくり満ちる）とも、ゴールの音とも別のもの:
	//   ★★**跳ねる音を2回**（★二段ジャンプなので「タン・タン」）→ ★明るい和音で満ちる
	function giftSound() {
		melody([
			[784,  0.07,   0],   // ★1回目の跳躍
			[1047, 0.07,  70],
			[1319, 0.09, 140],
			[1047, 0.07, 260],   // ★★2回目の跳躍（★間をあけて「もう一度」を出す）
			[1319, 0.07, 330],
			[1568, 0.10, 400],
			// ★★満ちる和音（★手に入った）
			[2093, 0.50, 520], [1568, 0.50, 520], [1047, 0.50, 520]
		]);
	}

	// ★★★次のページへ（2026-08-22）。★最後のページなら、もう進めない
	//   ★★★2026-08-23、島さんの指定で**タップ音を鳴らさない**ようにした:
	//     > 島さん「画面タップでの省略は可能だがタップ音は必要ないです。」
	//   ★★飛ばしたページは、そのまま消える（★次のページは**フェードインから**始まる）
	function endNext() {
		if (st.endPage >= GOAL_PAGES.length - 1) return false;
		st.endPage++;
		st.pageMs = 0;
		return true;
	}

	// ★★★★BET の音（★★仮です。★島さんの耳が正 → `tools/preview-sound.html`）
	//   ★★**払って、得る**の順に聞こえるようにしてある:
	//     ・下がる2音（★体力を差し出した）→ 上がる2音（★倍率が乗った）
	//   ★買った音（騆け上がるだけ）とは**別物**にしてある（★意味が違うため）
	function betSound() {
		melody([
			[392, 0.07,   0],   // ソ  ★払う（下がる）
			[294, 0.07,  80],   // レ
			[587, 0.09, 190],   // レ（上）★得る（上がる）
			[880, 0.20, 300]    // ラ（上）
		]);
	}

	// ============================================================
	// ★★★★★転生の音（2026-09-12。★★**仮です**）
	// ============================================================
	//   ★形は「★★**一度深く沈んで、そこから高く登り直す**」。
	//     ★★★差し出して、その先を受け取る ―― その順番を音でなぞっています。
	//   ★★★★**AI へ: 勝手に差し替えないこと**。
	//     ★まず `tools/preview-sound.html` で鳴らして選んでもらう
	//     （★★AI は過去に 2 度、理屈で音を「良く」して外しています）。
	//   ★★**並べるのは `melody()` の 1 か所だけ**（★`setTimeout` を散らさない）。
	function prestigeSound() {
		melody([
			[523, 0.10,   0],   // ド    ★差し出す（沈んでいく）
			[392, 0.10, 110],   // ソ
			[262, 0.16, 220],   // ド（下）★★いちばん深いところ
			[392, 0.08, 420],   // ソ    ★★★ここから登り直す
			[523, 0.08, 500],   // ド
			[659, 0.08, 580],   // ミ
			[784, 0.10, 660],   // ソ（上）
			[1047, 0.26, 760]   // ド（上）★前より高いところへ
		]);
	}

	// ★★★問いかけの音（★「REBORN?」を出した瞬間。★★まだ何も起きていない）
	//   ★形は「**問いかけ**」―― ★★最後が上がる（★★★決まっていないことを音でも伝える）
	function prestigeAskSound() {
		melody([
			[523, 0.06,   0],
			[698, 0.12,  80]
		]);
	}

	// ★★知らせの音（★お店に行が**はじめて出た**とき。★★転生そのものとは別）
	function prestigeReadySound() {
		melody([
			[784,  0.06,   0],
			[1047, 0.06,  90],
			[1319, 0.14, 180]
		]);
	}

	// ★★★ゴールの音（★★仮です。★島さんの耳が正 → `tools/preview-sound.html`）
	//   ★買った音（速い・駆け上がる）とも、回復の音（ゆっくり満ちる）とも別のもの:
	//   ★★**開く → 光が差す**（★駆け上がったあと、長い和音で広がる）
	function goalSound() {
		melody([
			[523,  0.10,   0],   // ド
			[659,  0.10, 110],   // ミ
			[784,  0.10, 220],   // ソ
			[1047, 0.14, 330],   // ド（上）
			// ★★光が広がるところ（★長い和音 ＝ 白くなっていく時間）
			[1319, 0.55, 470],   //   ミ
			[1047, 0.55, 470],   // ＋ド
			[784,  0.55, 470]    // ＋ソ
		]);
	}

	// ============================================================
	// ■■■ ★★★死亡とキャンプ（2026-08-16 / Phase D）■■■
	// ============================================================

	// ★★★HP が 0 になった ＝ **死亡**。★★未確定分を全部失う
	//   ★★「スタミナ切れ（撤退）」とはっきり別物にする:
	//     撤退 … 疲れて旅を続けられなくなった → ★稼ぎは**全部残る**
	//     死亡 … 危険に耐えられなくなった     → ★★稼ぎを**全部失う**
	//   ★恒久アップグレード・覚えた技・拾った鍵は**失わない**（買った瞬間に保存済み）
	function onDeath() {
		st.died = true;
		// ★★★死亡 ＝ **そのランで稼いだぶんを失う**（★保留中の仕組み。CAMP_ON = 1 のとき）
		//   ★2026-08-16、稼ぎは越えた瞬間に貯金へ入るようになったので、
		//     ★★**ここで貯金から引き戻す**（★引き忘れると「死んでも得」になる）
		addCoins(-Math.floor(st.coin));
		st.coin = 0;
		st.shakeMs = SHAKE_MS;
		sound(180, 0.20);
		setTimeout(function () { sound(120, 0.30); }, 150);
		runOver();
	}

	// ★★キャンプに着いた ＝ **世界が止まって選ぶ**
	function reachCamp(c) {
		st.phase = "camp";
		st.campObj = c;
		st.campSel = 0;                 // ★★はじめは「キャンプする」（＝安全側）
		st.campStopMs = CAMP_STOP_MS;   // ★誤タップよけ
		st.campsSeen++;
		sound(660, 0.10);
		setTimeout(function () { sound(880, 0.14); }, 90);
	}

	// ★キャンプの選択を決めた
	function campDecide() {
		if (st.campSel === 0) {
			// ★★キャンプする ＝ **そこで旅を終えて店へ戻る**（島さんの判断 2026-08-16）
			//   ★スタミナを回復して走り続けられる形にすると、**無限に走れて店に戻らない**
			sound(440, 0.12);
			runOver();
		} else {
			// ★このまま進む ＝ 倍率も HP もそのまま。★さらに奥へ
			sound(990, 0.08);
			st.phase = "play";
			st.campObj = null;
		}
	}

	function campMove(d) {
		st.campSel = (st.campSel + d + 2) % 2;
		sound(880, 0.03);
	}

	// ★★ラン終了（スタミナが 0 になった）。★転んだのではない
	//   ★★`opts.reset` = ★**GAMEOVER（育てたものを全部なくす）**（2026-08-16 島さんの指定）
	//     ★キャンプで自分から終える道（保留中）は、これを立てない
	function runOver(opts) {
		st.phase = "over";
		st.phaseMs = 0;
		st.reached = meters();
		st.newBest = updateBest(st.reached);
		if (PR) PR.finish(st.reached);
		// ★★★★★死んだらセーブも消える（2026-09-13）。
		//   ★★**ここだけが「やり直し防止」の核**です（★CONTINUE では消しません）
		if (!testMode) deleteSave();
		// ★★積分した稼ぎを整数にする。★COIN のアップグレードはここで効く
		//   ★★★死んだときは `st.coin` が 0 にされているので、自然に 0 になる
		//     （★「死亡＝未確定分を失う」を、ここに if を足さずに表す）
		// ★★★2026-08-16、ここで COIN 倍率を掛けるのをやめた。
		//   ★COIN は「**1個あたりの枚数**」に変わったので、
		//     `gainCoin()` の時点でもう掛かっている（★二重に掛けない）
		st.earned = Math.floor(st.coin);
		// ★★★2026-08-16、**ここでは貯金に足さない**（島さんの「買えない」報告の直し）。
		//   ★貯金には `gainCoin()` が**越えた瞬間に入れている**ので、
		//     ここで足すと**二重になる**。★`st.earned` は記録用に残してあるだけ
		// ★★★2026-08-16、島さんの指定で**清算（数え上げ）をやめた**。
		//   ★`countMs` は最初から終わった状態にする（★仕組みは残してある）
		st.countMs = COUNT_MS;
		st.overFadeMs = 0;                       // ★★ここから暗転が始まる
		// ★★★カーソルを `START` に戻す（2026-08-16。★実機で見つけた）。
		//   ★走っている途中にショップを開いて `SPEED` を選んだまま死ぬと、
		//     ★★GAMEOVER でもカーソルが `SPEED` に残り、**タップ1回でもう一回**が崩れる
		st.shopSel = 0;
		st.tapArmed = false;
		st.shopOpen = false;                     // ★ショップを開いたまま死んでも閉じる
		// ★★★育てたものを全部なくす（島さん「死んだら(GAMEOVER)ステータスもリセット」）。
		//   ★★**BEST を数えたあとに消す**（★順番が逆だと記録も消える）
		if (opts && opts.reset) { st.wiped = true; resetStatus(); }
		// ★★低い音を2つ重ねて「落ちた」感じにする（★買った音の逆向き）
		sound(330, 0.20);
		setTimeout(function () { sound(165, 0.45); }, 180);
	}

	// ============================================================
	// ■■■ ★★コインのカウントアップ（★表示だけ・貯金に触らない）■■■
	// ============================================================
	//
	//   島さん「`COIN 0 ×4.2` からチャリンチャリンの音と同時に数字が0から上昇する
	//           （タップで省略可）」
	// ★★★GAMEOVER の暗転を進める（2026-08-16）。★世界は止まったまま
	function updateOver(dt) {
		if (st.overFadeMs < OVER_FADE_MS) {
			st.overFadeMs = Math.min(OVER_FADE_MS, st.overFadeMs + dt * 1000);
		}
		updateCount(dt);          // ★★清算は出していないが、仕組みは残してある
	}

	// ★暗転がどこまで進んだか（0 = まだ明るい / 1 = まっ暗）
	function fadeT() { return Math.min(1, st.overFadeMs / OVER_FADE_MS); }
	// ★★暗転が終わったか（★お店の一覧とタップを、ここより後ろにする）
	function fadeDone() { return st.overFadeMs >= OVER_FADE_MS; }

	function updateCount(dt) {
		if (st.countMs >= COUNT_MS) return;
		var before = st.countMs;
		st.countMs = Math.min(COUNT_MS, st.countMs + dt * 1000);
		// ★チャリンチャリン。★数え終わったら鳴らさない／稼ぎが0なら鳴らさない
		if (st.earned > 0 &&
			Math.floor(st.countMs / COUNT_BEEP_MS) !== Math.floor(before / COUNT_BEEP_MS)) {
			sound(COUNT_BEEP_HZ, 0.03);
		}
	}

	function countDone() { return st.countMs >= COUNT_MS; }

	// ============================================================
	// ■■■ ★★お店の一覧（★ラン終了の画面と一体）2026-08-15 / Phase B ■■■
	// ============================================================
	//
	//   ★★**カーソルの最初の場所は `START`**。
	//     → **タップ1回で即もう一回**（前に作った「即リトライ」を1ドットも損なわない）
	//   ★操作はいまの3つだけ: 上へなぞる＝↑ / 下へなぞる＝↓ / タップ＝決定
	//
	//   ★一覧は毎回その場で作る（★項目数を決め打ちにしない ＝ 表に1行足せば増える）
	//   ★★★2026-08-16、ショップボタンから開いたときは先頭が `CLOSE`（＝閉じる）。
	//     ★ラン終了の画面から見たときは `START`（＝タップ1回で即もう一回）のまま
	// ★★★★BET（2026-08-23 島さんの指定）
	//   ★★体力を `pay` だけ払う。★ただし `minLeft` は必ず残す（★即死させない）
	function betCfg() { return (UP && UP.BET) || null; }
	function canBet() {
		var b = betCfg();
		if (!BET_ON || !b || !st) return false;
		// ★★★★**エンディング後の遊び**（2026-08-23 島さんの指定）。
		//   > 島さん「BETはエンディング後の遊びにしたいです。」
		//   ★★`st.dj` ＝ 二段ジャンプを授かったか ＝ **このランでゴールを見たか**。
		//     ★二段ジャンプと**まったく同じ扱い**にしてある
		//     （★そのランのあいだだけ・死ねば消える）
		if (!st.goalDone) return false;
		return st.stamina - b.pay >= b.minLeft;
	}
	// ★★「次に押したらこうなる」倍率（★他の行が「次の値段」を出すのと同じ形）
	function nextBetMul() {
		var b = betCfg();
		return b ? (st ? st.betMul : 1) * b.mul : 1;
	}
	// ★倍率の見せ方。★10倍を超えたら K/M と同じ短い書き方にする
	function betText(m) {
		return (m < 10) ? String(Math.round(m * 10) / 10) : shortNum(Math.round(m));
	}

	// Keep row identities stable; availability is shared by both shop renderers and purchases.
	function shopConditionMet(id) {
		if (upgLevel(id) > 0 || bagCount(id) > 0 || buyCount(id) > 0) return true;
		if (id === "coin") return true;
		if (id === "prestige") return canPrestige();
		if (id === "speed") return upgLevel("coin") >= 2;
		if (id === "stamina") return upgLevel("coin") >= 5 && upgLevel("speed") >= 3;
		if (id === "rail") return upgLevel("railpass") >= 1;
		if (id === "railpass") return journeyRank >= 1;
		if (id === "drink") return buyCount("maxdrink") >= 1;
		if (id === "wheels") return upgLevel("coin") >= 3;
		if (id === "shoes") return !!(st && st.dj) || (upgLevel("coin") >= 4 && upgLevel("speed") >= 2);
		if (id === "magnet") return upgLevel("coin") >= 6 && !!(st && st.dj);
		if (id === "light") return upgLevel("stamina") >= 2;
		if (id === "recover") return upgLevel("stamina") >= 3 && upgLevel("coin") >= 8;
		if (id === "live") return upgLevel("coin") >= 8 && upgLevel("rail") >= 1;
		if (id === "maxdrink") return upgLevel("stamina") >= 1;
		return !!unlocked[id];
	}
	function shopUnlocked(id) { return !!openedPanels[id] || shopConditionMet(id); }
	function syncShopUnlocks(announce) {
		if (!UP || !st) return;
		var added=[];
		UP.UPGRADES.concat(UP.ITEMS || [],UP.UNLOCKS || [],[{id:"prestige"}]).forEach(function(u){
			if (!openedPanels[u.id] && shopConditionMet(u.id)) { openedPanels[u.id]=true; added.push(u.id); }
		});
		if (added.length && PR) PR.unlockPanels(added);
		st.newPanels=st.newPanels || {}; st.panelFx=st.panelFx || {};
		if (announce) added.forEach(function(id){if(id!=="coin" && id!=="prestige")st.newPanels[id]=true;});
		if (announce && added.some(function(id){return id!=="coin" && id!=="prestige";})) prestigeReadySound();
	}
	function panelRevealMs(id) {
		if (!st) return 0;
		st.panelFx=st.panelFx || {}; st.newPanels=st.newPanels || {};
		if(st.newPanels[id]) { delete st.newPanels[id]; st.panelFx[id]=900; }
		return st.panelFx[id] || 0;
	}
	function railEnabled() { return !!(RAIL_ON && upgLevel("railpass") > 0); }
	function drinkRecovery() { return 5 + upgLevel("drink"); }
	function shopNextUnlock() {
		var hints = [
			["speed", "COIN Lv2で BEARING 開放", "BEARING: COIN LV2"],
			["wheels", "COIN Lv3で WHEELS 開放", "WHEELS: COIN LV3"],
			["shoes", "COIN Lv4 ＋ BEARING Lv2で SHOES 開放", "SHOES: COIN4 + BEARING2"],
			["stamina", "COIN Lv5 ＋ BEARING Lv3で STAMINA 開放", "STAMINA: COIN5 + BEARING3"],
			["maxdrink", "STAMINA Lv1で MAXDRINK 開放", "MAXDRINK: STAMINA LV1"],
			["drink", "MAXDRINK購入で DRINK 開放", "DRINK: BUY MAXDRINK"],
			["magnet", "COIN Lv6 ＋ SHOES習得で MAGNET 開放", "MAGNET: COIN6 + SHOES"],
			["light", "STAMINA Lv2で LIGHT 開放", "LIGHT: STAMINA LV2"],
			["railpass", "初めての転生で GEARのRAIL 開放", "RAIL: FIRST REBIRTH"],
			["rail", "GEARのRAIL購入で TRUCK 開放", "TRUCK: BUY RAIL"],
			["live", "COIN Lv8 ＋ TRUCK Lv1で LIVE 開放", "LIVE: COIN8 + TRUCK1"],
			["recover", "COIN Lv8 ＋ STAMINA Lv3で ENERGY 開放", "ENERGY: COIN8 + STAMINA3"]
		];
		for (var i = 0; i < hints.length; i++) if (!shopUnlocked(hints[i][0])) return { id:hints[i][0], text:hints[i][1], pixel:hints[i][2] };
		return null;
	}
	function prestigePreview() {
		return maxedIds().map(function (id) {
			var u = UP.UPGRADES.filter(function (u) { return u.id === id; })[0], cap = capOf(u);
			return { id: id, name: u.name, before: cap, after: cap + PRESTIGE_STEP };
		});
	}
	function shopRows() {
		var opened = !!(st && st.shopOpen);
		var rows = [{ kind: "start", name: opened ? "CLOSE" : "START" }];
		if (!UP) return rows;
		UP.UPGRADES.forEach(function (u) {
			var lv = upgLevel(u.id);
			if (u.id === "shoes" && st && st.dj) lv = 1;
			var max = capOf(u);        // ★★転生で伸びた天井を含む（2026-09-12）
			rows.push({
				kind: "upg", id: u.id, name: u.name, group: u.group || "upg", lv: lv, max: max,
				// ★★`maxLevel: null` = 上限なし。★そのときは必ず次の値段が出る
				cost: (max !== null && lv >= max) ? 0 : UP.costOf(u, lv)
			});
		});
		UP.UNLOCKS.forEach(function (u) {
			rows.push({
				kind: "unlock", id: u.id, name: u.name,
				got: !!unlocked[u.id], cost: u.cost, hint: u.hint
			});
		});
		// ★★★使うと無くなるもの（2026-08-22）。★何本でも買える ＝ `got` を持たない
		(UP.ITEMS || []).forEach(function (u) {
			rows.push({
				kind: "item", id: u.id, name: u.name,
				have: bagCount(u.id), maxHave: (u.maxHave || 1), usedUp: buyCount(u.id) >= (u.maxBuys || Infinity),
				// ★★★値段は「**次に買う値段**」（★買うたびに10倍）
				cost: itemCost(u)
			});
		});
		// ★★★★BET は**いちばん下**（2026-08-23）。
		//   ★カーソルは先頭（START / CLOSE）から始まるので、★★**事故で体力を失わない**
		//   ★★★**エンディングを見るまでは、行そのものが出ません**
		//     （★島さんの指定「BETはエンディング後の遊びにしたいです。」）。
		//   ★★★★だから**はじめて遊ぶ人の一覧は1行も増えない**
		if (BET_ON && betCfg() && st && st.goalDone) {
			rows.push({ kind: "bet", name: betCfg().name, mul: nextBetMul(), pay: betCfg().pay });
		}
		// ============================================================
		// ★★★★★転生は**行の並びではいちばん下**、
		//   ★でも**見せるのは 1 ページ目**（2026-09-12 島さんの指定）
		// ============================================================
		//
		//   > **島さん「プレステージ項目はお店の1ページ目に出現。」**
		//
		//   ★★★★**行の番号は動かしません**（★いちばん下に足す）。
		//     ★途中に割り込むと、★★**その先の行の番号が全部 1 つずれます**
		//     （★★★選んでいる行 `st.shopSel` も、見張りの列番号もずれる。
		//     ★ 2026-09-12 に実際にテストが捕まえました）。
		//   ★★★**どこに見せるかは `shopOrder()` が決めます**（→ 下）。
		//   ★★**1 項目も MAX でなければ、行そのものが出ません**
		//     （★はじめて遊ぶ人の一覧は 1 行も増えない）。
		if (PRESTIGE_ON && shopUnlocked("prestige")) {
			var mx = maxedIds();
			// ★★`state` … 実機のお店（`js/shop.js`）がそのまま出す文字。
			//   ★★★**言葉を決めるのはここ 1 か所**（★お店の画面は 2 つあるので、
			//   ★別々に書くと必ず片方だけ古くなります）。
			rows.push({ kind: "prestige", name: PRESTIGE_WORD, ids: mx, step: PRESTIGE_STEP,
				cost: 0, state: mx.length ? "+" + PRESTIGE_STEP + " x" + mx.length : "NEED MAX" });
		}
		rows.forEach(function (r) { r.hidden = !!(r.id && !shopUnlocked(r.id)); });
		return rows;
	}

	// ★その行が買えるか（★買えないものは暗く出す）
	function canBuy(r) {
		if (r.hidden || (r.id && !shopUnlocked(r.id))) return false;
		if (r.kind === "start") return true;
		// ★★★使うと無くなるもの（2026-08-22 島さんの指定）:
		//   ・★**持てるのは 1 本まで**（★持っているあいだは買えない）
		//   ・★★値段は買うたびに10倍（★`cost` にはもう次の値段が入っている）
		if (r.kind === "unlock") return false;
		if (r.kind === "item") return !r.usedUp && r.have < r.maxHave && coins >= r.cost;
		// ★★★★BET はコインでは買わない（★払うのは体力）
		if (r.kind === "bet") return canBet();
		// ★★★★★転生はコインでは買いません（★差し出すのは育てたものそのもの）
		if (r.kind === "prestige") return canPrestige();
		// ★★上限なし（`max === null`）なら、レベルでは止めない
		if (r.kind === "upg" && r.max !== null && r.lv >= r.max) return false;
		return !r.got && coins >= r.cost;
	}

	// ============================================================
	// ★★★★★転生する（★YES を押されてから、ここへ来ます）
	// ============================================================
	//   ★★**伸びるのは、この瞬間 MAX だった項目だけ**（★島さんの指定）。
	//   ★★★差し出すのは **コイン・レベル・道具 ＋ いま走った距離**。
	//     ★**BEST は残します**（★★`updateBest()` を呼ばない）。
	//     ★★技と二段ジャンプも残ります（★`PR` が覚えている）。
	//   ★★★★**世界（種）はそのまま**です（★`reset()` を呼ばない
	//     ＝ ★★同じ景色を、強くなってもう一度旅する）。
	function prestigeDo() {
		var ids = maxedIds();
		if (!ids.length) return false;
		var keepDoubleJump = st.dj;
		PR.prestige(ids, PRESTIGE_STEP);
		setBoostDeadline(Date.now()+60000);   // ★★2026-09-15 島さん「五分間は長すぎた。1分に」
		reloadCaps();                      // ★★天井が伸びたので、控えを取り直す
		resetStatus();                     // ★コイン・レベル・道具が消える（★既存）
		st.dj = keepDoubleJump;             // SHOES stays through rebirth, but not a new run after death.
		st.newPanels={}; st.panelFx={}; syncShopUnlocks(true);
		st.cones = []; st.nextRail = nextRailGap();
		if (global.DotShop) global.DotShop.close();
		st.shopOpen = false;
		st.dist = 0; st.scroll = 0;        // ★★いま走った距離を差し出す
		st.cones = []; st.picks = [];      // ★★★周りを空ける（★走り出しに障害物を置かない）
		st.stamina = curStaminaMax();
		st.staminaMax = st.stamina;
		st.prestigeMs = 0;                 // ★パネルは消えるので、グリッチも止める
		st.prestigeSeen = false;           // ★★次に MAX へ届いたとき、また知らせる
		prestigeSound();
		readyAgain();                      // ★★既存の道具。0m から READY / GO
		if(global.DotBoostUI)global.DotBoostUI.render();
		return true;
	}

	// ★★★問いかけの答え（★`which` … 0 = YES / 1 = NO）。
	//   ★★キャンプの `campAnswer()` と**まったく同じ形**にしてあります
	function prestigeAnswer(which) {
		if (!st || !st.prestigeAsk) return false;
		st.prestigeAsk = false;
		st.prestigeBtn = "";
		if (which !== 0) { sound(494, 0.06); return false; }   // ★NO … 何も起きない
		return prestigeDo();
	}

	// ★★決定を押したとき。★買えたら true
	function shopPick() {
		if (st.prestigeAsk) return false;
		var rows = shopRows();
		var r = rows[Math.max(0, Math.min(rows.length - 1, st.shopSel))];
		if (!r || r.kind === "start") return false;
		if (!canBuy(r)) { sound(180, 0.06); return false; }   // ★買えない音
		// ============================================================
		// ★★★★BET —— 体力を払って、そこから先のコインを増やす（2026-08-23）
		//   ★コインは動かさないので、`saveCoins()` も `saveUpg()` も通さない
		//     （★★**そのランのあいだだけ**のもの ＝ 覚えさせない）
		// ============================================================
		if (r.kind === "bet") {
			var bcfg = betCfg();
			st.stamina -= bcfg.pay;            // ★(1)払った（★バーがその場で減る）
			st.betMul *= bcfg.mul;             // ★(2)得た（★左上に ×1.5 が出る）
			st.betCount++;
			st.betFlashMs = BET_FLASH_MS;      // ★バーが赤く点滅する
			betSound();
			return true;
		}
		// ============================================================
		// ★★★★★転生―― 育てたものを差し出して、天井を上げる（2026-09-12）
		// ============================================================
		//
		//   ★★**伸びるのは、この瞬間 MAX だった項目だけ**（★島さんの指定）。
		//   ★★★差し出すのは **コイン・レベル・道具 ＋ いま走った距離**。
		//     ★**BEST は残します**（★★`updateBest()` を呼ばない）。
		//     ★★技と二段ジャンプも残ります（★`PR` が覚えている）。
		//   ★★★★**世界（種）はそのまま**です（★`reset()` を呼ばない
		//     ＝ ★★同じ景色を、強くなってもう一度旅する）。
		if (r.kind === "prestige") {
			if (!maxedIds().length) { sound(180, 0.06); return false; }
			// ★★★★★**ここではまだ転生しません**（2026-09-12 島さんの指定）。
			//   ★問いかけを出して、YES を押されてはじめて進みます
			//     （★★実際に進むのは `prestigeAnswer()` → `prestigeDo()`）。
			st.prestigeAsk = true;
			st.prestigeBtn = "";
			prestigeAskSound();
			return true;
		}
		if (r.kind === "upg") {
			coins -= r.cost;
			upgLv[r.id] = (upgLv[r.id] || 0) + 1;
			if (r.id === "shoes") { st.dj = true; giftSound(); }
			if (r.id === "railpass") st.nextRail = Math.min(st.nextRail, 280);
			if (r.id === "live") liveState();
			// ★★★★★この買い物で**はじめて MAX に届いた**なら、その場で知らせる
			//   （2026-09-12 島さんの指定「特殊フェードインと音演出により知らせる」）
			//   ★★**払う処理と同じ 1 か所**でやります（★離すと片方だけ直す事故が起きる）
			if (PRESTIGE_ON && st && !st.prestigeSeen && canPrestige()) {
				st.prestigeSeen = true;
				st.prestigeMs = PRESTIGE_GLITCH_MS;   // ★★パネルがグリッチしながら現れる
				prestigeReadySound();
			}
			// ============================================================
			// ★★★★STAMINA は「買った瞬間に」増える（2026-08-23 に直した）
			//
			//   > 島さん「ドリンク使用後ダメージをうけなくなるバグがあります。」
			//
			//   ★★調べて分かった、もっと大きな問題:
			//     ★★★**STAMINA を買っても、そのランでは何も起きていなかった。**
			//       ・`st.stamina` は**走り出しに1回**決めるだけだった
			//       ・`st.staminaMax`（バーの満タン）も**古いまま**だった
			//     ★死ぬと全部消える作りなので、★**次のランにも持ち越せない**
			//       ＝ ★★★**STAMINA は買っても永久に無意味だった**。
			//
			//   ★★あわせて、島さんが見つけた「ダメージを受けない」もこれが原因:
			//     ★ドリンクは**新しい満タン**（例:10）まで回復するのに、
			//       ★★バーは**古い満タン**（5）で割っていたので、
			//       ★★★**5回ぶつかるまでバーが1ドットも動かなかった**。
			//
			//   → ★**買った瞬間に、増えたぶんをその場で足す**（★満タンも更新する）
			// ============================================================
			if (r.id === "stamina" && st) {
				var nowMax = curStaminaMax();
				// ★★★★★2026-09-14 島さんの指定「スタミナのレベルを上げた時の効果は
				//   上限が一つ増加するのみで回復はしないこと」。★いまの体力は1つも増やさない
				st.hpGrowMs = 650;
				st.staminaMax = nowMax;           // ★★バーの満タンもそろえる
			}
		} else if (r.kind === "item") {
			// ★★使うと無くなるもの。★★★**買った回数**も数える（★次の値段が10倍になる）
			coins -= r.cost;
			bag[r.id] = bagCount(r.id) + 1;
			buys[r.id] = buyCount(r.id) + 1;
		} else {
			coins -= r.cost;
			unlocked[r.id] = true;
			if (PR) PR.learn(r.id);
		}
		saveCoins();
		saveUpg();
		syncShopUnlocks(true);
		// New panels may change pagination; keep the purchased card in view.
		st.shopPage = Math.floor(Math.max(0, shopOrder().indexOf(st.shopSel)) / 4);
		buySound();                                            // ★★★買えた音（★脳汁）
		return true;
	}

	function shopMove(d) {
		var order = [0].concat(shopOrder()), at = Math.max(0, order.indexOf(st.shopSel));
		at = (at + d + order.length) % order.length;
		st.shopSel = order[at];
		st.shopPage = Math.floor(Math.max(0, at - 1) / 4);
		st.shopKeyboard = true;
		sound(880, 0.03);
	}

	// ★★いま選んでいる行を決める（★呼ぶのは「指を離したとき」＝ `inputUp`）
	function shopDecide() {
		var rows = shopRows();
		if (rows[st.shopSel] && rows[st.shopSel].kind === "start") {
			// ★★ショップボタンから開いていたら「閉じる」／ラン終了の画面なら「もう一回」
			if (st.shopOpen) { global.DotOllie.toggleShop(); return; }
			restart();
			return;
		}
		shopPick();
	}

	// ★いま画面に出す額（★0 → 稼いだ額。最初速く、最後ゆっくり）
	function countedCoin() {
		if (countDone()) return st.earned;
		var t = st.countMs / COUNT_MS;
		return Math.floor(st.earned * (1 - Math.pow(1 - t, 3)));
	}

	// ★★★2026-08-16、`runAvgMult()`（そのランで効いた平均倍率）は消した。
	//   ★倍率そのものが無くなったので、意味が残っていない
	//   ★★かわりの目安は「稼ぎ ÷ 越えた数」＝ `curCoinPer()` そのもの

	// ============================================================
	// ★★★GAMEOVER からタイトルへ戻す（2026-08-16 島さんの指定）
	// ============================================================
	//   > 島さん「GAMEOVER画面から何か押したらタイトル画面へ。」
	//
	//   ★★**種を引き直すのはシェル側**（SEED ID 画面で見せた番号をそのまま渡す作り）。
	//     ★ここでは「戻す」だけ。★★ゲーム側で引き直すと、見せた番号と世界がずれる
	//   ★★`exitToMenu` が無い（テストなど）ときは、**その場でやり直す**（★固まらせない）
	function toTitle() {
		sound(440, 0.10);
		if (exitToMenu) { exitToMenu(); return; }
		restart();
	}

	// ★★やり直し。★**同じ種のまま**（「次はこの技を使おう」を起こしたいので）
	//   ★★2026-08-15（Phase 3）: **待ち時間なしで走り出す**（`instant`）。
	//     島さん「クラッシュ → タップ → 即スタート」
	//   ★ただし**加速はやり直される**（`speedMs` が 0 に戻る）ので、
	//     いきなりトップスピードにはならない
	function restart() {
		reset(WD.getSeed(), true);
		sound(880, 0.06);
	}

	// ============================================================
	// ★★★★★キャンプモード —— 夜だけ出るボタン（2026-09-04 島さんの指定）
	// ============================================================
	//
	//   > 島さん「夜になったらキャンプボタン出現。キャンプモードを選択できる。」
	//
	//   ■ ★★「夜になったら」＝ **暮れはじめ**（★走り出しから60秒）
	//
	//     ★この作品では `NIGHT_A0` に「**夜のはじまり**」と書いてあります。
	//     ★★つまり `nightAlpha() > 0` になった瞬間が「夜になった」です。
	//     ★★★完全な夜（120秒）まで待つと、下手な人には出ないことがあります
	//       （★実測: ミス25%の人は 3/20 しか届かない）。
	//
	//   ■ ★★★新しい仕組みは1つも作っていません
	//
	//     ★ボタンの出し入れ … ★★`refreshPad()`（★音を切り替えるときから在る口）
	//     ★世界を止める     … ★★`update()` の early return（★お店とまったく同じ）
	//     ★★★だから **`st.dayMs` も一緒に止まります**（★時計は1つのまま）
	var campPadOn = false;   // ★いまボタンを出しているか（★シェルに何度も頼まないため）

	function isNightNow() { return !!(CAMPMODE_ON && st && nightAlpha() > 0); }

	// ============================================================
	// ★★★★★「完全な夜」か（2026-09-05 島さんの指定）
	// ============================================================
	//   ★★暮れている途中（薄暗い）や、明けている途中は**ちがいます**。
	//     ★★★いちばん濃いところ（`NIGHT_A1`）に届いているあいだだけ true。
	//   ★これが**青スライムの出る条件**です（★島さんの言葉そのまま）
	function isFullNight() { return !!(NIGHT_ON && st && nightAlpha() >= NIGHT_A1 - 0.0001); }

	function syncCampPad() {
		if (!CAMPMODE_ON) return;
		var want = isNightNow();
		if (want === campPadOn) return;          // ★変わっていないなら何もしない
		campPadOn = want;
		var p = global.DotOllie.pad, i = p.indexOf("camp");
		if (want && i < 0) p.push("camp");
		else if (!want && i >= 0) p.splice(i, 1);
		// ★★朝になったら、開けっぱなしのキャンプは閉じる（★開いたまま昼にならない）
		//   ★★★★★ただし "wake" は**朝を迎えた直後**なので、消してはいけません（2026-09-04(6)）。
		//     ★消すと **READY の 0.5秒待ちが1コマも効かず**、そのまま走り出します
		//     （★テストが捕まえました）
		if (!want && st && st.campPhase && st.campPhase !== "wake") st.campPhase = "";
		if (refreshPad) refreshPad();
	}

	function toggleCamp() {
		clearActionAssist();
		if (st && st.campPhase === "fish" && !st.shopOpen) { leaveFishing(); return; }
		if (st && st.campPhase === "trip") return;                        // ★つなぎの途中では戻らない
		if (st && st.campPhase === "mine" && !st.shopOpen) { leaveMining(); return; }
		if (!CAMPMODE_ON || !st) return;
		// ============================================================
		// ★★★★★眠りにつく演出の最中は、閉じられない（2026-09-04(9)）
		// ============================================================
		//   > 島さん（2026-09-04(4)）「暗転を飛ばせるようにしないこと」
		//
		//   ★YES を押したあとは、★★**もう取り返しがつかない道**に入っています。
		//     ★★★ここでキャンプボタンを押すと**暗転ごと取り消されて**、
		//       ★夜のまま走る画面に戻ってしまいました。
		if (st.campPhase === "fade" || st.campPhase === "dark" ||
			st.campPhase === "wake") return;
		// ============================================================
		// ★★★★★一度テントを張ったら、朝まで外に出ない（2026-09-05 島さんの指定）
		// ============================================================
		//   > 島さん「私が伝えたかったのは一度テントを張ったら朝まで外にでないことです。
		//   >   キャンプモード中にキャンプボタンは『WANT TO GO TO SLEEP?』にとんでください」
		//
		//   ★★**キャンプの中からは、走る画面へ戻る道がありません。**
		//     ★★★出る道は「眠って朝を迎える」ひとつだけ。
		//   ★だからキャンプボタンは「閉じる」ではなく、★★**出口と同じ問いかけへの近道**です
		//     （★リュックを開いていても、中身を見ていても、そこから直接聞けます）
		if (st.campPhase === "in" || st.campPhase === "bag" || st.campPhase === "box") {
			campAskSleep();
			return;
		}
		// ★もう聞いているときは、何も起きない（★二重に鳴らさない）
		if (st.campPhase === "sleep") return;
		// ★★「CAMP?」は**まだテントを張っていない**ので、いままでどおり取り消せる
		//   （★2026-09-04(2) 島さんの指定「いきなり入らない。誤操作による意図しない行動を防ぐ」。
		//     ★★ここで取り消せないと、押しまちがえたときに逃げ道がなくなります）
		if (st.campPhase === "ask") { campClose(); return; }
		// ★★開くのは夜のあいだだけ
		if (!isNightNow()) return;
		// ============================================================
		// ★★★★★いきなり入らない（2026-09-04 島さんの指定）
		// ============================================================
		//   > 島さん「CAMP?（キャンプにはいりますか？を問う。いきなり入らない。
		//   >   誤操作による意図しない行動を防ぐ。）」
		//
		//   ★★キャンプを出ると**翌日の朝**になります ＝ ★★★**夜が終わる**。
		//     ★だから「押しまちがえて入ってしまった」が起きると、取り返しがつきません。
		//     ★★ここで一度止めるのは、そのための「重み」です
		st.campPhase = "ask";
		st.campBtn = "";              // ★★どのボタンも押していない状態から
		st.shopOpen = false;          // ★お店とは同時に開かない
		st.paused = false;
		st.tapArmed = false;
		// ★★音は**仮**です（★お店の開閉音と同じ形で、高さだけ変えてあります）。
		//   ★★★**AIへ: 島さんが `tools/preview-sound.html` で選ぶまで、勝手に凝らないこと**
		sound(740, 0.06);
	}

	// ★キャンプをやめる（★入る前にやめた／中断した）
	function syncFishing() {
		var f = st.fishing, discovered = [];
		f.pool.forEach(function (o) { if (o.alive && !f.seen[o.type]) { f.seen[o.type] = true; discovered.push(o.type); } });
		if (PR && discovered.length) PR.observeFish(discovered);
		// ★★★★★釣り場の音（2026-09-15 島さんが選んだ）。★自然の出来事は js/fishing-sound.js、知らせは電子音
		f.events.splice(0).forEach(function (e) {
			if (e.type === 'cast' || e.type === 'water' || e.type === 'hit') fishSound(e);
			else if (e.type === 'miss') sound(165,.08);
			else if (e.type === 'catch') {
				if (PR) { PR.recordFish(e.data); f.records = PR.snapshot().fish; }
				fishSound(e);   // ★水から出る水音（★知らせの電子音は下のまま）
				melody(e.data.rare || e.data.giant || e.data.cm >= 35 ? [[660,.05,0],[880,.05,85],[1320,.09,170]] : [[660,.04,0],[880,.06,80]]);
			}
		});
		// ★泡・暴れる水音の合図（★遊びの出来事とは別の袋。★毎回ここで空にする）
		(f.sfx || []).splice(0).forEach(fishSound);
	}
	// ★★★★★釣り場の自然の音（★中身は js/fishing-sound.js。★音を切っているときは鳴らさない）
	function fishSound(e) {
		if (soundOn && global.DotFishSound) global.DotFishSound.event(e);
	}
	function fishAct(down, x, y, cancel) {
		if (down) global.DotFishing.press(st.fishing, x === undefined ? 156 : x, y === undefined ? 80 : y);
		else global.DotFishing.release(st.fishing, cancel);
		syncFishing();
	}
	function cancelFishingHold() {
		if (st && st.campPhase === 'fish') { global.DotFishing.release(st.fishing, true); st.fishOutside = false; }
	}
	if (global.addEventListener) global.addEventListener('blur', cancelFishingHold);
	if (typeof document !== 'undefined' && document.addEventListener) document.addEventListener('visibilitychange', function () { if (document.hidden) cancelFishingHold(); });
	function enterFishing() {
		if (!global.DotFishing || !st || st.campPhase !== "in" || st.shopOpen) return;
		if (!st.fishing) st.fishing = global.DotFishing.create(WD.getSeed() ^ Date.now());
		st.campVX = 0; st.campVY = 0;
		st.campBagMs = 0; st.campExitMs = 0; st.fishBtn = ""; st.saveBtn = ""; st.saveOkMs = 0; st.roadBtn = "";
		st.fishing.records = PR ? PR.snapshot().fish : {};
		st.fishing.seen = PR ? PR.snapshot().fishSeen : {};
		var opt = {}; try { opt = JSON.parse(global.localStorage.getItem('dotollie-options')) || {}; } catch (e) { /* defaults */ }
		st.fishing.options = { reduced: !!(global.matchMedia && global.matchMedia('(prefers-reduced-motion: reduce)').matches), shake: opt.shake !== 0, flash: opt.flash !== 0 };
		st.campPhase = "fish";
		saveGame("enter-fishing");     // ★★★場所を移るときは必ず書く（2026-09-21(6)）
		if (global.DotCampSound) global.DotCampSound.stop();   // ★キャンプの音は消す（★釣り場の音と二重にしない）
		if (soundOn && global.DotFishSound) global.DotFishSound.wake();   // ★触った瞬間に音を起こす（iPhone）
		cancelFishingHold(); syncFishing();
	}
	function enterMining() {
		if (!global.DotMining || !st || st.campPhase !== "in" || st.shopOpen) return;
		// ★素材・ツルハシ・その地点の鉱石は旅の記録から戻す（★テストモードでは読みも書きもしない）
		var saved = PR && PR.snapshot ? PR.snapshot().mining : null;
		st.mining = global.DotMining.create((WD.getSeed() ^ Date.now()) >>> 0, saved || null);
		st.mineSavedAt = Date.now(); st.mineDown = null; st.mineBtn = ""; st.fishBtn = "";
		st.campVX = 0; st.campVY = 0; st.campBagMs = 0; st.campExitMs = 0; st.saveBtn = ""; st.saveOkMs = 0;
		if (global.DotCampSound) global.DotCampSound.stop();   // ★キャンプの音は消す（★釣りと同じ）
		if (soundOn && global.DotMineSound) global.DotMineSound.wake();
		// ★★★すぐには切り替えず、「地上 → 地下」を短い絵と音で見せる（2026-09-21 島さんの指定）
		startTrip("down");
	}
	// ============================================================
	// ★★★★★キャンプ（地上）↔ 採掘（地下）のつなぎ（2026-09-21 島さんの指定）
	// ============================================================
	//   ★中身は `js/trip.js`（★段取り・時間・絵・音の名前は、ぜんぶあちら）
	//   ★★**途中の状態は保存しません**（★保存するのは camp か mining の、決まった形だけ）
	//   ★★★**1回押したら、そのまま目的地へ行きます**（2026-09-21(2) 島さんの指定）。
	//     ★途中で何も要求しない ／ ★初回も2回目も同じ ／ ★250ms の坑道ワイプ1つだけ
	function startTrip(dir) {
		if (!global.DotTrip || !st) return false;
		st.trip = global.DotTrip.create(dir);
		st.campPhase = "trip"; st.paused = false;
		st.mineDown = null; st.mineBtn = ""; st.fishBtn = "";
		return true;
	}
	// ★つなぎの出来事（音）→ 採掘の音の仕組みへ。★終わったら、行き先の画面に落ち着く
	function updateTrip(dt) {
		var T = global.DotTrip, tr = st.trip;
		if (!T || !tr) { st.campPhase = "in"; return; }
		var done = T.update(tr, dt);
		tr.sfx.splice(0).forEach(function (k) { if (soundOn && global.DotMineSound) global.DotMineSound.event({ type: k }); });
		if (!done) return;
		st.trip = null;
		if (tr.dir === "down") {
			st.campPhase = "mine";
		} else {
			st.campPhase = "in"; st.campVX = 0; st.campVY = 0;
			if (soundOn && global.DotCampSound) global.DotCampSound.wake();   // ★キャンプの音へ戻す
		}
	}
	function saveMining() {
		// ★★★★★ 2026-09-21(6): **`testMode` で止めるのをやめました**。
		//   ★ここで止めていたせいで、★★**テスト中は素材が1つも覚えられていませんでした**
		//   （★いまは `DotProgression` が「記憶だけモード」で受け止める ＝ 外には漏れない）
		if (!st || !st.mining || !PR || !PR.saveMining) return;
		PR.saveMining(global.DotMining.saveData(st.mining)); st.mining.dirty = false; st.mineSavedAt = Date.now();
	}
	// ============================================================
	// ★★★★★保存の入口はこの1つ（2026-09-21(6) 島さんの指定）
	// ============================================================
	//
	//   ★★**ここを呼べば、その瞬間のものがすべて書き出されます**。
	//     ★採掘の素材・ツルハシ ／ ★釣果（★釣った瞬間にも書いています）／
	//     ★財布・レベル・持ち物 ／ ★★スケボの総距離。
	//
	//   ★★★**AIへ: 保存をここ以外にもう一箇所作らないこと**。
	//     ★二重になった瞬間、★★「片方だけ直す」事故が作れるようになります
	var saveDirty = false, lastSaveAt = 0;
	var SAVE_DEBOUNCE = 1500;     // ★★続けざまに書かない（★最短 1.5 秒間隔）
	var lastSaveOK = 0, lastSaveReason = "";
	// ★何か変わったときに呼ぶ（★すぐには書かない。★★次の間隔でまとめて書く）
	function touchSave() { saveDirty = true; }
	// ★★走った分を総距離へ繰り入れる（★二重に数えないため、「前回より先」だけ）
	function commitDistance() {
		if (!st || !PR || !PR.addDistance) return 0;
		var now = meters(), from = Number.isFinite(st.distCommitted) ? st.distCommitted : now;
		var add = Math.floor(now - from);
		if (add > 0) { st.distCommitted = now; return PR.addDistance(add); }
		st.distCommitted = Math.max(from, now);
		return 0;
	}
	function saveGame(reason) {
		if (!st) return false;
		saveMining();                 // ★採掘（★中身の確かめは DotMining.saveData → cleanMining）
		saveCoins(); saveUpg(); saveItems();
		commitDistance();
		// ★★★★★**途中セーブも、ここで常に最新にします**（2026-09-22 島さんの指定）。
		//   ★★これが無いと、★★★**古いセーブの財布で、いまの財布を巻き戻してしまいます**。
		//   ★★★★また、常に最新なので**「閉じて開いてやり直す」ができません**。
		//     ★島さんの 2026-09-13 の決まり「やり直しに使えない」は、この形で守られます。
		//   ★★★★★**resumeMode はここでは絶対に書きません**（★手動 SAVE だけ）。
		if (st.phase !== "over" && st.stamina > 0) saveRun();
		if (PR && PR.flush) PR.flush();
		saveDirty = false; lastSaveAt = Date.now(); lastSaveOK = lastSaveAt; lastSaveReason = reason || "";
		return true;
	}
	// ★★★★★アプリを閉じる・裏に回る瞬間にも書く（2026-09-21(6)）
	//   ★iPhone では、ホームボタンを押した瞬間に★★**そのまま死んだことになる**ことがある。
	//   ★★`visibilitychange`（裏に回った）と `pagehide`（閉じる）の両方で書く
	var leaveBound = false;
	function bindLeaveSave() {
		if (leaveBound || !global.addEventListener) return;
		leaveBound = true;
		global.addEventListener("visibilitychange", function () {
			if (global.document && global.document.visibilityState === "hidden") saveGame("hidden");
		});
		global.addEventListener("pagehide", function () { saveGame("pagehide"); });
	}
	// ★★ちょっと間を置いて、まとめて書く（★毎フレーム書かない）
	function autoSaveTick() {
		if (!saveDirty || !st) return;
		if (Date.now() - lastSaveAt < SAVE_DEBOUNCE) return;
		saveGame("auto");
	}
	function leaveMining() {
		if (!st || st.campPhase !== "mine") return false;
		global.DotMining.release(st.mining);
		// ★★★飛んでいる途中の素材は、ここで必ず所持数にする（★戻ったせいで失われない）
		if (global.DotMining.collectAll) global.DotMining.collectAll(st.mining);
		saveMining();
		st.paused = false; st.mineBtn = ""; st.mineDown = null;
		st.campVX = 0; st.campVY = 0;
		// ★★★地下 → 地上（★つなぎのあいだ、採掘の状態はそのまま残す ＝ 壊さない）
		if (!startTrip("up")) st.campPhase = "in";
		saveGame("leave-mining");     // ★★★場所を移るときは必ず書く（2026-09-21(6)）
		return true;
	}
	// ★採掘の出来事 → 音。★素材が増えたら、ときどき保存（★2秒に1回まで。出るときは必ず保存）
	function syncMining() {
		var m = st.mining; if (!m) return;
		var upNow = false;
		m.events.splice(0).forEach(function (e) { if (soundOn && global.DotMineSound) global.DotMineSound.event(e); if (/^upgrade_/.test(e.type)) upNow = true; });
		if (m.dirty) touchSave();
		if (m.dirty && (upNow || Date.now() - (st.mineSavedAt || 0) > 2000)) saveMining();   // ★作ったときは、すぐ保存
	}
	function leaveFishing() {
		if (!st || st.campPhase !== "fish") return false;
		global.DotFishing.leave(st.fishing);
		saveGame("leave-fishing");     // ★★★場所を移るときは必ず書く（2026-09-21(6)）
		if (global.DotFishSound) global.DotFishSound.stop();
		st.campPhase = "in"; st.paused = false; st.fishBtn = "";
		st.campVX = 0; st.campVY = 0;
		return true;
	}

	function campClose() {
		if (!st) return;
		st.campPhase = "";
		st.campVX = 0; st.campVY = 0;
		st.campExitMs = 0;
		st.campBagMs = 0;
		sound(494, 0.06);
	}

	// ★★キャンプの中へ入る
	function campEnter() {
		st.campPhase = "in";
		if (lakesideCamp()) st.campLakeside = global.DotCampLakeside.create(WD.getSeed());
		if (soundOn && global.DotCampSound) global.DotCampSound.wake();   // ★触った瞬間に音を起こす（iPhone）
		st.campX = CAMP_START.x;
		st.campY = CAMP_START.y;
		st.campVX = 0; st.campVY = 0;
		st.campExitMs = 0;
		st.campSeen = true;
		sound(660, 0.09);
	}

	// ============================================================
	// ★★★★★キャンプを出る ＝ **翌日の朝**（2026-09-04 島さんの指定）
	// ============================================================
	//   > 島さん「キャンプを出る→翌日の朝にしたい。」「→朝スケボー。」
	//
	//   ★★やっているのは **夜の時計を 0 に戻す**だけ（★`st.dayMs = 0`）。
	//     ★時計は1つしか無いので、これで**そのまま朝になります**。
	//   ★★★**AIへ: ここで距離・コイン・体力に触らないこと**（★1日が終わっただけ）
	// ★★眠りにつく（★ここではまだ切り替えない。★ゆっくり暗くなるだけ）
	function campSleepStart() {
		st.campPhase = "fade";
		if (global.DotCampSound) global.DotCampSound.stop();   // ★眠りにつく ＝ キャンプの音は静かに消える
		st.campFadeMs = 0;
		st.campBtn = "";
		st.campVX = 0; st.campVY = 0;
		// ============================================================
		// ★★★★★眠りにつく音（2026-09-04(5)。★島さん「仮でそれっぽいものを」）
		// ============================================================
		//   ★★**だんだん低く、だんだん長く**（★沈んでいく形）。
		//     ★最後だけ2つ重ねて厚くします（★底に着いた感じ）。
		//   ★★★暗転（0.7秒）とほぼ同じ長さに揃えてあるので、
		//     ★**音が終わるころに画面がまっ暗**になります。
		//   ★★聴き比べ: `tools/preview-sound.html` の **S①/S②**
		melody([
			[392, 0.16,   0],
			[330, 0.18, 170],
			[262, 0.24, 360],
			[196, 0.55, 600], [147, 0.55, 600]
		]);
	}

	// ============================================================
	// ★★★★★まっ暗のあいだに、朝へ切り替える（2026-09-04(4) 島さんの指定）
	// ============================================================
	//   ★★**呼ばれるのは、暗転しきった瞬間だけ**（★`campSleepStart` から `CAMP_FADE_MS` 後）。
	//   ★★★**AIへ: ここで `st.dist` に触らないこと**（★島さんの指定「場所は続きから」）
	function campWakeMorning() {
		// ★★★★★2026-09-04(6)、**ここではまだ READY を出しません**（★島さんの指定）。
		//   > 島さん「朝音後0.5秒後にREADY/GOお願いします。」
		//   ★★朝の音を鳴らして明け始め、★★★0.5秒たってから READY へ（→ `updateCamp`）
		st.campPhase = "wake";
		st.campReadyMs = CAMP_READY_MS;
		st.campVX = 0; st.campVY = 0;
		st.campExitMs = 0;
		st.campBagMs = 0;
		st.campFadeMs = 0;
		st.campDarkMs = 0;
		// ============================================================
		// ★★★★★地面に接地させる（2026-09-04(7) 島さんの指定）
		// ============================================================
		//   > 島さん「スケーターが地面と接地していること。」
		//
		//   ★★キャンプに入った瞬間に**跳んでいた**り**レールに乗っていた**りすると、
		//     ★★★世界が止まったまま**空中の姿のまま**朝を迎えてしまいます。
		//   ★ここで**地上へ戻します**（★足の浮きが 0 になる）。
		//     ★★テストが  で毎回測っています
		//   ★★★2026-09-05、★**エンディングのあとと同じ道具**にまとめました
		//     （★同じことを2か所に書かない ＝ つぶまきと同じ決まり）
		standStill();
		st.speedMs = 0;           // ★加速をやり直す
		st.dayMs = 0;             // ★★★時間は朝スタート（★島さんの指定）
		// ============================================================
		// ★★★★★寝たら HP が回復する（2026-09-05 島さんの指定）
		// ============================================================
		//   > 島さん「寝たらHP回復してください。」
		//
		//   ★★**満タンまで戻します**（★MAXdrink の「全回復」とまったく同じ形）。
		//   ★★★**満タンもそろえること**（★2026-08-23 に踏んだ罠）:
		//     ★キャンプの中でも STAMINA を買えるようになったので（2026-09-05(4)）、
		//     ★★そろえないと**新しい満タンまで回復したのにバーは古い満タンで割る**
		//       ＝ ★★★**何回ぶつかってもバーが動かない**（＝「ダメージを受けない」に見える）
		if (CAMP_HEAL_ON) {
			st.staminaMax = curStaminaMax();
			st.stamina = st.staminaMax;
		}
		// ★★★★障害物とコインを、周囲から消す（★島さんの指定「周囲に無い事」）
		//   ★いま画面にあるものを消し、★★`wakeWx` の周りには**しばらく置かない**
		st.cones = [];
		st.picks = [];
		st.wakeWx = worldX();     // ★★ここが「朝スタートの場所」
		st.wakeMs = CAMP_WAKE_MS; // ★★ゆっくり明ける（★READY は 0.5秒後）
		syncCampPad();            // ★朝になったので、キャンプボタンを引っこめる
		// ============================================================
		// ★★★★★朝の音（2026-09-04(5)。★島さん「仮でそれっぽいものを」）
		// ============================================================
		//   ★★**まっすぐ駆け上がって、和音で満ちて、最後にきらめき2つ**。
		//     ★眠りの音（下がる）と、★★**ちょうど逆向き**にしてあります。
		//   ★★★明ける（0.7秒）とほぼ同じ長さなので、
		//     ★**明けきるころに、いちばん高い音**が鳴ります。
		//   ★★聴き比べ: `tools/preview-sound.html` の **M①/M②**
		melody([
			[392,  0.10,   0],
			[523,  0.10, 100],
			[659,  0.12, 200],
			[784,  0.30, 320], [1047, 0.30, 320],
			[1319, 0.16, 560],
			[1568, 0.22, 660]
		]);
	}

	// ★★朝スタートの周りは、障害物もコインも置かない（★`inGoalClear` と同じ形）
	function inWakeClear(wx) {
		if (!st || st.wakeWx === null || st.wakeWx === undefined) return false;
		return Math.abs(wx - st.wakeWx) <= CAMP_WAKE_CLEAR;
	}

	// ★★★「ここには置かない」を1か所にまとめたもの
	//   ★ゴールの扉の前後（2026-08-23）と、★★朝スタートの周り（2026-09-04(4)）
	function inNoSpawn(wx) { return inGoalClear(wx) || inWakeClear(wx); }

	// ★★問いかけの答え（★`which` … 0 = YES / 1 = NO）
	//   ★★★2026-09-04、島さんの指定で**押したボタンで決まる**ようになりました
	function campAnswer(which) {
		if (!st) return;
		if (st.campPhase === "ask") {
			if (which === 0) campEnter();      // ★YES → 中へ
			else campClose();                   // ★NO  → やめる
		} else if (st.campPhase === "bag") {
			// ★★★★★リュックサック（2026-09-04(5) 島さんの指定）
			if (which === 0) { st.campPhase = "box"; sound(880, 0.07); }   // ★YES → 中身を見る
			else campLeaveBag();                                           // ★NO  → 何もしない
		} else if (st.campPhase === "sleep") {
			if (which === 0) campSleepStart();     // ★YES → ★★まず、ゆっくり暗転
			else {
				// ★★NO → キャンプに戻る。★出口から少し離す（★すぐまた聞かれないように）
				st.campPhase = "in";
				st.campExitMs = 0;
				// ★★★★離すのは「出口に立っているとき」だけ（2026-09-05）。
				//   ★キャンプボタンからも聞けるようになったので、
				//     ★★離れた場所で NO を押したのに**出口へ引き寄せられる**のを防ぐ
				if (inCampExit()) st.campY = Math.max(CAMP_WALK.y0, CAMP_EXIT.y - 14);
				sound(494, 0.06);
			}
		}
	}

	// ============================================================
	// ★★★★★YES / NO のボタンは、どこに出ているか（2026-09-04）
	// ============================================================
	//   ★★**描くところと、さわったかを見るところが、この1か所を共有します。**
	//     ★★★別々に持つと「見た目と当たり判定がずれる」——
	//       ★この作品が 2026-08-22 と 08-31 に2度踏んだ罠です
	function campAskTop() {
		return Math.round(H / 2) - (global.DotFont.GLYPH_H + 5);
	}

	function campBtnRects() {
		if (!CBTN || !CBTN.YES) return null;
		var bw = CBTN.YES.rows[0].length, bh = CBTN.YES.rows.length;
		var all = bw * 2 + CAMP_BTN_GAP;
		var x0 = Math.round((W - all) / 2), y0 = campAskTop() + CAMP_BTN_DY;
		return {
			yes: { x: x0, y: y0, w: bw, h: bh },
			no: { x: x0 + bw + CAMP_BTN_GAP, y: y0, w: bw, h: bh }
		};
	}

	// ★さわったところが、どちらのボタンか（★""＝どちらでもない）
	function campHitBtn(lx, ly) {
		var r = campBtnRects();
		if (!r || lx < 0 || ly < 0) return "";
		if (lx >= r.yes.x && lx < r.yes.x + r.yes.w &&
			ly >= r.yes.y && ly < r.yes.y + r.yes.h) return "yes";
		if (lx >= r.no.x && lx < r.no.x + r.no.w &&
			ly >= r.no.y && ly < r.no.y + r.no.h) return "no";
		return "";
	}

	// ★★★★★足がリュックサックのそばにあるか（2026-09-04(5)）
	function inCampBag() {
		return st.campX >= CAMP_BAG.x && st.campX <= CAMP_BAG.x + CAMP_BAG.w &&
			st.campY >= CAMP_BAG.y && st.campY <= CAMP_BAG.y + CAMP_BAG.h;
	}

	// ★リュックから少し離れる（★すぐまた聞かれないように）。★出口の NO とまったく同じ形
	function campLeaveBag() {
		st.campPhase = "in";
		st.campBagMs = 0;
		st.campX = Math.min(CAMP_WALK.x1, CAMP_BAG.x + CAMP_BAG.w + 12);
		sound(494, 0.06);
	}

	// ★★足が出口に入っているか（★島さんの絵の、右下の木の橋）
	function inCampExit() {
		return st.campX >= CAMP_EXIT.x && st.campX <= CAMP_EXIT.x + CAMP_EXIT.w &&
			st.campY >= CAMP_EXIT.y && st.campY <= CAMP_EXIT.y + CAMP_EXIT.h;
	}

	// ============================================================
	// ★★★★★キャンプの中の時間（2026-09-04）
	// ============================================================
	//   ★★**世界は止まったまま**です（★距離も夜の時計も進まない）。
	//     ★ここで進むのは「中を歩いている」ことだけ。
	//   ★★★問いかけ（CAMP? / WANT TO GO TO SLEEP?）のあいだは、**中も止まります**
	function updateCamp(dt) {
		// ★★キャンプ ↔ 採掘のつなぎ（★このあいだ、採掘も釣りも動かさない）
		if (st.campPhase === "trip") { updateTrip(dt); return; }
		if (st.campPhase === "mine") {
			if (typeof document === "undefined" || !document.hidden) global.DotMining.update(st.mining, dt);
			syncMining();
			return;
		}
		if (st.campPhase === "fish") {
			if (typeof document === "undefined" || !document.hidden) global.DotFishing.update(st.fishing, dt);
			else cancelFishingHold();
			syncFishing();
			// ★池の環境音とリールの音（★ここが呼ばれなくなる＝一時停止・ショップ・池を出た → 音は静かに消える）
			if (global.DotFishSound) global.DotFishSound.frame(st.fishing, soundOn && (typeof document === "undefined" || !document.hidden));
			return;
		}
		// ★★★★★眠りにつく途中（★ゆっくり暗転）。2026-09-04(4) 島さんの指定
		if (st.campPhase === "fade") {
			st.campFadeMs += dt * 1000;
			// ★★まっ暗になったら、★★★**そのまま1秒待つ**（2026-09-04(6) 島さんの指定）
			if (st.campFadeMs >= CAMP_FADE_MS) { st.campPhase = "dark"; st.campDarkMs = 0; }
			return;
		}
		// ★★★★★まっ暗のまま待つ（★「夜が過ぎた」の合図）。2026-09-04(6)
		if (st.campPhase === "dark") {
			st.campDarkMs += dt * 1000;
			if (st.campDarkMs >= CAMP_DARK_MS) campWakeMorning();   // ★朝を迎える
			return;
		}
		// ★★★★★朝を迎えて、明けていく途中（2026-09-04(6)）
		//   ★★世界はまだ止まったまま。★★★朝の音から 0.5秒たったら READY へ
		if (st.campPhase === "wake") {
			st.campReadyMs -= dt * 1000;
			if (st.campReadyMs <= 0) {
				st.campPhase = "";
				readyAgain();     // ★★スケーター待機 ＋ READY / GO
			}
			return;
		}
		if (st.campPhase !== "in") return;
		if (st.saveOkMs > 0) st.saveOkMs = Math.max(0, st.saveOkMs - dt * 1000);   // ★SAVED の消えこみ
		if (lakesideCamp()) {
			st.campVX = 0; st.campVY = 0; st.campBagMs = 0; st.campExitMs = 0;
			if (!st.campLakeside) st.campLakeside = global.DotCampLakeside.create(WD.getSeed());
			if (typeof document === "undefined" || !document.hidden) global.DotCampLakeside.update(st.campLakeside, dt);
			// ★★★★★キャンプの音（2026-09-18 島さんが選んだ B 構成。中身は js/camp-sound.js）
			//   ★ここが呼ばれなくなる ＝ 一時停止・ショップ・眠り・朝・釣り → 音は静かに消える
			if (global.DotCampSound) global.DotCampSound.frame(st.campLakeside, soundOn && (typeof document === "undefined" || !document.hidden));
			return;
		}
		if (st.campVX || st.campVY) {
			// ★★★★★向きを決めて、コマを進める（2026-09-05）。
			//   ★止まっているあいだは進めない ＝ **0コマ目のまま立つ**
			st.campDir = campDirOf(st.campVX, st.campVY);
			st.campWalkMs += dt * 1000;
			st.campX += st.campVX * CAMP_SPEED * dt;
			st.campY += st.campVY * CAMP_SPEED * dt;
			if (st.campX < CAMP_WALK.x0) st.campX = CAMP_WALK.x0;
			if (st.campX > CAMP_WALK.x1) st.campX = CAMP_WALK.x1;
			if (st.campY < CAMP_WALK.y0) st.campY = CAMP_WALK.y0;
			if (st.campY > CAMP_WALK.y1) st.campY = CAMP_WALK.y1;
		} else {
			st.campWalkMs = 0;      // ★★止まったら 0コマ目へ（★向きはそのまま覚えている）
		}
		// ★★★★★リュックサックに「少し立ったら」聞く（2026-09-04(5) 島さんの指定）
		//   ★出口とまったく同じ形（★通りかかっただけでは聞かれない）
		if (inCampBag()) {
			st.campBagMs += dt * 1000;
			if (st.campBagMs >= CAMP_BAG_MS) {
				st.campPhase = "bag";
				st.campVX = 0; st.campVY = 0;
				sound(740, 0.06);
				return;
			}
		} else {
			st.campBagMs = 0;
		}
		// ★★出口に「少し立ったら」聞く（★通りかかっただけで聞かれないように）
		if (inCampExit()) {
			st.campExitMs += dt * 1000;
			if (st.campExitMs >= CAMP_EXIT_MS) campAskSleep();
		} else {
			st.campExitMs = 0;
		}
	}

	// ============================================================
	// ★★★★★「WANT TO GO TO SLEEP?」と聞く（★1か所にまとめてある）
	// ============================================================
	//   ★呼ぶのは2つ:
	//     ① ★出口に少し立ったとき（→ `updateCamp`）
	//     ② ★★**キャンプボタンを押したとき**（→ `toggleCamp`。2026-09-05 島さんの指定）
	//   ★★★**2か所に書かない**（★問いかけの出し方がずれると、片方だけ直す事故になる）
	function campAskSleep() {
		st.campPhase = "sleep";
		st.campBtn = "";
		st.campVX = 0; st.campVY = 0;
		st.campExitMs = 0;
		st.campBagMs = 0;
		sound(740, 0.06);
	}

	function update(dt) {
		if (!assistsActive()) clearActionAssist();
		// ★★★★★夜になったらキャンプボタンを出す／朝になったら引っこめる（2026-09-04）
		//   ★★**いちばん先に呼ぶ**（★GAMEOVER でも一時停止でも、必ず通る場所）。
		//   ★変わったときだけシェルに頼むので、毎コマ呼んでも重くありません
		syncCampPad();
		// ============================================================
		// ★★★★★パネルのグリッチフェードイン（2026-09-12 島さんの指定）
		// ============================================================
		//   ★★★★**下の「お店のあいだは止まる」より前に置くこと。**
		//     ★知らせるのは**お店の中のパネル**なので、
		//     ★★後ろに置くと**お店を閉じるまで 1 コマも進みません**
		//     （★★★ 2026-09-12 に実際にそうなっていました）。
		//   ★★★**減らすのはここ 1 か所だけ**（★つぶまきの決まりと同じ）
		if (st.prestigeMs > 0) st.prestigeMs = Math.max(0, st.prestigeMs - dt * 1000);
		Object.keys(st.panelFx || {}).forEach(function(id) { st.panelFx[id] = Math.max(0, st.panelFx[id] - dt * 1000); });
		// ★★ショップ・一時停止のあいだは、何も進まない
		if (st.paused || st.shopOpen) return;
		// ============================================================
		// ★★★★★明けていく（2026-09-04(6)）。★**ここ1か所だけで減らします**
		// ============================================================
		//   ★キャンプの中（"wake"）でも、READY でも、走っていても、ここを必ず通ります。
		//   ★★2か所で減らすと「片方だけ直す」事故が起きます（★つぶまきの決まりと同じ）
		if (st.wakeMs > 0) st.wakeMs = Math.max(0, st.wakeMs - dt * 1000);
		// ★★★★★キャンプの中（2026-09-04）。★**世界は止まったまま**、中の歩きだけ進む
		//   ★これで `st.dayMs`（夜の時計）も止まります（★お店とまったく同じ考え方）
		if (st.campPhase) { updateCamp(dt); return; }
		// ★★ラン終了。★世界は止まったまま、コインの数え上げだけ進む
		if (st.phase === "over") { updateOver(dt); return; }
		// ★★★★5000m のエンディング（2026-08-22）。★世界は止まったまま、演出だけ進む
		if (st.phase === "ending") { updateEnding(dt); return; }
		// ★★★★二段ジャンプを授かる場面（2026-08-22）。★これも世界は止まったまま
		if (st.phase === "gift") { updateGift(dt); return; }
		// ★★★キャンプで選んでいるあいだは、世界が止まる（2026-08-16 / Phase D）
		//   ★距離も倍率も増えない（★「止まって考える場所」なので）
		if (st.phase === "camp") {
			if (st.campStopMs > 0) st.campStopMs = Math.max(0, st.campStopMs - dt * 1000);
			return;
		}

		updatePhase(dt);

		// ★★enter と READY のあいだは世界が止まる（進まない・コーンも流れない）。
		//   ★スケーターは**立ちのまま待つ**（プッシュは GO の瞬間から）
		if (isFrozen(st.phase)) { updateStandby(dt); return; }

		// ★扉の光り（★描画だけ）。★**下の早い戻りより前に置くこと**。
		//   後ろに置くと、スタミナ 0 のあいだ時間が進まず**点滅しない**
		if (st.gateFlashMs > 0) st.gateFlashMs = Math.max(0, st.gateFlashMs - dt * 1000);
		if (st.shakeMs > 0) st.shakeMs = Math.max(0, st.shakeMs - dt * 1000);

		// ★★★2026-08-16、**スタミナは時間では減らない**（島さんの指定）。
		//   ★減るのは `onHit()` の中だけ ＝ **ぶつかった回数ぶん**。
		//   ★ここは「0 になったら終わり」の見張りだけが残っている
		// ============================================================
		// ★★★MAXdrink（2026-08-22 島さんの指定）
		// ============================================================
		//   > 島さん「回復のタイミングは残り体力が0になった時です」
		//
		//   ★★**GAMEOVER の判定より前**に置くこと。
		//     ★後ろに置くと、先に `runOver()` が走って**使う前に終わってしまう**。
		//   ★1本使って**満タンまで**戻す（★「全回復」＝ 島さんの指定）
		//   ★`st.phase !== "over"` … ★すでに終わっているときは使わない
		if (DRINK_ON && st.stamina <= 0 && bagCount("maxdrink") > 0 && st.phase !== "over") {
			bag.maxdrink = bagCount("maxdrink") - 1;
			saveUpg();
			// ★★★満タンもそろえる（2026-08-23 に直した）。
			//   ★そろえないと、★★**新しい満タンまで回復したのにバーは古い満タンで割る**ので、
			//     ★★★**何回ぶつかってもバーが動かない**（＝島さんが見つけた「ダメージを受けない」）
			st.staminaMax = curStaminaMax();
			st.stamina = Math.min(st.staminaMax, drinkRecovery());
			st.reviveMs = REVIVE_MS;            // ★演出
			reviveSound();                      // ★心地よい音
		}
		// ★★★★絵の時計を進める（2026-08-27）。★見た目だけ
		st.animMs += dt * 1000;
		st.dayMs += dt * 1000;    // ★★★★★昼と夜の時計（2026-09-02）。★見た目だけ
		updateStars(dt);          // ★★★★★夜空の星（2026-09-05）。★見た目だけ
		updateRain(dt);           // ★★★★★天気：雨（2026-09-06）。★見た目だけ
		if (st.reviveMs > 0) st.reviveMs = Math.max(0, st.reviveMs - dt * 1000);
		// ★★★★BET を払った瞬間の点滅（2026-08-23）
		if (st.betFlashMs > 0) st.betFlashMs = Math.max(0, st.betFlashMs - dt * 1000);

		if (st.stamina <= 0) {
			st.stamina = 0;
			// ★★★扉で止められたときだけ「間」を置く（2026-08-16 のレビュー C-1）
			//
			//   ★問題だったこと: 扉に当たった瞬間にスタミナが 0 になり、
			//     **その次の1コマ（約16ms）でリザルト画面が扉を塗りつぶしていた**。
			//     ★しかも扉の13列のうち9列は**主役の体で隠れている**。
			//     → **なぜ終わったのかが、画面のどこにも映らない**。
			//
			//   ★★だから扉のときだけ、リザルトへ行く前に**少し止まって見せる**。
			//     ★遊びは1ドットも変わらない（★世界は止まっている。距離も増えない）
			if (st.gateStopMs > 0) { st.gateStopMs -= dt * 1000; return; }
			runOver({ reset: true });   // ★★★GAMEOVER ＝ 育てたものを全部なくす
			return;
		}

		// ★ぶつかったあとの減速（残り時間が減っていく）
		if (st.slowMs > 0) st.slowMs = Math.max(0, st.slowMs - dt * 1000);
		var slowFactor = (st.slowMs > 0) ? 1 - (1 - HIT_SLOW) / (1 + upgLevel("wheels") * 0.2) : 1;

		// ★★走り出しの加速。GO からの経過で、速さがじわっと上がる
		st.speedMs += dt * 1000;
		// ★★SPEED のアップグレードはここで効く（→ `curSpeed()`）
		var moved = curSpeed() * accelFactor() * slowFactor * dt;
		updateLive(dt);
		st.assistClock += dt * 1000;
		st.assistPrevLift = currentLift();
		st.cornerShift = Math.max(0, st.cornerShift - moved);
		var hitsBeforeMove = st.hits;
		st.dist += moved;
		st.hpGrowMs = Math.max(0, st.hpGrowMs - dt * 1000);

		// ★★見た目だけのもの（★遊びには触らない）を進める
		updatePops(dt);
		updateSparks(dt);   // ★★★★跳んだ軌跡のきらめき（★ここは一時停止・ショップ・
		                    //   GAMEOVER・エンディング・READY を全部くぐった先＝止まると進まない）
		updateDrone(dt);
		updateDusts(dt);    // ★★★★跳んだときの土けむり（2026-08-31）
		if (st.gainFlashMs > 0) st.gainFlashMs = Math.max(0, st.gainFlashMs - dt * 1000);
		// ★揺れと扉の光りは、**スタミナの判定より前**で進めてある（上を見ること）

		// ★★距離の節目（★進むほど間隔が広がる。★距離は報酬の主役ではない）
		//   ★★2026-08-15、島さんの指定で **いったん出さない**（`MILESTONE_POP_ON = 0`）
		var mile = milestoneAt(st.mileIndex);
		if (meters() >= mile) {
			if (MILESTONE_POP_ON) addPop("+" + mile + "m", "gain");
			st.mileIndex++;
		}
		// ★★★2026-08-16、**走っているだけではコインが増えない**（島さんの指定）。
		//   ★増えるのは「障害物を1つ越えた瞬間」だけ（→ `gainCoin()`）。
		//   ★★これで**距離は「どこまで行けたか」だけの意味**になり、稼ぎと役割が分かれた

		// ★三角コーン: 画面の右の外から出して、左へ流す
		// ★★★注意: この `if` の中には**障害物ぜんぶ**（コーン・敵・扉・鍵・当たり判定）が入っている。
		//   ★`CONE_ON = 0` にすると、コーンだけでなく**全部消える**（★昔からこの形）
		if (CONE_ON) {
			st.nextCone -= moved;
			if (st.nextCone <= 0) {
				// ★★出そうとした場所が「まっすぐな道の本体」のときだけ出す（2026-08-11）
				//   `>= 1` ＝ 完全に平らなところ。**入口と出口のなだらかな坂には置かない**
				//   平らでなければ「今回は出さない」だけ（抽選のタイミングはそのまま進む）
				var bornAt = worldX() + W + 4;
				// ★★2026-08-15（Phase 2）: 1個ずつではなく**パターンをまるごと**置く。
				//   ★パターンの順番は A→B→C→D の巡回。**種（シード）では決めない**
				//     （既存の決まり: 障害物を種で決めると「覚えゲー」になる）
				//   ★★2026-08-16（Phase C）: **出す場所の距離**でパターンを太らせる。
				//     ★「いま何メートル走ったか」ではなく **`bornAt`（そのコーンが立つ場所）**
				//       で決める。★そうしないと、同じ場所なのに来かたで幅が変わる
				var pat = PATTERN_ON ? patternAt(st.patIndex, bornAt) : null;
				var len = pat ? patternLen(pat) : 0;
				// ★★パターンの**端から端まで**が平らな道の上に乗るときだけ置く
				// ★★★扉の前後は何も置かない（2026-08-23 島さんの指定）。
				//   ★★パターンの**端から端まで**が、あけておく帯にかからないこと
				// ★★★★レールが近ければ、コーンは置かない（2026-08-31）。
				//   ★★**両側が互いを見ます**（★片側だけでは防げない＝鳥のときの教訓）
				//   ★★★見るのは**レールだけ**（★`railNearAt`）。
				//     ★ここで「何か」を見ると、★★コーンどうしが弾き合って**半減**します
				var clearOK = !inNoSpawn(bornAt) && !inNoSpawn(bornAt + len) &&
					!railNearAt(bornAt, len);
				if (pat && clearOK &&
					WD.flatnessAt(bornAt) >= 1 && WD.flatnessAt(bornAt + len) >= 1) {
					for (var oi = 0; oi < pat.obs.length; oi++) {
						for (var ci = 0; ci < pat.obs[oi].n; ci++) {
							var off = pat.obs[oi].at + ci * CONE_W;
							// wx = ★このコーンが**世界のどこに立っているか**。
							//   描くのには使わないが、「本当に平らな道の上か」を測るときの正。
							//   画面の x から逆算すると丸めが二重にかかってブレる
							st.cones.push({ x: W + 4 + off, wx: bornAt + off });
							st.conesBorn++;           // ★テストが「全滅していないか」を見る
						}
					}
					// ============================================================
					// ★★★★D案: コーンの真上にも1列（2026-08-23 島さんの指定）
					//
					//   > 島さん「D導入。いづれの案も美しい配置優先。」
					//
					//   ★★**どうせ跳ぶ**ので、跳ぶ意味が2つ重なる
					//     （★避ける動きと拾う動きが**同じ**なので、1ボタンでも成立する）。
					//   ★★★**コーンの塊のまん中にそろえる**（★美しい配置優先）
					//
					//   ★★ここは「重ねない」の**例外**です（→ ふつうの列は重ねません）。
					//     ★理由がはっきり違う: ★あちらは「別の動きを同時に要求しない」ため
					// ============================================================
					if (PICK_ON && COIN_ICON && !st.pickQuiet && st.picks.length <= PICK_MAX - PICK_N && meters() >= PICK_FROM_M &&
						!inNoSpawn(bornAt) && Math.random() < PICK_OVER_CONE) {
						// ★塊の広さに合わせて枚数を決める（★はみ出させない）
						var overN = Math.max(3,
							Math.min(PICK_N, Math.round(len / PICK_STEP) + 1));
						var overW = (overN - 1) * PICK_STEP + PICK_W;
						// ★★★コーンの塊の**本当の端から端**でまん中を出す（★美しい配置優先）。
						//   ★`len` から出すと数ドットずれる（★2026-08-23 に実測して直した）
						var gMin = pat.obs[0].at;
						var gLast = pat.obs[pat.obs.length - 1];
						var gMax = gLast.at + gLast.n * CONE_W;
						var ox0 = W + 4 + Math.round((gMin + gMax - overW) / 2);
						var overMade = makeRow(ox0,
							{ rows: [{ n: overN, step: PICK_STEP, lift: 1.00 }] });
						if (!pickRowAllowed(overMade)) overMade = [];
						// ★★印を付けておく（★テストが「コーンの真上か」を測るため）
						for (var vi = 0; vi < overMade.length; vi++) {
							overMade[vi].over = 1;
							st.picks.push(overMade[vi]);
						}
						if (overMade.length) {
							st.picksBorn++;
							// ★★ふつうの列とぶつからないよう、次の抽選を先へずらす
							st.nextPick = Math.max(st.nextPick, len + nextPickGap());
						}
					}

					st.patIndex++;
					// ★★次のパターンまで、ひと呼吸あける。
					//   ★★**「1回の技で進む距離」より必ず広くする**（→ 上の「欠陥」の説明）
					st.nextCone = len + coneGapMin();
				} else {
					st.nextCone = nextConeGap();      // すこし進んで、また試す
				}
			}
			// ★★丘の敵（2026-08-15、島さんの指定で新設）。
			//   ★コーンは「まっすぐな道」、敵は「丘」。**場所で住み分ける**
			if (ENEMY_ON) {
				st.nextEnemy -= moved;
				if (st.nextEnemy <= 0) {
					var enemyAt = worldX() + W + 4;
					// ★丘のときだけ（＝まっすぐな道ではないとき）
					//   ★★★扉の前後は何も置かない（2026-08-23 島さんの指定）
					// ★★★★2026-08-27、**鳥が近ければ置きません**（★島さん「ケンカにならないように」）。
					//   ★鳥のほうが数が少ないので、★★**先に居るほうを残します**
					// ★★★★★2026-09-02、**レールが近ければ置きません**。
					//   ★レールが坂にも出るようになったので、★★ここで初めて隣り合います。
					//   ★★★見るのは**レールだけ**（`railNearAt`）＝
					//     ★スライムどうしは弾き合いません（★コーンで踏んだ罠）
					if (WD.flatnessAt(enemyAt) <= 0 && !inNoSpawn(enemyAt) &&
						!railNearAt(enemyAt, ENEMY_W) &&
						!(((TORI_ON && TORI) || (AOSURA_ON && AOSURA)) &&
							tooCloseForTori(enemyAt, "enemy"))) {
						st.cones.push({ x: W + 4, wx: enemyAt, kind: "enemy" });
						st.enemiesBorn++;
					}
					st.nextEnemy = nextEnemyGap();
				}
			}

			// ============================================================
			// ★★★★★レール（2026-08-31 新設 → ★2026-09-02、坂にも出るようにした）
			// ============================================================
			//
			//   > **島さん「レールは坂(上り下り)でも出現するようにします。」**（2026-09-02）
			//
			//   ★★**世界のどこにでも出ます**（★平地・上り・下りを選びません）。
			//     ★★★レールは**まっすぐな1本**（★両端を結ぶ）なので、坂でも
			//       ★めり込みません（→ `railRowAtOff`）。★実測: 地面から 10〜17ドット
			//
			//   ★★★これで**住み分けが3つ**になりました:
			//     ★コーン … まっすぐな道だけ ／ ★スライム・鳥 … 丘だけ ／
			//     ★★**レール … どこでも**（★だから、どちらとも隣り合いうる）
			//
			//   ★扉の前後は何も置かない（2026-08-23 島さんの指定）
			//   ★★他の障害物とケンカしない（★`railClashAt` が両側から見張る）
			//   ★★★**種で決めない**（★間隔はランダム ＝ 覚えゲーにしない）
			if (railEnabled() && RAIL) {
				st.nextRail -= moved;
				if (st.nextRail <= 0) {
					var railAt = worldX() + W + 4;
					if (!inNoSpawn(railAt) && !inNoSpawn(railAt + RAIL_LEN) &&
						!railClashAt(railAt, RAIL_LEN)) {
						st.cones.push({ x: W + 4, wx: railAt, kind: "rail" });
						st.railsBorn++;
						// ★★置けたときだけ、次までを長く取る（★連続で並ばないように）
						st.nextRail = RAIL_LEN + nextRailGap();
					} else {
						// ★★置けなかったら**すぐ試し直す**（★コーンとまったく同じ作法）。
						//   ★★★2026-09-02、★**ここを通ることはめったに無くなりました**
						//     （★前は「まっすぐな道が世界の14%しかない」ので毎回ここでした）。
						//     ★いま止めるのは「扉の前後」と「他の障害物が近い」ときだけ
						st.nextRail = RAIL_RETRY;
					}
				}
			}

			// ★★★★丘の敵その2（鳥）。2026-08-27、島さんの指定で新設
			//   ★★**仕様はスライムと同じ**（★丘にだけ置く／地面に立つ／扉の前後は空ける）。
			//   ★★★ちがうのは2つだけ:
			//     ① ★間隔が広い（★出やすさが低い）
			//     ② ★★ほかの障害物が近ければ**置かない**（★ケンカを構造的に防ぐ）
			if (TORI_ON && TORI) {
				st.nextTori -= moved;
				if (st.nextTori <= 0) {
					var toriAt = worldX() + W + 4;
					if (WD.flatnessAt(toriAt) <= 0 && !inNoSpawn(toriAt) && !tooCloseForTori(toriAt, "tori")) {
						st.cones.push({ x: W + 4, wx: toriAt, kind: "tori" });
						st.toriBorn = (st.toriBorn || 0) + 1;
					}
					st.nextTori = nextToriGap();
				}
			}

			// ============================================================
			// ★★★★★丘の敵その3（青スライム）。2026-09-05、島さんの指定で新設
			// ============================================================
			//   > 島さん「完全に夜になると出現する敵を描きました。」
			//
			//   ★★**鳥とまったく同じ形**（★丘にだけ置く／扉の前後は空ける／
			//     ★★ほかの障害物が近ければ置かない）。
			//   ★★★ちがうのは **`isFullNight()`** の1行だけです。
			//     ★暮れている途中（薄暗い）も、明けている途中も出ません
			if (AOSURA_ON && AOSURA) {
				st.nextAosura -= moved;
				if (st.nextAosura <= 0) {
					var aoAt = worldX() + W + 4;
					if (isFullNight() && WD.flatnessAt(aoAt) <= 0 && !inNoSpawn(aoAt) &&
						!tooCloseForTori(aoAt, "aosura")) {
						st.cones.push({ x: W + 4, wx: aoAt, kind: "aosura" });
						st.aosuraBorn = (st.aosuraBorn || 0) + 1;
					}
					st.nextAosura = nextAosuraGap();
				}
			}

			// ============================================================
			// ★★★★飛ぶ敵（2026-08-23 島さんの指定で新設）
			// ============================================================
			//   > 島さん「空に敵がいると『ここは跳ばない』が初めて生まれます」
			//   > 島さん「エンディング後に出現にしてください。」
			//
			//   ★★**`st.goalDone`** ＝ CONTINUE を押した（★エンディングを見終えた）。
			//     ★★★見る前は**1羽も出ません** ＝ ★はじめて遊ぶ人の空は1ドットも変わらない。
			//     ★`st.dj`（二段ジャンプ）ではないのは、★★`DJ_ON = 0` で鳥まで消えるため。
			//
			//   ★★★**地上の障害物から必ず離す**（→ `birdKeepAway()`）。
			//     ★真上や直前にいると、★★**跳ばないとコーンに当たり、跳ぶと鳥に当たる**
			//     ＝ ★★★**避けようがない**。★だから近ければ**出さない**。
			//   ★さらに、出したあとはコーン・敵・コインの次の抽選を**先へずらして場所を予約**する
			//     （★これは `PICK_OVER_CONE` で既に使っている書き方。★新しい仕組みではない）
			if (BIRD_ON && st.goalDone) {
				st.nextBird -= moved;
				if (st.nextBird <= 0) {
					var birdAt = worldX() + W + 4;
					var away = birdKeepAway();
					// ★★扉の前後は何も置かない／★地上の障害物のそばには置かない
					if (!inNoSpawn(birdAt) && !groundObstacleNear(birdAt, away)) {
						st.cones.push({ x: W + 4, wx: birdAt, kind: "bird" });
						st.birdsBorn++;
						// ★★場所を予約する（★このあと地上の障害物が割り込むのを防ぐ）
						var hold = away + BIRD_W;
						st.nextCone  = Math.max(st.nextCone,  hold);
						st.nextEnemy = Math.max(st.nextEnemy, hold);
						st.nextPick  = Math.max(st.nextPick,  hold);
						st.nextBird = nextBirdGap();
					} else {
						// ★置けなかった。★すこし進んで、また試す
						st.nextBird = away;
					}
				}
			}

			// ============================================================
			// ★★★扉と鍵（2026-08-16 / Phase C）
			//
			//   ★★扉は「決まった距離」に**1回だけ**立っている。
			//     ★種（シード）では決めない ＝ 既存の決まり「障害物は種で決めない」を守る。
			//     ★★同じ場所なら誰が来ても同じなので、
			//       **「前は開けられなかった扉を開けた」**がちゃんと残る
			// ============================================================
			// ============================================================
			// ★★★★拾えるコインの弧（2026-08-23 島さんの指定）
			//
			//   ★★**1000m から**出はじめる（★島さんの指定）。
			//   ★★★**障害物と重ねない**（★避けるのと拾うのが同時に来ないように）
			// ============================================================
			if (PICK_ON && COIN_ICON && meters() >= PICK_FROM_M) {
				st.nextPick -= moved;
				if (st.nextPick <= 0) {
					var pat = pickPattern(st.pickBeat);
					var row = pickRow(pat), rowW = Math.max(PICK_FOOTPRINT, pickRowW(row));
					// ★★次の障害物まで、列がまるごと入る余裕があるときだけ置く
					var room = Math.min(st.nextCone, st.nextEnemy);
					// ★★★扉の前後は何も置かない（2026-08-23 島さんの指定。★「など」に含む）
					var pickWx = worldX() + W + 4;
					var pickClear = !inNoSpawn(pickWx) && !inNoSpawn(pickWx + rowW);
					if (pat.rest) {
						st.pickBeat++; st.pickQuiet = true; st.nextPick = nextPickGap() + PICK_REST_EXTRA;
					} else if (row.length && pickClear && room > rowW + CONE_W * 2 && st.picks.length + row.length <= PICK_MAX) {
						// ★★★水平に並べる（→ `makeRow()`）
						var made = makeRow(W + 4, pat);
						if (!pickRowAllowed(made)) made = [];
						if (!made.length) { st.nextPick = CONE_W * 4; }
						else {
						for (var pi = 0; pi < made.length; pi++) st.picks.push(made[pi]);
						st.picksBorn++;
						st.pickBeat++; st.pickQuiet = false;
						st.nextPick = nextPickGap();
						}
					} else {
						// ★★置けなかったら、少し待ってもう一度ためす（★間隔は崩さない）
						st.nextPick = CONE_W * 4;
					}
				}
			}

			// ============================================================
			// ★★★★ゴールの扉（2026-08-22 島さんの指定）
			//
			//   ★決まった距離に**1回だけ**立つ（★種では決めない ＝ 既存の決まり）。
			//   ★★置き方は下の「扉」とまったく同じ（★通り過ぎさせない）。
			//   ★★★`GATE_ON`（保留中）の**外**に置いてあります。混ぜないこと
			// ============================================================
			if (GOAL_ON && !st.goalBorn && !st.goalDone) {
				// ★★★**足の列に届いた瞬間に、距離がちょうど 5000m になる**ように置く。
				//   ★主役は画面の左（`RIDER_X`）にいるので、扉の世界座標を
				//     **足の分だけ右へずらす**（★ずらさないと 9996m で着いてしまい、
				//     ★★画面の数字と「5000m」の文字が食い違う）
				var goalWx = GOAL_M * SCORE_DOTS + RIDER_X + RIDER_FOOT;
				var gEdge = worldX() + W + 4;
				if (gEdge >= goalWx) {
					st.goalBorn = true;                // ★この位置は一度きり
					var gx3 = W + 4 - (gEdge - goalWx);
					// ★★もう足より左＝通り過ぎている場所なら、右端に寄せ直して**必ず置く**
					//   （★捨てるとゴールを素通りできてしまう。★扉と同じ考え方）
					if (gx3 <= RIDER_X + RIDER_FOOT) gx3 = W + 4;
					st.cones.push({ x: gx3, wx: goalWx, kind: "goal" });
				}
			}

			if (GATE_ON) {
				// --- 扉 ---
				if (!st.gateBorn) {
					var gateWx = GATE_M * SCORE_DOTS;      // ★世界のこの位置に立っている
					var edge = worldX() + W + 4;           // ★画面の右の外
					if (edge >= gateWx) {
						st.gateBorn = true;                // ★この位置は一度きり
						// ★★画面の右外に「まだ届いていない分」だけ右に置く
						//   （★一気に近づいたときも、めり込まない）
						var gx = W + 4 - (edge - gateWx);
						// ★★★もう主役の足より左＝**通り過ぎている場所**になっていたら、
						//   **画面の右端に寄せ直して必ず置く**（★捨てない）。
						//   ★ふつうに走っていれば必ず右端から来るので、ここは通らない
						//     （1コマ 208ドット以上進んだときだけ。★いまの最速は 5.3ドット）。
						//   ★★捨ててしまうと**扉を素通りできてしまう**ので、
						//     「置き場所がずれる」より「必ず立ちはだかる」を優先する
						if (gx <= RIDER_X + RIDER_FOOT) gx = W + 4;
						st.cones.push({
							x: gx, wx: gateWx, kind: "gate",
							// ★★**「持っているだけ」では開いた姿にしない。**
							//   突破した瞬間に `opened` を立てる（→ 下の「越えた」判定）
							// ★★★ただし**一度自分で開けた扉は、次のランからは開いたまま**。
							//   ★これが無いと、毎ラン同じ壁に見えて**進歩の痕跡が残らない**
							//   （2026-08-16 のレビュー H-2）
							opened: hasItem("gateOpened")
						});
						st.gateSeen = true;
						// ★★★「扉を見た」を**永久に覚える**。
						//   ★これが鍵を出す門番になる（→ `KEY_MIN_M` の上の説明）
						//   ★★覚えないと、毎ラン「見たことがない」に戻って鍵が出ない
						giveItem("sawGate");
					}
				}
					// --- ★★キャンプ（2026-08-16 / Phase D）---
				//   ★★決まった距離ごとに立っている。★種では決めない（扉と同じ考え方）
				if (CAMP_ON) {
					var campWx = (st.campBorn + 1) * CAMP_M * SCORE_DOTS;
					var cEdge = worldX() + W + 4;
					if (cEdge >= campWx) {
						st.campBorn++;
						var cx2 = W + 4 - (cEdge - campWx);
						// ★通り過ぎている場所なら置かない（★キャンプは「行き止まり」ではないので捨ててよい）
						if (cx2 > RIDER_X + RIDER_FOOT) {
							st.cones.push({ x: cx2, wx: campWx, kind: "camp" });
						}
					}
				}

				// --- 鍵 ---
				//   ★★★**扉を見たことがある**ときだけ出る（→ 上の `KEY_MIN_M` の説明）
				//     ・見る前は出ない → 「何だこれ？」が先に来る（★輪が逆転しない）
				//     ・見たあとは手前に出る → 拾える（★輪が閉じる）
				//   ★★まっすぐな道かどうかは**見ない**（鍵は障害物ではないので、丘にもある）
				st.nextKey -= moved;
				if (st.nextKey <= 0) {
					var keyAt = worldX() + W + 4;
					if (hasItem("sawGate") && !hasItem("key") &&
						metersOf(keyAt) >= KEY_MIN_M && Math.random() < KEY_RATE) {
						st.cones.push({ x: W + 4, wx: keyAt, kind: "key" });
						st.keysBorn++;
					}
					st.nextKey = KEY_TRY_GAP;             // ★次に抽選するまでの距離
				}
			}

			var foot = RIDER_X + RIDER_FOOT;
			for (var i = st.cones.length - 1; i >= 0; i--) {
				var c = st.cones[i];
				var cw = obWidth(c);
				c.x -= moved;

				// ============================================================
				// ★★★扉と鍵は「足に届いた瞬間」に決める（2026-08-16 / Phase C）
				//
				//   ★★なぜ `hitConeIndex()` に任せないのか:
				//     あちらは「**いま重なっているか**」しか見ない。
				//     ★速さが上がると 1コマで扉の幅（13ドット）以上進むので、
				//       **重なったコマが1度も来ずにすり抜ける**。
				//     ★★扉は「鍵が無ければ絶対に通れない」ものなので、すり抜けは致命的。
				//   → **足の列に届いた最初のコマで、必ず1回だけ決める。**
				// ============================================================
				if (!c.resolved && (c.kind === "gate" || c.kind === "key" || c.kind === "camp" ||
					c.kind === "goal") &&
					Math.round(c.x) <= foot) {
					c.resolved = 1;
					// ★★★★ゴールの扉 ＝ **鍵は要らない。必ず開く**（2026-08-22）
					if (c.kind === "goal") { reachGoal(c); return; }   // ★★世界を止める
					if (c.kind === "camp") { reachCamp(c); return; }   // ★★世界を止める
					if (c.kind === "key") takeKey(c);
					else if (hasItem("key")) passGate(c);   // ★★鍵を**使った**瞬間
					else blockedByGate(c);                  // ★行き止まり
				}

				// ★★足の位置を通り過ぎた ＝ 越えた（★ここでコインが入る）
				//   ★扉と鍵は上で決めてあるので、ここでは何もしない
				if (!c.passed && Math.round(c.x) + cw < foot) {
					c.passed = 1;
					// ★★★★飛ぶ敵は `BIRD_COIN = 0` で、コインを止められる（2026-08-23）
					//   ★見返りが無いと、★★鳥は**ただの罰**になるので 1 にしてある
					if (c.kind === "bird") { if (BIRD_COIN) gainCoin(curCoinPer()); }
					// ============================================================
					// ★★★★★レールは**ここでは1枚も入らない**（2026-09-02 島さんの指摘）
					//
					//   > **島さん「レールを素通りしてもポイントが稼げるのなんで」**
					//
					//   ★★**8/31 の消し忘れ**でした。★レールは作った当日、
					//     ★★★はじめは**ぶつかる障害物**でしたが、同じ日に島さんの指定で
					//       「★障害物でない。素通り可」に変えました。
					//     ★★そのとき**当たり判定は外したのに、ここの払い出しを外し忘れ**ました。
					//
					//   ★★★ここのコインは「**危ないものを越えた**」ごほうびです。
					//     ★レールはぶつからないので、素通りに**危険も手間もありません**。
					//     ★★払うと「**何もしないで18枚**」になり、
					//       ★★★**乗る意味（110枚）が薄まります**。
					//
					//   ★レールで稼ぐ道は**乗ることだけ**（→ `updateGrind`）
					// ============================================================
					else if (c.kind !== "gate" && c.kind !== "key" && c.kind !== "camp" &&
						c.kind !== "goal" && c.kind !== "rail") {
						gainCoin(curCoinPer());
						// ============================================================
						// ★★★★★越えたモンスターを数える（2026-09-04 島さんの指定）
						// ============================================================
						//
						//   ★★★**払うのと同じ場所で数えること。**
						//     ★離すと「片方だけ直す」事故が起きます。
						//     ★★2026-09-02、レールで**当たり判定は外したのに
						//       払い出しを外し忘れた**のが、まさにこの罠でした。
						//
						//   ★数えるのは**モンスターだけ**（★コーンは障害物であって
						//     ★★モンスターではありません ＝ `MONSTERS` の表に無い）
						countMet(c.kind);
					}
				}
				if (c.x + cw < 0) st.cones.splice(i, 1);
			}
			// ============================================================
			// ★★★★レール（2026-08-31 島さんの指定）
			//
			//   ★★**ぶつかるものとは別に見る**（★拾えるコインとまったく同じ形）。
			//     ★`hitConeIndex()` は「低いときだけ当たる」ように直してあるので、
			//     ★★ここでは「**合っていれば乗る**」だけを見ます
			// ============================================================
			updateGrind(moved);      // ★乗っているあいだ（★コインが増え続ける）
			tryGrind();              // ★乗れるか（★足の高さが合っていれば）

			// ============================================================
			// ★★★★拾えるコインを動かす・拾う（2026-08-23 島さんの指定）
			//
			//   ★★**ぶつかるものではない**ので、`hitConeIndex()` とは別に見る。
			//
			//   ★★★**足の高さで拾う**（★体ぜんぶで拾うと、★走っているだけで取れてしまう。
			//     ★2026-08-23 に実際そうなって直した）。
			//   ★★これで「**跳んだ道に沿って置いたコインは、跳べば取れる**」が
			//     ★そのまま成り立つ（★弧は島さんの跳躍の絵から作っているので）
			// ============================================================
			if (PICK_ON) {
				// ★★★コインは**画面の行**で持っているので、主役の足も行で見る（2026-08-23）
				var myRow = riderGroundRow() - 1 - currentLift();
				var boxL = RIDER_X + st.cornerShift, boxR = boxL + RIDER_FOOT * 2;
				var magnet = magnetRadius(), magnetX = (boxL + boxR) / 2;
				// ============================================================
				// ★★★★★グラインド中は「**体に触れたら取れる**」（2026-09-02 島さんの指摘）
				//
				//   > **島さん「グラインド中コインに接触しても取得できん。直して。」**
				//
				//   ★★ふだんは**足の高さ**で拾います（2026-08-23 島さんの指定）。
				//     ★理由は「★★体ぜんぶだと、**走っているだけで取れて**しまう」から。
				//     ★★★この決まりは**地上ではいまも生きています**（★テストが見張る）。
				//
				//   ★★ところがレールの上では、その決まりが**成り立ちません**:
				//
				//       ★コインの高さ    … 地面から **24〜27ドット**（★オーリーの頂点に合わせてある）
				//       ★★グラインド中の足 … 地面から **10〜17ドット**（★レールの高さ）
				//       → ★★★差が **10〜13ドット** ＝ 拾える余裕（±8）を**必ず超える**
				//
				//   ★★★★実測: ★**体に重なったコインの 100% が取れませんでした**。
				//     ★レールの上では高さを変えられない（★跳んだら降りてしまう）ので、
				//     ★★**足の高さを合わせようがありません** ＝ 決まりが機能しない場面です。
				//
				//   → ★★乗っているあいだだけ、**絵に重なったら取る**（★見たとおりになる）。
				//     ★★★地上の決まりは1ドットも変えていません
				var grindTop = 0;
				// ★★★★★主役の絵の上端（頭）。★いつでも出しておく
				//   ★★前はグライン中だけ出していましたが、
				//   ★★★2026-09-12 から**いつでも体で拾う**ので、ここで決めます
				var HPose = currentPose();
				var HFrm = (HPose && HPose.art && HPose.art.FRAMES)
					? HPose.art.FRAMES[currentFrame()] : null;
				var bodyTop = HFrm ? (myRow - (HFrm.rows.length - 1)) : myRow;
				if (st.grind) grindTop = bodyTop;
				var kept = 0, collected = 0;
				for (var qi = 0; qi < st.picks.length; qi++) {
					var pk = st.picks[qi];
					if (pk.taken) continue;
					pk.x -= moved;
					if (magnet > 0 && pk.x < W) {
						var mx = magnetX - pk.x, my = myRow - pk.y;
						var distance2 = mx * mx + my * my;
						if (pk.attracted || distance2 <= magnet * magnet) {
							pk.attracted = true;
							pk.pullAge = (pk.pullAge || 0) + dt;
							pk.trailX = pk.x; pk.trailY = pk.y;
							var distance = Math.sqrt(distance2);
							// A gentle start, then a clear accelerating convergence. No orbit / random jitter.
							var ramp = 0.45 + 1.55 * Math.min(1, pk.pullAge / 0.24);
							var amount = pk.pullAge > 0.8 ? 1 : Math.min(1, (100 * dt + moved * 2) * ramp / Math.max(1, distance));
							pk.x += mx * amount; pk.y += my * amount;
						}
					}
					// Latched coins remain alive behind the rider / screen until they arrive.
					if (pk.x + PICK_W < 0 && !pk.attracted) continue;
					var px = Math.round(pk.x);
					// ★★★★縦の判定。★グラインド中だけ「絵に重なったか」で見る
					//   ★コインは `pk.y` が**下端**なので、上端は `pk.y - (PICK_H - 1)`
					// ============================================================
					// ★★★★★縦の判定 ―― **絵が重なったら取れる**（2026-09-12 島さんの指定）
					// ============================================================
					//
					//   > **島さん「接触しているが取得できんコインがある。
					//   >   ジャンプせずに届くパターンのコインです。」**
					//
					//   ★実測（直す前）: ★★足で拾えるのは地面から **0〜8ドット**、
					//     ★主役の背は **25ドット**。
					//     → ★★★**9〜25 ドットは「体は当たるのに拾えない」帯**でした。
					//     ★並びのいちばん下の段は 13・17・19 ドット ＝ **全部この帯の中**。
					//
					//   ★★★島さんの決定（2026-09-12）: **触れたら取れる**。
					//     ★いちばん下の段 … 走るだけで取れる
					//     ★★２段目以降 … **跳んだ高さだけ**取れる（★跳ぶ理由はこちらへ移った）
					//
					//   ★★★★グライン中は 2026-09-02 からすでにこの形でした。
					//     → ★**判定を 1 本にまとめました**（★★同じことを 2 か所に書かない）。
					//
					//   ★`PICK_TAKE_Y` は、★★**足より少し下**にあるコインを拾うために残してあります
					//     （★列は水平なので、★★坂では足がコインより上に来ることがある）。
					var vHit = (pk.y >= bodyTop) &&
						(pk.y - (PICK_H - 1) <= myRow + PICK_TAKE_Y);
					if (px + PICK_W > boxL && px < boxR && vHit) {
						pk.taken = 1;
						st.picksGot++;
						// ★★その場で財布に入る（★越えたときと同じ道）。
						//   ★★★音だけは「チャリーン」に分けてある（2026-08-23 島さんの指定）
						collected++;
					}
					if (!pk.taken) st.picks[kept++] = pk;
				}
				st.picks.length = kept;
				if (collected) gainCoin(pickValue(), "pick", collected);
			}

			// ★★当たり判定。★★**転ばない。** 減速＋倍率リセット＋スタミナ減だけ
			var hi = hitConeIndex();
			if (hi >= 0) onHit(hi);
		}
		updateRecover(st.hits === hitsBeforeMove ? moved / SCORE_DOTS : 0, dt);
		// ★技: 島さんの絵を js/frames.js の時間どおりに送る。物理の計算は無い
		//   ★★JUMP のアップグレードはここで効く ＝ **コマの進みが遅くなる**
		//     → 同じ絵をゆっくり再生 → 滞空が伸びる → 越えられる幅が広がる
		//   ★★★絵も `js/frames.js` の表も1つも変えていない
		if (st.air >= 0) {
			st.air += dt * 1000 / jumpDurationMul();
			// Check the new pose as well: a descending frame must not skip a rail top.
			if (FR.frameAt(POSES[st.trick].ms, st.air) >= 0) tryGrind();
			if (!st.grind && FR.frameAt(POSES[st.trick].ms, st.air) < 0) {
				liveLanding();
				st.air = -1;
				st.grindGrace = null; st.airJumps = 0;
				st.djBase = 0;                   // ★★下駄をはずす（2026-08-22）
				// ★★★★着地のけむり（2026-08-31）。★**跳ぶときと対になる反応**
				//   ★桜井資料「操作したのに無反応の状態を作らない」
				//     （出典: ノーリアクションを排除せよ）
				addLandDust();
				landSound();
				// ★★着地したあと、たまにそのままプッシュへ（島さんの指定。そのほうが自然）
				st.idle = (Math.random() < PUSH_AFTER_TRICK) ? I_PUSH : I_STANDBY;
				st.idleMs = 0;
				st.nextPush = nextPushWait();
			}
		} else {
			updateIdle(dt);
		}
		consumeBufferedAction();
	}

	// ------------------------------------------------------------
	// ■ 描く
	//   ★上から順に: 背景 → 地面 → スケーター → 距離
	// ------------------------------------------------------------
	// 絵を1コマ描く。**技もコーンも同じ道具で描く**
	//   ox / oy = 画面のどこに置くか（絵の左上）
	function drawArt(f, ox, oy) {
		var rows = f.rows;
		for (var r = 0; r < rows.length; r++) {
			var line = rows[r], y = oy + r;
			if (y < 0 || y >= H) continue;
			var c = 0;
			// 横に続く同じ色はまとめて塗る（1ドットずつ塗ると重くなる）
			while (c < line.length) {
				var ch = line.charAt(c);
				if (ch === ".") { c++; continue; }
				var run = 1;
				while (c + run < line.length && line.charAt(c + run) === ch) run++;
				ctx.fillStyle = GB[global.DotPalette.indexOfChar(ch)];
				ctx.fillRect(ox + c, y, run, 1);
				c += run;
			}
		}
	}

	// ★★★★地面の際（草の表面）の絵を置く（2026-08-25）
	//
	//   ★★**どこに何を置くかは「種と区画」から、その場で計算します**
	//     （★絵は数枚しか持たないので、★★何万メートル走っても重くなりません）。
	//   ★★★**絵は地面の表面に沿います**（★起伏のとおりに上下する）。
	//   ★透明のところは、下に塗ってある土がそのまま見えます。
	//
	//   ★★継ぎ目について: どの絵も**左端と右端の厚みが同じ**なので
	//     （`tools/edge2art.js` が毎回測って止めます）、
	//     ★★★**どの絵がとなり合っても段差が作れません**。
	function drawEdgeArt(gx) {
		var E = global.DotEdgeArt;
		if (!E) return;
		var PALX = global.DotPalette;
		// ★★★★★草も「段ごとに1枚の絵」にして貼る（2026-09-12）
		//   ★実測（★直す前）: **1,542回 塗って 1,800ドット** ＝ 1回あたり **1.2ドット**。
		//   ★★草は1ドットずつ生えているので、縦にまとめてもほとんど続きません。
		//   ★★★土とまったく同じ直し方です（→ `sheetTile`）。
		var eRun = null;
		function flushEdge() {
			if (!eRun) return;
			ctx.drawImage(eRun.tile.cv, eRun.col, 0, eRun.n, E.H, eRun.c, eRun.top, eRun.n, E.H);
			eRun = null;
		}
		for (var c = 0; c < W; c++) {
			var wx = gx + c;
			var seg = Math.floor(wx / E.W);                  // ★区画の番号
			var idx = Math.floor(WD.rand(seg, EDGE_SALT) * E.SHEETS.length);
			if (idx < 0) idx = 0;
			if (idx >= E.SHEETS.length) idx = E.SHEETS.length - 1;
			// ★★★★AIへ: ここに「横ずらし」を入れないこと（2026-08-25 に試して却下）
			//   ★土（drawSoilArt）には入れてあるが、★★**草には使えません**。
			//   ★草は「**両端の厚みがそろっている**」ことで継ぎ目を消しているので、
			//     ★★★途中から読むと**厚みが合わず、段差が8ドット出ました**（★実測）。
			//   ★しかも繰り返しは 4.99 → 3.25倍にしか下がらず、割に合わなかった。
			var col = wx - seg * E.W;                        // ★絵の中の何列目か
			var rows = E.SHEETS[idx];
			var top = groundRowAt(c);
			var gm = gmapAt(c);                              // ★★地域ごとの色の置き換え
			var tile = sheetTile(edgeTiles, E, idx, gm, gmapKey(gm));
			if (tile) {
				// ★となりの列と「同じ段・同じ色・同じ高さ・絵の続き」なら、まとめて1回
				if (eRun && eRun.tile === tile && eRun.top === top &&
					eRun.col + eRun.n === col && eRun.c + eRun.n === c) {
					eRun.n++;
				} else {
					flushEdge();
					eRun = { tile: tile, col: col, c: c, top: top, n: 1 };
				}
				continue;
			}
			flushEdge();
			// ★絵が作れない場所（★古いブラウザ）は、いままでどおり1ドットずつ
			//   ★縦に続く同じ色はまとめて塗る
			var y = 0;
			while (y < E.H) {
				var ch = rows[y].charAt(col);
				if (ch === ".") { y++; continue; }
				var run = 1;
				while (y + run < E.H && rows[y + run].charAt(col) === ch) run++;
				ctx.fillStyle = GB[gidx(gm, PALX.indexOfChar(ch))];
				ctx.fillRect(c, top + y, 1, run);
				y += run;
			}
		}
		flushEdge();
	}

	// ★★★★土（地面の本体）の模様を置く（2026-08-25）
	//
	//   ★★**草の下端から**始めます（★列ごとに、草の絵がどこまで届いているかを見る）。
	//   ★下は体力バーの上まで。★足りないところで切られますが、
	//     ★★★絵の下端が土の基本の色なので、**その先の無地とつながります**。
	// ============================================================
	// ★★★★★土の模様は「段ごとに1枚の絵」にして、貼る（2026-09-12）
	// ============================================================
	//
	//   > **島さん「遅延がある。直ちに原因と対策を」**
	//
	//   ★実測（★本物のブラウザで、1コマを 400 回まわして測った）:
	//
	//   ```
	//   1コマ 4.61ms のうち、★★**塗りそのもの（fillRect）が 3.11ms ＝ 67%**
	//   1コマの fillRect  9,979 回 … ★★★そのうち **土が 5,556 回（56%）**
	//   ```
	//
	//   ★土は**粒**なので、縦にまとめても1〜2ドットずつしか続きません。
	//   ★★だから列ごとに 23 回ほど塗っていて、★★★**240 列 × 23 ＝ 5,556 回**でした。
	//
	//   ★★★★**直し方: 段（シート）を1枚の絵にして持っておき、そこから貼る。**
	//     ★1列につき **1回**（`drawImage`）。★★となりの列と条件が同じなら**まとめて1回**。
	//     ★★★**出るドットは1つも変わりません**（★お手本＝golden が見張っています）。
	//
	//   ★絵は「段 × 地域の色」ごとに1枚だけ作って、あとは使い回します
	//     （★地域の色は移り変わりの途中でも数種類しかありません）。
	//   ★★裏の板が作れない場所（★古いブラウザなど）では、
	//     ★★★**今までどおり1ドットずつ塗ります**（`SOIL_TILE_ON = 0` でも同じ）。
	var SOIL_TILE_ON = 1;          // ★0 にすると、2026-09-11 までの塗り方に戻る
	var soilTiles = {};            // ★段 x 地域の色 -> 裏の板（土）
	var edgeTiles = {};            // ★★同じもの（草）
	var soilTileKeys = null;

	function makeOffscreen(w, h) {
		var doc = global.document;
		if (!doc || !doc.createElement) return null;
		var cv = doc.createElement("canvas");
		if (!cv || !cv.getContext) return null;
		cv.width = w; cv.height = h;
		var c2 = cv.getContext("2d");
		return c2 ? { cv: cv, ctx: c2 } : null;
	}

	// ★★地域の色の入れ替え表に、短い名前をつける（★同じ表なら同じ絵を使い回すため）
	function gmapKey(gm) {
		if (!gm) return "-";
		if (!soilTileKeys) soilTileKeys = [];
		for (var i = 0; i < soilTileKeys.length; i++) if (soilTileKeys[i] === gm) return "g" + i;
		soilTileKeys.push(gm);
		return "g" + (soilTileKeys.length - 1);
	}

	// ★★★段 `idx` を、地域の色 `gm` で塗った1枚の絵（★なければ作る）
	//   ★★★★**土も草も、これ1つを通します**（★同じ処理を2か所に書かない ＝ この作品の決まり）。
	//   ★`.`（透明）は塗らないので、★★草の下から土がそのまま見えます。
	function sheetTile(store, A, idx, gm, key) {
		if (!SOIL_TILE_ON) return null;
		var id = idx + "|" + key;
		var hit = store[id];
		if (hit !== undefined) return hit;
		var off = makeOffscreen(A.W, A.H);
		if (!off) { store[id] = null; return null; }
		var PALX = global.DotPalette, rows = A.SHEETS[idx];
		for (var x = 0; x < A.W; x++) {
			var y = 0;
			while (y < A.H) {
				var ch = rows[y].charAt(x);
				if (ch === ".") { y++; continue; }        // ★透明はそのまま
				var run = 1;
				while (y + run < A.H && rows[y + run].charAt(x) === ch) run++;
				off.ctx.fillStyle = GB[gidx(gm, PALX.indexOfChar(ch))];
				off.ctx.fillRect(x, y, 1, run);
				y += run;
			}
		}
		store[id] = off;
		return off;
	}

	function drawSoilArt(gx) {
		var S = global.DotSoilArt, E = global.DotEdgeArt;
		if (!S) return;
		var PALX = global.DotPalette;
		// ★★★★2026-08-25、島さん「体力バーの上も先ほどの一色になっています」
		//   ★体力バーの絵には**透明なところが1599ドット**あり、
		//   ★★そこから**下の地面が見えます**。
		//   ★★★だから土の模様は「バーの上まで」ではなく、**画面のいちばん下まで**描く
		//     （★前は barTop() までで止めていたので、★そこだけ一色に見えていた）
		var bottom = H;
		var eb = edgeBottoms();                // ★草の下端（段ごと・列ごと）
		// ★★★★★となり合う列を**まとめて 1 回で貼る**ための覚え書き（2026-09-12）
		var run = null;
		function flushSoil() {
			if (!run) return;
			ctx.drawImage(run.tile.cv, run.col, 0, run.n, run.lim, run.c, run.top, run.n, run.lim);
			run = null;
		}
		for (var c = 0; c < W; c++) {
			var wx = gx + c;
			// ★草がどこまで届いているか（★草の絵を使っていなければ、種の太さで測る）
			var off = 0;
			if (eb && E) {
				var eseg = Math.floor(wx / E.W);
				var ei = Math.floor(WD.rand(eseg, EDGE_SALT) * E.SHEETS.length);
				if (ei < 0) ei = 0;
				if (ei >= E.SHEETS.length) ei = E.SHEETS.length - 1;
				off = eb[ei][wx - eseg * E.W];
			} else {
				off = WD.edgeThickAt(wx);
			}
			var top = groundRowAt(c) + off;
			if (top >= bottom) continue;
			var gm = gmapAt(c);                              // ★★地域ごとの色の置き換え

			var seg = Math.floor(wx / S.W);
			var idx = Math.floor(WD.rand(seg, SOIL_SALT) * S.SHEETS.length);
			if (idx < 0) idx = 0;
			if (idx >= S.SHEETS.length) idx = S.SHEETS.length - 1;
			// ★★★★区画ごとに「絵のどこから読むか」を横にずらす（2026-08-25）
			//   > 島さん「繰り返しているのがわかりすぎて違和感」
			//   ★段を選ぶだけだと、★★**64ドットごとに同じ模様が同じ位置に来ます**
			//     （★実測 1.63倍。★ずらしを入れて 1.0倍近くになる）。
			//   ★★土は粒状なので、どこでつないでも継ぎ目は見えません
			var sft = Math.floor(WD.rand(seg, SOIL_SALT + 7) * S.W);
			var col = ((wx - seg * S.W) + sft) % S.W;
			var rows = S.SHEETS[idx];
			var lim = Math.min(S.H, bottom - top);
			// ★★★★★段の絵があれば、そこから**まとめて貼る**（2026-09-12）
			//   ★となりの列と「同じ段・同じ地域の色・同じ高さ・絵の続き」なら、
			//   ★★**1回の `drawImage` にまとめます**（★呼び出しをさらに減らす）
			var key = gmapKey(gm);
			var tile = sheetTile(soilTiles, S, idx, gm, key);
			if (tile) {
				if (run && run.tile === tile && run.top === top && run.lim === lim &&
					run.col + run.n === col && run.c + run.n === c) {
					run.n++;
				} else {
					flushSoil();
					run = { tile: tile, col: col, c: c, top: top, lim: lim, n: 1 };
				}
			} else {
				flushSoil();
				// ★絵が作れない場所（★古いブラウザ）は、いままでどおり1ドットずつ
				var y = 0;
				while (y < lim) {
					var ch = rows[y].charAt(col);
					var r1 = 1;
					while (y + r1 < lim && rows[y + r1].charAt(col) === ch) r1++;
					ctx.fillStyle = GB[gidx(gm, PALX.indexOfChar(ch))];
					ctx.fillRect(c, top + y, 1, r1);
					y += r1;
				}
			}
			// ★★★★絵より下は、**絵の「下のほう」を縦に繰り返す**（2026-08-25）
			//   > 島さん「下端が一色なの気になります」→ ★1色をやめて繰り返しにした
			//   > 島さん「繰り返しているのがわかりすぎて違和感」
			//     → ★★★**繰り返すたびに、別の段を使い、横にもずらす**
			//
			//   ★これで縦にも横にも変化が出るので、★★同じ模様が真下に並びません。
			//   ★上のほう（草のすぐ下の影）は繰り返しません（★何度も影が出て不自然）
			var rep = Math.min(SOIL_REPEAT, S.H);
			var depth = bottom - top;
			var yy = S.H;
			while (yy < depth) {
				var repI = Math.floor((yy - S.H) / rep);       // ★何回目の繰り返しか
				var i2 = (idx + repI + 1) % S.SHEETS.length;   // ★段を変える
				var sh2 = S.SHEETS[i2];
				var col2 = ((col + repI * SOIL_SHIFT) % S.W + S.W) % S.W; // ★横にずらす
				var repEnd = Math.min(depth, S.H + (repI + 1) * rep);
				var srcTop = S.H - rep + ((yy - S.H) % rep);
				var t2 = sheetTile(soilTiles, S, i2, gm, key);
				if (t2) {
					// ★★ひと繰り返しぶんは、絵の**縦に続いた一切れ**なので1回で貼れる
					ctx.drawImage(t2.cv, col2, srcTop, 1, repEnd - yy, c, top + yy, 1, repEnd - yy);
					yy = repEnd;
					continue;
				}
				var ch2 = sh2[srcTop].charAt(col2);
				// ★まとめるのは「同じ繰り返しの中」だけ（★またぐと段も横位置も変わる）
				var run2 = 1;
				while (yy + run2 < repEnd) {
					var s2 = S.H - rep + ((yy + run2 - S.H) % rep);
					if (sh2[s2].charAt(col2) !== ch2) break;
					run2++;
				}
				ctx.fillStyle = GB[gidx(gm, PALX.indexOfChar(ch2))];
				ctx.fillRect(c, top + yy, 1, run2);
				yy += run2;
			}
		}
		flushSoil();
	}

	// ★★★★めずらしい草（根が垂れている絵）を置く（2026-08-25 島さんの指定）
	//
	//   ★区画ごとに `EDGE_RARE_RATE` の割合で出ます。
	//   ★★**絵の上端が地面の表面**に来ます（★ふつうの草と同じ高さから始まる）。
	//   ★★★透明のところは、ふつうの草と土がそのまま見えます。
	//     ★だから「ふつうの草の上に、ときどき根が生えている」ように見えます。
	function drawRareEdge(gx) {
		var A = global.DotEdgeRareArt;
		if (!A || EDGE_RARE_RATE <= 0) return;
		var PALX = global.DotPalette;
		for (var c = 0; c < W; c++) {
			var wx = gx + c;
			var seg = Math.floor(wx / A.W);
			// ★この区画に出るか（★種で決まるので、戻れば同じところに出る）
			if (WD.rand(seg, EDGE_RARE_SALT) >= EDGE_RARE_RATE) continue;
			var col = wx - seg * A.W;
			var top = groundRowAt(c);
			var gm = gmapAt(c);                              // ★★地域ごとの色の置き換え
			// ★縦に続く同じ色はまとめて塗る
			var y = 0;
			while (y < A.H) {
				var ch = A.rows[y].charAt(col);
				if (ch === ".") { y++; continue; }
				var run = 1;
				while (y + run < A.H && A.rows[y + run].charAt(col) === ch) run++;
				if (top + y < H) {
					ctx.fillStyle = GB[gidx(gm, PALX.indexOfChar(ch))];
					ctx.fillRect(c, top + y, 1, Math.min(run, H - (top + y)));
				}
				y += run;
			}
		}
	}

	// ★★草の絵の「列ごとの下端」（★1回だけ数えて覚えておく）
	//   ★毎コマ数えると無駄なので、最初に1度だけ作ります
	var _edgeBottoms = null;
	function edgeBottoms() {
		var E = global.DotEdgeArt;
		if (!E) return null;
		if (_edgeBottoms) return _edgeBottoms;
		_edgeBottoms = [];
		for (var s = 0; s < E.SHEETS.length; s++) {
			var arr = [];
			for (var x = 0; x < E.W; x++) {
				var b = 0;
				for (var y = 0; y < E.H; y++) if (E.SHEETS[s][y].charAt(x) !== ".") b = y + 1;
				arr.push(b);
			}
			_edgeBottoms.push(arr);
		}
		return _edgeBottoms;
	}

	// ★★スタミナバー（★★★2026-08-23、島さんの指定で**画面のいちばん下**へ移した）
	//   > 島さん「体力バーを液晶の一番下に持って来てください」
	//   ★★**見た目だけ。** ここは何も書き換えない（読むだけ）
	//   ★★★**高さを直書きしない**（`barTop()` を通す）。
