	function barColorFor(ratio) {
		for (var i = 0; i < BAR_STEPS.length; i++) {
			if (ratio >= BAR_STEPS[i].at) return BAR_STEPS[i].color;
		}
		return BAR_STEPS[BAR_STEPS.length - 1].color;
	}

	// ★★★★バーの絵（2026-08-25、島さんが描いた）
