		// ============================================================
		// ★★★★★星の数字を、外から差し替える（2026-09-05）
		// ============================================================
		//   ★★**`tools/preview-stars.html` のためだけ**の口です。
		//     ★★★遊びの中からは1回も呼びません（★ゲームの動きは1ドットも変わりません）。
